(window.GIM_TS=window.GIM_TS||{})["Shabbat.4"]={"from":96,"a":[["\u0003נוטל את הכיסוי והן,\u0004 גיזי הצמר, \u0003נופלות\u0004 מאליהן. הרי שאף בגיזי צמר שטמנו בהם אסור לטלטל, ושלא כדברי רבא!","\u0003אלא אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר, כך נאמר],\u0006 זו היא הגירסה הנכונה, \u0003אמר רבא: לא שנו\u0004 שאין מטלטלים גיזי צמר \u0003אלא\u0004 כ\u0003שלא יחדן להטמנה. אבל\u0004 אם \u0003יחדן להטמנה\u0004 — \u0003מטלטלין אותן.\u0004","וכדברים אלה \u0003איתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 \u0003כי אתא\u0004 \u0005[\u0006ש\u0005כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יעקב\u0004 ש\u0003אמר\u0004 בשם \u0003ר' אסי בן שאול\u0004 ש\u0003אמר\u0004 בשם \u0003רבי: לא שנו\u0004 שאין מטלטלים גיזי צמר \u0003אלא\u0004 כ\u0003שלא יחדן להטמנה\u0004 מבעוד יום, \u0003אבל\u0004 אם \u0003יחדן להטמנה\u0004 — \u0003מטלטלין אותן.\u0004","\u0003רבינא אומר,\u0004 יש להבין את הדברים בדרך אחרת: \u0003בשל הפתק שנו\u0004 במשנה, שמדובר בערימה מסודרת של גיזי צמר הערוכים לקניה ומכירה, והם אכן אסורים בטלטול בשבת. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003גיזי צמר של הפתק אין מטלטלין אותן. ואם התקינן בעל הבית להשתמש בהן\u0004 — \u0003מטלטלין אותן.\u0004","בשאלה מה יש ומה אפשר לעשות בדברים של מוקצה כדי להשתמש בהם בשבת \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003רבה בר בר חנה קמיה\u0004 \u0005[לפני]\u0006 \u0003רב: חריות\u0004 (הענפים הקשים) \u0003של דקל שגדרן\u0004 (קצצם) בערב שבת לצורך שימוש בהם \u0003לעצים\u0004 להסקה או בניה, \u0003ונמלך עליהן\u0004 והחליט להשתמש בהם \u0003לישיבה\u0004 — \u0003צריך לקשר\u0004 את החריות יחד בערב שבת כדי שיהא מותר להזיזן בשבת, ככל כלי אחר מכלי הבית. \u0003רבן שמעון בן גמליאל אומר: אין צריך לקשר,\u0004 ומותר לטלטלן אף בלא קשירה. \u0003הוא\u0004 רבה בר בר חנה \u0003תני לה\u0004 \u0005[שנה אותה,\u0006 את הברייתא\u0005]\u0006 \u0003והוא אמר לה\u0004 \u0005[אותה]\u0006 והוסיף כי \u0003הלכה כרבן שמעון בן גמליאל.\u0004","באותו נושא עצמו \u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003רב אמר: קושר\u0004 אותם בערב שבת, \u0003ושמואל אמר: חושב\u0004 מבעוד יום שהוא מכינם לצורך זה, ודי בכך ואין צורך בקשירתם. \u0003ורב אסי אמר: יושב\u0004 עליהם שעה קלה מבעוד יום ואז מותר לו לשבת עליהם בשבת, \u0003אף על פי שלא קישר ואף על פי שלא חישב.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003רב הוא\u0004 ש\u0003אמר\u0004 דבריו \u0003כתנא קמא\u0004 \u0005[הראשון],\u0006 \u0003ושמואל נמי\u0004 \u0005[גם כן]\u0006 \u0003הוא\u0004 ש\u0003אמר\u0004 דבריו \u0003כרבן שמעון בן גמליאל. אלא רב אסי\u0004 ש\u0003אמר\u0004 דבריו, \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אמר? שהרי דברי רב אסי הם בניגוד לשתי דעות התנאים!","ומשיבים: \u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003יוצאין\u0004 בשבת לרשות הרבים \u0003בפקורין\u0004 \u0005[פשתן סרוק]\u0006 \u0003ובציפא\u0004 \u0005[צמר סרוק]\u0006 שמניחים על גבי פצע בשבת, \u0003בזמן שצבען\u0004 (טבל אותם) \u0003בשמן וכרכן\u0004 על גבי הפצע \u0003במשיחה.\u0004 ואם \u0003לא צבען בשמן ולא כרכן במשיחה\u0004 — \u0003אין יוצאים בהם\u0004 לרשות הרבים. \u0003ואם יצא בהם שעה אחת מבעוד יום, אף על פי שלא צבע ולא כרכן במשיחה מותר לצאת בהן\u0004 בשבת. הרי שלדעת תנא זה השימוש בדבר מבעוד יום מתיר להשתמש בו בשבת, בלא צורך בעשייה נוספת.","\u0003אמר רב אשי: אף אנן נמי תנינא\u0004 \u0005[אף אנו שנינו גם כן\u0006 מעין זה במשנתנו\u0005]:\u0006 \u0003הקש שעל גבי המטה\u0004 שהיה מונח שם בערימה להסקה או לגיבול טיט, לא \u0003ינענעו בידו\u0004 אם רצונו לסדר אותו ולשכב עליו בשבת. \u0003אבל מנענעו בגופו\u0004 שלא כדרך המקובלת (\"כלאחר יד\"). \u0003אבל אם היה עליו,\u0004 על המטה, אותו קש מוכן ל\u0003מאכל בהמה, או שהיה עליו כר או סדין\u0004 בערב שבת ושכב עליו \u0003מבעוד יום\u0004 — \u0003מנענעו בידו,\u0004 נמצא שדי בשימוש מבעוד יום כדי להכשיר לצורך שבת. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שיש דעה כזו וכמותה סובר רב אסי.","\u0003ומאן\u0004 \u0005[ומיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[שחלוק עליו]\u0006 על \u0003רבן שמעון בן גמליאל\u0004 בברייתא הראשונה ולא פורש שמו ואמר שכדי שיוכלו להשתמש בו צריך לעשות מעשה — הרי זה \u0003ר' חנינא בן עקיבא. דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003זעירי\u0004 ש\u0003אמר\u0004 בשם \u0003ר' חנינא: פעם אחת הלך ר' חנינא בן עקיבא\u0004 והגיע \u0003למקום אחד\u0004 בערב שבת, \u0003ומצא\u0004 שם \u0003חריות של דקל שגדרום לשום\u0004 (לשם) \u0003עצים. ואמר להם לתלמידיו: צאו וחשבו\u0004 עליהם לשימוש \u0003כדי שנשב עליהן למחר\u0004 בשבת בהיתר. \u0003ולא ידענא אי\u0004 \u0005[ואיני יודע אם]\u0006 \u0003בית המשתה\u0004 של חתונה \u0003הוה\u0004 \u0005[היה]\u0006 זה שבא אליו ר' חנינא, \u0003אי\u0004 \u0005[אם]\u0006 \u0003בית האבל הוה\u0004 \u0005[היה]\u0006 זה.","ומסבירים: \u0003מדקאמר אי\u0004 \u0005[ממה שאמר אם]\u0006 \u0003בית המשתה הוה\u0004 \u0005[היה]\u0006 זה \u0003אי\u0004 \u0005[אם]\u0006 \u0003בית האבל הוה\u0004 \u0005[היה]\u0006 נלמד כי הלכה זו נאמרה \u0003דוקא\u0004 ב\u0003בית האבל או\u0004 ב\u0003בית המשתה דטרידי\u0004 \u0005[ש\u0006הם \u0005טרודים]\u0006 ואין סיפק בידם לקשור את העצים, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בכל מקרה אחר, אם \u0003קשר\u0004 אותם יחד — \u0003אין\u0004 \u0005[כן],\u0006 מותר להשתמש בו בשבת, ואולם אם \u0003לא קשר\u0004 — \u0003לא.\u0004","\u0003אמר רב יהודה: מכניס אדם\u0004 בערב שבת \u0003מלא קופתו\u0004 (סלו) \u0003עפר\u0004 לביתו ושופכו על רצפת ביתו, \u0003ועושה בה כל צרכו\u0004 בשבת. \u0003דרש מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003מר זוטרא רבה\u0004 \u0005[הגדול]:\u0006 \u0003והוא שיחד לו\u0004 לעפר בביתו \u0003קרן זוית.\u0004","\u0003אמרו רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב פפא: כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 נאמרה הלכה אחרונה זו שדי בייחוד מקום לאותו עפר כדי שיהיה מותר בשימוש בשבת — \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 בדיני חריות הדקל. \u0003דאי כרבנן\u0004 \u0005[שאם כ\u0006שיטת \u0005חכמים]\u0006 היא — \u0003האמרי בעינן\u0004 \u0005[הרי\u0006 הם \u0005אומרים\u0006 כי \u0005צריכים אנו]\u0006 שיעשו \u0003מעשה\u0004 של ממש בגופו של המוקצה כדי להכשירו לשימוש בשבת, כגון קשירת החריות, ולא די במחשבה בלבד.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהלכה זו כשיטת \u0005חכמים\u0006 היא\u0005],\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן דבעינן\u0004 \u0005[אמרו חכמים שצריכים אנו] שיעשה \u0006\u0003מעשה\u0004 של ממש \u0003אלא מידי דבר עבידא ביה\u0004 \u0005[\u0006ב\u0005דבר הניתן שייעשה בו]\u0006 \u0003מעשה, אבל מידי דלא בר מיעבדא ביה\u0004 \u0005[דבר שאינו ניתן שייעשה בו]\u0006 \u0003מעשה\u0004 — \u0003לא\u0004 אמרו שצריך לעשות בו מעשה כדי שיהיה ניתן לשימוש בשבת, וחול ועפר כיון שאי אפשר לעשות בהם מעשה — מותר להשתמש בהם אף על ידי מחשבה בלבד.","ומעירים: שאלה זו אם יש צורך בדברים אלה כדי לעשות מעשה, \u0003נימא כתנאי\u0004 \u0005[האם נאמר\u0006 שהיא \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 בענין אחר. ששנינו בברייתא אחת: \u0003בכל חפין\u0004 (משפשפים, מנקים) \u0003את הכלים\u0004 בשבת \u0003חוץ מכלי כסף בגרתקון\u0004 (מין גיר) העשוי במיוחד לשיפשוף כלי כסף, ושעל ידי שימוש בו מתגרדת ויורדת שכבה מן הכלי. ומכאן נדייק ש\u0003נתר וחול מותר\u0004 להשתמש בהם בשבת לצחצוח כלים.","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]\u0006 בענין זה: \u0003נתר וחול\u0004 — \u0003אסור\u0004 להשתמש בהם בשבת לצחצוח כלים. \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה חלוקים\u0006 הם\u0005],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה\u0006 האוסר שימוש בחול בשבת \u0005סבור]\u0006 כי כדי להתיר את השימוש במוקצה בשבת \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שייעשה בו \u0003מעשה\u0004 של ממש, וכיון שאין אפשרות לעשות מעשה בחול — אסור להשתמש בו. \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 שהתיר \u0005סבור]\u0006 ש\u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיעשה \u0003מעשה.\u0004","הסבר זה נדחה: \u0003לא, דכולי עלמא לא בעינן\u0004 \u0005[לדעת הכל אין\u0006 \u0003אנו צריכים]\u0004 שייעשה \u0003מעשה, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 אין סתירה בין הברייתות, כי טעמו של האסור אינו משום מוקצה, אלא \u0003הא\u0004 \u0005[זו,\u0006 הברייתא האוסרת\u0005]\u0006 כשיטת \u0003ר' יהודה\u0004 היא, ואילו \u0003הא\u0004 \u0005[זו,\u0006 הברייתא המתירה\u0005]\u0006 כשיטת \u0003ר' שמעון\u0004 היא.","ומפרטים: \u0003הא\u0004 \u0005[זו,\u0006 הברייתא האוסרת\u0005]\u0006 כשיטת \u0003ר' יהודה\u0004 היא, ש\u0003אמר\u0004 כלל בהלכות שבת: \u0003דבר שאין מתכוין\u0004 לעשותו, ונעשית המלאכה בלא שיתכוון לכך — \u0003אסור,\u0004 והחול והנתר אף על פי שאין מתכוון להחליק בהם את כלי הכסף, מכל מקום משפשפים הם את הכלי ואסור הדבר בשבת, ואילו \u0003הא\u0004 \u0005[זו,\u0006 הברייתא המתירה\u0005]\u0006 כשיטת \u0003ר' שמעון\u0004 היא. ש\u0003אמר\u0004 ש\u0003דבר שאין מתכוין\u0004 — \u0003מותר.\u0004","ומקשים: \u0003במאי אוקימתא להא דשרי\u0004 \u0005[במה העמדת את זה שהתיר]\u0006 — \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור את סוף\u0006 אותה ברייתא\u0005],\u0006 ששנינו בה בענין השימוש בשבת בנתר ובחול: \u0003אבל לא יחוף בהם שערו\u0004 בשבת. \u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' שמעון\u0004 הלא ר' שמעון \u0003משרא קשרי\u0004 \u0005[מתיר הוא]\u0006 בחפיפה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003נזיר\u0004 שאסור לו לגלח שערותיו \u0003חופף\u0004 אותן בימות החול בחול ונתר \u0003ומפספס\u0004 (מפריד בין השערות הדבוקות), \u0003אבל לא סורק,\u0004 כי המסרק ודאי ישיר שערות. הרי שר' שמעון מתיר לחוף את הראש אף במקום שיש איסור בהורדת השערות, כיון שלדעתו אין לחשוש בכך להשרת השיער!","\u0003אלא\u0004 יש לומר כי \u0003הא והא\u0004 \u0005[זו וזו],\u0006 שתי הברייתות החלוקות בענין רחיצה כשיטת \u0003ר' יהודה היא, ותרי תנאי אליבא\u0004 \u0005[ושני תנאים על פי שיטת]\u0006 \u0003ר' יהודה. האי תנא אליבא\u0004 \u0005[תנא זה ההולך בשיטת]\u0006 \u0003ר' יהודה סבר גריר\u0004 \u0005[סבור\u0006 הוא כי הנתר \u0005משיר]\u0006 ולכן אסר לחפוף בו את השיער, \u0003והאי תנא אליבא\u0004 \u0005[תנא זה ההולך בשיטת]\u0006 \u0003ר' יהודה\u0004 ומתיר, \u0003סבר לא גריר\u0004 \u0005[\u0006\u0005סבור\u0006 ש\u0005אין\u0006 הנתר \u0005משיר].\u0006","ומקשים: \u0003במאי אוקימתא\u0004 \u0005[במה,\u0006 כשיטת מי \u0005העמדת\u0006 את הברייתא\u0005]\u0006 — \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של אותה ברייתא\u0005]\u0006 ששנינו בה: \u0003אבל\u0004 את \u0003פניו ידיו ורגליו מותר\u0004 לרחוץ בחול ונתר. ולכאורה מדוע יהא מותר, \u0003הא מעבר שיער\u0004 \u0005[הרי\u0006 בכך \u0005משיר\u0006 הוא את \u0005השערות]!\u0006","ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שההיתר לרחוץ פניו ידיו ורגליו הוא \u0003בקטן. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהמדובר \u0003באשה. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי המדובר \u0003בסריס,\u0004 שכל אלה אין להם שערות בפניהם ידיהם ורגליהם ואין לחשוש להשרתן.","אגב בעיות אלה של רחיצה \u0003אמר רב יהודה: עפר לבינתא\u0004 \u0005[לבונה\u0006 שחוקה\u0005]\u0006 (רה\"נ) \u0003שרי\u0004 \u0005[\u0006\u0005מותר]\u0006 לרחוץ בו בשבת, שאינו משיר את השיער. ו\u0003אמר רב יוסף:\u0004 ה\u0003כוספא\u0004 הנשארת לאחר סחיטת השמן הריחני מן ה\u0003יסמין שרי\u0004 \u0005[מותר]\u0006 לרחוץ בה. ו\u0003אמר רבא: עפר\u0004 (אבקת) \u0003פלפלי שרי\u0004 \u0005[פלפלים מותר]\u0006 לרחוץ בה. ו\u0003אמר רב ששת: ברדא שרי\u0004 \u0005[מותר]\u0006 לרחוץ בה בשבת.","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003ברדא\u0004 זו? \u0003אמר רב יוסף: תילתא אהלא ותילתא אסא ותילתא סיגלי\u0004 \u0005[שליש אהל, ושליש הדס, ושליש סיגלים].\u0006 \u0003אמר רב נחמיה בר יוסף: כל היכא דליכא רובא אהלא\u0004 \u0005[בכל מקום שאין רוב אהל]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005],\u0006 ואפילו היה האהל יתר על שליש, כי רק חומר חריף זה יש בו כדי להשיר את השיער, ולא כן בשאר המרכיבים.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 בני הישיבה את \u0003רב ששת\u0004 שאלה זו: \u0003מהו\u0004 הדין לענין ההיתר \u0003לפצוע זיתים\u0004 על סלע בשבת כדי לרחוץ בשמן היוצא מהם (גאונים) \u0003בשבת? אמר להו\u0004 \u0005[להם]\u0006 \u0003וכי\u0004 לפוצעם \u0003ב\u0004ימות ה\u0003חול מי\u0004 \u0005[האם]\u0006 \u0003התירו? קסבר\u0004 \u0005[סבור הוא]\u0006 שיש בכך צד איסור משום \u0003הפסד אוכלין,\u0004 שעל ידי הפציעה מתקלקלים הזיתים, ואפילו בחול אסור להשחית דבר מאכל.","ומעירים: \u0003לימא פליגא\u0004 \u0005[האם נאמר\u0006 כי \u0005חלוקה]\u0006 הלכה זו על שיטת \u0003שמואל?\u0004 ש\u0003אמר שמואל: עושה אדם כל צורכו בפת\u0004 ואין חושש שמא תתקלקל אגב כך! ומשיבים: אין זו סתירה הכרחית כי \u0003פת לא מאיסא\u0004 \u0005[אינה נמאסת],\u0006 \u0003הני מאיסי\u0004 \u0005[\u0006ו\u0005אלה\u0006 הזיתים, \u0005נמאסים]\u0006 ומתקלקלים.","מסופר: \u0003אמימר ומר זוטרא ורב אשי הוו יתבי, אייתו לקמייהו\u0004 \u0005[היו יושבים\u0006 בשבת ו\u0005הביאו לפניהם]\u0006 \u0003ברדא\u0004 לרחוץ. \u0003אמימר ורב אשי משו\u0004 \u0005[רחצו],\u0006 ואילו \u0003מר זוטרא לא משא\u0004 \u0005[רחץ].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא סבר לה מר להא\u0004 \u0005[אין אדוני סובר ל\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רב ששת\u0004 כי \u0003ברדא שרי\u0004 \u0005[מותר]\u0006 לרחוץ בו בשבת?! \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב מרדכי\u0004 שהיה אף הוא שם: \u0003בר מיניה דמר\u0004 \u0005[חוץ ממנו, מאדוני],\u0006 כלומר, אין ללמוד ממר זוטרא, שכן \u0003אפילו בחול נמי לא סבירא ליה\u0004 \u0005[גם כן אינו סבור]\u0006 שמותר להשתמש בברדא.","כי \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כי הא דתניא\u0004 \u0005[\u0006כברייתא \u0005זו ששנינו]:\u0006 \u0003מגרר אדם גלדי\u0004 (קרומים יבשים) \u0003צואה וגלדי מכה שעל בשרו בשביל צערו\u0004 שלא יכאיבו לו, ו\u0003אם בשביל ליפות\u0004 עצמו על ידי שמסיר הלכלוך — אסור. שלדעת החכם בברייתא זו אסור כלל לגבר ליפות עצמו משום חשש \"ולא ילבש גבר שמלת אשה\" (דברים כב, ה) שאסור לגבר להתקשט בבגדי נשים, או כדרך הנשים.","ומעירים: \u0003ואינהו כמאן סברוה\u0004 \u0005[והם\u0006 החכמים שהתירו \u0005כמי סברו]?\u0006 — \u0003כי הא דתניא\u0004 \u0005[כמו\u0006 ברייתא \u0005זו\u0006 ששנינו]: \u0003רוחץ אדם פניו ידיו ורגליו בכל יום בשביל\u0004 כבוד \u0003קונו, משום שנאמר: \"כל פעל ה' למענהו\"\u0004 (משלי טז, ד), כלומר, שכל דבר נאה שישנו בעולם הוא שבח לשם ה', שברא בריות נאות, וראוי לאדם ליפות עצמו לשבחו של הבורא.","שנינו במשנה ש\u0003ר' אלעזר בן עזריה אומר\u0004 ש\u0003קופה\u0004 המלאה בגיזי צמר (שהם מוקצה) שטמן בתוכה קדירת תבשיל, כשרוצה ליטול את הקדירה מתוכה בשבת הריהו \u0003מטה\u0004 לאותה קופה \u0003על צדה ונוטל\u0004 את הקדירה, \u0003שמא יטול\u0004 את הקדירה מן הקופה ואינו יכול להחזיר, כי גיזי הצמר יפלו לחלל בו היתה מונחת הקדירה ויסתמוהו, וחכמים מתירים. \u0003אמר ר' אבא\u0004 שכך \u0003אמר ר' חייא בר אשי\u0004 שכך \u0003אמר רב: הכל מודים,\u0004 אף חכמים, \u0003שאם נתקלקלה הגומא\u0004 שהיתה בה הקדירה בקופה — \u0003שאסור להחזיר\u0004 את הקדירה לאותה קופה.","ומקשים: הרי \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003וחכמים אומרים: נוטל ומחזיר.\u0004 ונברר את הדבר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 במקרה ש\u0003לא נתקלקלה הגומא\u0004 — \u0003שפיר קא אמרי רבנן\u0004 \u0005[יפה אומרים חכמים]\u0006 שמותר להחזיר, ומדוע יאסור ר' אלעזר בן עזריה במקום זה שברור היתרו. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003אף על פי\u0004 ש\u0003נתקלקלה הגומא\u0004 ויש איפוא מחלוקת בדבר.","ודוחים: \u0003לא, לעולם\u0004 מדובר באופן ש\u0003לא נתקלקלה, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003חוששין\u0004 לקלקול \u0003קמיפלגי\u0004 \u0005[נחלקו].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר בן עזריה, \u0005סבור]\u0006 כי \u0003חוששין שמא נתקלקלה הגומא\u0004 ולכן אין מחזירים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]\u0006 כי \u0003אין חוששין\u0004 שמא נתקלקלה הגומה.","בקשר לנושא זה של הכנסת חפץ בתוך מוקצה נאמרו הלכות אחדות. \u0003אמר רב הונא: האי סליקוסתא\u0004 \u0005[ענף נרקיס]\u0006 שנהוג היה להכניסו לנוי ולריח בעציץ בתוך הבית, ולהעמידו בעפר לח, אם בערב שבת \u0003דצה\u0004 \u0005[נעצה]\u0006 בעפר ואחר כך \u0003שלפה, והדר דצה\u0004 \u0005[וחזר\u0006 ו\u0005נעצה]\u0006 — \u0003שריא\u0004 \u0005[מותרת]\u0006 לשולפה שוב בשבת, כי על ידי הנעיצה והשליפה כבר הרחיב את החור שהיא מצויה בו, ואין לחשוש שבשבת יזיז את העפר ממקומו. \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 עשה כן מערב שבת \u0003אסיר\u0004 \u0005[אסור]\u0006 לשולפה שוב בשבת.","\u0003אמר שמואל: האי סכינא דביני אורבי\u0004 \u0005[סכין זו\u0006 שמניחה \u0005בין הלבנים]\u0006 אם \u0003דצה\u0004 \u0005[נעצה]\u0006 בין הלבנים בערב שבת ואחר כך \u0003שלפה, והדר דצה\u0004 \u0005[וחזר\u0006 ו\u0005נעצה]\u0006 — \u0003שרי\u0004 \u0005[מותר]\u0006 לשולפה בשבת מבין הלבנים. \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 עשה כן מערב שבת \u0003אסיר\u0004 \u0005[אסור]\u0006 לשולפה שוב בשבת.","\u0003מר זוטרא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב אשי\u0004 הוא ש\u0003אמר\u0004 זאת: \u0003בגורדיתא דקני\u0004 \u0005[בקנים המפרידים\u0006 בבית\u0005]\u0006 (גאונים) \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005]\u0006 לנעוץ \u0005סכין ביניהם בשבת\u0006\u0005,\u0006 ואין לחשוש שמא יבואו לחתוך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרבא: מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב קטינא תיובתא\u0004 \u0005[קושיא חמורה]\u0006 על שיטת רב הונא ושמואל האומרים שאם לא נעץ את ענף הנרקיס או הסכין בשבת ושלפו וחחר ונעצו אינו יכול לשולפו בשבת ממה ששנינו במשנה: \u0003הטומן לפת וצנונות\u0004 בעפר ש\u0003תחת הגפן\u0004 כדי לשומרם, \u0003אם היה מקצת עליו\u0004 של הטמון \u0003מגולים\u0004 ויש לו אפשרות לאחוז בהם לכשירצה לשולפם — \u0003אינו חושש\u0004"],["\u0003לא משום כלאים,\u0004 כי אף שמיני זרעים הצומחים מתחת גפן נאסרים מן התורה משום כלאי הכרם, כיון שבמקרה זה שהשאיר מקצת הירק מגולה — אין כאן זריעה, ואין לחשוש לאסור. \u0003ו\u0004אף \u0003לא\u0004 יחשוש \u0003משום שביעית\u0004 (שמיטה), שמא יש בכך משום שתילת ירק בשנת השמיטה. \u0003ולא משום מעשר,\u0004 שיחשוש שמא יצטרך לשוב ולהפריש מעשר מירק זה, כאילו הוצא מתחילתו מן הקרקע. \u0003ו\u0004כן \u0003ניטלין בשבת,\u0004 ואין לחשוש להזזת העפר בשעת מעשה. ואם כן הרי זו קושיה על דברי רב הונא ושמואל, שחששו להזזת העפר בשבת! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא.","תבשיל שטמנו בערב שבת, אם \u0003לא כסהו מבעוד יום\u0004 — \u0003לא יכסנו\u0004 עוד \u0003משתחשך. כסהו\u0004 מבעוד יום \u0003ונתגלה\u0004 בשבת \u0003מותר לכסותו, ו\u0004מותר שיהא \u0003ממלא\u0004 את \u0003הקיתון\u0004 במים צוננים \u0003ונותן\u0004 אותו \u0003לתחת הכר או תחת הכסת\u0004 כדי שלא יתחממו.","\u0003אמר רב יהודה אמר שמואל: מותר להטמין את הצונן\u0004 שהוא ודאי לא יתחמם ואין לחשוש משום הדמיון שיש בכך להטמנת חמין. \u0003אמר רב יוסף: מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בדבריו? והלא כבר \u0003תנינא\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 הלכה מפורשת בענין. ששנינו: \u0003ממלא אדם קיתון\u0004 (ספל) במים \u0003ונותן תחת הכר או תחת הכסת!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: טובא קא משמע לן\u0004 \u0005[הרבה,\u0006 דבר גדול \u0005השמיע לנו],\u0006 \u0003דאי ממתניתין הוה אמינא\u0004 \u0005[שאם ממשנתנו הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שמותר להטמין את הצונן — הרי זה דווקא ב\u0003דבר שאין דרכו להטמין\u0004 בחמין, \u0003אבל דבר ש\u0004כיוצא בו \u0003דרכו להטמין\u0004 בחמין — \u0003לא\u0004 הותר לטומנו בדרך זו, ועל כן אמר שמואל שהיתר זה כללי הוא.","\u0003אמר רב הונא\u0004 שכך \u0003אמר רב\u0004 (ראה גרסות): \u0003אסור להטמין את הצונן.\u0004 ומקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003רבי התיר להטמין את הצונן\u0004! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין הדבר קשה],\u0006 כי \u0003הא מקמיה דלישמעיה\u0004 \u0005[זה\u0006 שאסר רבי היה זה \u0005לפני ששמעה\u0006 להלכה זו\u0005]\u0006 \u0003מר' ישמעאל בר' יוסי, הא לבתר דלישמעיה\u0004 \u0005[\u0006ו\u0005זה\u0006 שהתיר היה זה \u0005לאחר ששמעה ]\u0006 \u0003כי הא דיתיב\u0004 \u0005[כמו זה\u0006 ששנינו \u0005שישב]\u0006 \u0003רבי ואמר: אסור להטמין את הצונן\u0004 בשבת. \u0003אמר לפניו ר' ישמעאל בר' יוסי: אבא התיר להטמין את הצונן. אמר\u0004 רבי: אם כן חוזר אני בי ש\u0003כבר הורה זקן\u0004 (ר' יוסי) בנושא זה, ואני מבטל דעתי מפניו.","\u0003אמר רב פפא: בא וראה כמה מחבבין\u0004 היו \u0003זה את זה. שאילו ר' יוסי\u0004 היה \u0003קיים\u0004 (חי), \u0003היה\u0004 הוא \u0003כפוף ויושב לפני רבי\u0004 כתלמיד, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' ישמעאל בר' יוסי\u0004 ש\u0003ממלא מקום אבותיו הוה\u0004 \u0005[היה],\u0006 שהיה גדול בתורה כאביו, \u0003ו\u0004בכל זאת היה \u0003כפוף ויושב לפני רבי\u0004 כתלמיד. \u0003וקאמר\u0004 \u0005[ו\u0006בכל זאת \u0005אמר]\u0006 רבי: \u0003כבר הורה זקן,\u0004 שביטל דעתו מפני ר' יוסי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לדרו עבדיה\u0004 \u0005[עבדו]:\u0006 \u0003אטמין לי צונן\u0004 בשבת, \u0003ואייתי\u0004 \u0005[והבא]\u0006 \u0003לי מיא דאחים קפילא ארמאה\u0004 \u0005[מים שחימם טבח ארמי,\u0006 גוי\u0005]\u0006 בחול. ובכך רצה להראות שאין בכך משום בישולי גוים. \u0003שמע ר' אמי\u0004 על מעשה רב נחמן \u0003ואיקפד\u0004 \u0005[והקפיד\u0006 עליו\u0005].\u0006 \u0003אמר רב יוסף: מאי טעמא איקפד\u0004 \u0005[מה טעם הקפיד]\u0006 ר' אמי? והרי רב נחמן \u0003כרבוותיה עביד\u0004 \u0005[עשה],\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003כרב, וחדא\u0004 \u0005[ואחת]\u0006 \u0003כשמואל.\u0004","ומפרטים: \u0003כשמואל\u0004 — ש\u0003אמר ר' יהודה אמר שמואל: מותר להטמין את הצונן.\u0004 ו\u0003כרב\u0004 — ש\u0003אמר רב שמואל בר רב יצחק\u0004 שכך \u0003אמר רב: כל\u0004 דבר \u0003שהוא נאכל כמות שהוא חי\u0004 ואין הכרח לבשלו, גם אם נתבשל — \u0003אין בו\u0004 איסור \u0003משום בשולי גוים,\u0004 ומים הניתנים לשתיה גם בלא בישול מותר לשתותם, אפילו חיממם גוי.","ומסבירים: \u0003והוא,\u0004 רבי אמי שהקפיד, \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 כי \u0003אדם חשוב שאני\u0004 \u0005[שונה]\u0006 וחייב להקפיד על עצמו ביותר, ולהתרחק אף מדבר הנראה כאיסור.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אף על פי שאמרו\u0004 חכמים ש\u0003אין טומנין\u0004 ביום השבת \u0003אפילו בדבר שאינו מוסיף הבל משחשכה,\u0004 בכל זאת בשבת \u0003אם בא להוסיף\u0004 על הדברים שהטמין בהם מבעוד יום — \u0003מוסיף. כיצד הוא עושה? רבן שמעון בן גמליאל אומר:\u0004 כגון ש\u0003נוטל את הסדינין\u0004 שכיסה בהם את הקדירה \u0003ומניח את הגלופקרין\u0004 (שמיכות עבות), \u0003או\u0004 אם חושש לחום יתר \u0003נוטל את הגלופקרין ומניח את הסדינין.\u0004","\u0003וכן היה רבן שמעון בן גמליאל אומר\u0004 ומקל עוד בדיני הטמנה: \u0003לא אסרו\u0004 להטמין בשבת \u0003אלא\u0004 ב\u0003אותו מיחם\u0004 שחיממו בו את המים, \u0003אבל פינה\u0004 מקודם \u0003ממיחם למיחם\u0004 שעכשיו המיחם השני הוא כלי שני — \u0003מותר\u0004 להטמין בו. וטעמו של דבר: \u0003השתא אקורי קא מקיר לה, ארתוחי קא מירתח לה\u0004 \u0005[הרי עתה\u0006 רואים אנו שהוא \u0005מקרר אותו,\u0006 את המיחם בכוונה בעברת תוכנו למיחם אחר, וכי יש עוד לחשוש שמא \u0005יבוא להרתיחו]\u0006 בשבת?!","ועוד אמר: \u0003טמן וכיסה\u0004 את הקדירה \u0003בדבר הניטל בשבת, או\u0004 ש\u0003טמן בדבר שאינו ניטל בשבת\u0004 משום מוקצה \u0003וכיסה בדבר הניטל בשבת\u0004 — \u0003הרי זה נוטל\u0004 את הדבר שהטמין בו \u0003ומחזיר\u0004 אותו למקומו ואינו חושש, שכיון שהכיסוי ניטל בשבת הריהו יכול לאחוז בכיסוי ולגלותה.","ואם \u0003טמן וכיסה בדבר שאינו ניטל בשבת או שטמן בדבר הניטל בשבת, וכיסה בדבר שאינו ניטל בשבת,\u0004 בכגון זה אינו יכול ליטלו, ולכן \u0003אם היה\u0004 הכלי \u0003מגולה מקצתו נוטל\u0004 את הכלי ומטהו על צידו והכיסוי נופל מאליו \u0003ו\u0004כן \u0003מחזיר\u0004 את הכלי אחר כך. \u0003ואם לאו\u0004 \u0005[לא],\u0006 היה מגולה מקצתו —"],["\u0003אינו נוטל ומחזיר.\u0004 \u0003ר' יהודה אומר: נעורת של פשתן דקה הרי היא כזבל\u0004 ואין טומנים בה.","","\u0003מניחין מיחם על גבי מיחם וקדרה על גבי קדרה\u0004 כי המיחם התחתון לא יוכל להרתיח את העליון, \u0003אבל לא\u0004 מניחים \u0003קדרה על גבי מיחם, ו\u0004לא \u0003מיחם על גבי קדרה\u0004, שבכגון זה יש חשש שיתחמם הכלי עליון. \u0003וטח\u0004 (סותם בטיח) אדם \u0003את פיה\u0004 של הקדירה לסתום את נקביה \u0003בבצק,\u0004 וכל אלו \u0003לא בשביל שיחמו\u0004 המים, \u0003אלא בשביל שיהיו משומרים\u0004 בדרגת החום כשהיו, שלא יצטננו ממה שהיו.","\u0003וכשם שאין טומנין את החמין כך אין טומנין את הצונן. רבי התיר להטמין את הצונן.\u0004","\u0003ואין מרזקין\u0004 (מרסקים, שוברים) \u0003לא את השלג ולא את הברד בשבת בשביל שיזובו מימיו\u0004 ויוכלו לשתותם, כי יש בכך משום יצירת דבר חדש — מים משלג, בשבת. \u0003אבל נותן הוא\u0004 את הקרח או את הברד \u0003לתוך הכוס או לתוך הקערה\u0004 והקרח נמס מאליו \u0003ואינו חושש.\u0004","","בפרטי דיני ההוצאה בשבת אמרו חכמים: \u0003במה בהמה יוצאה ובמה אינה יוצאה?\u0004 — \u0003יוצא הגמל באפסר ו\u0004ה\u0003נאקה בחטם ולובדקים\u0004 יוצאים \u0003בפרומביא,\u0004 וכל אלה יבוארו עוד להלן בדברי הגמרא. \u0003וסוס\u0004 יוצא בשבת \u0003בשיר\u0004 (צמיד סביב לצוארו). \u0003ו\u0004בכלל, \u0003כל בעלי השיר,\u0004 אותם בעלי החיים שרגילים להוציא אותם בצמיד סביב לצוארם בחול, \u0003יוצאים בשיר\u0004 בשבת, \u0003ו\u0004מותר לקשור חבל שיהיו אף \u0003נמשכין בשיר.\u0004 \u0003ו\u0004כשנטמאים אלה \u0003מזין עליהן\u0004 מי חטאת כדי לטהרם, \u0003ו\u0004כן \u0003טובלן\u0004 כשהם \u0003במקומן\u0004 שמזה על השיר ומטביל את בעל החיים כאשר השיר בצוארו, ואינו צריך להסירו.","","","מילים אחדות שבמשנה לא היו מובנות לחכמי התלמוד ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נאקה בחטם\"? אמר רבה בר בר חנה: נאקתא חיורתי בזממא דפרזלא\u0004 \u0005[נקבת גמל לבנה\u0006 (גאונים) \u0005בחח ברזל\u0006 שמכניסים בחוטמה\u0005].\u0006 וכדי לבאר את פירוש המילים \u0003\"ולובדקים בפרומביא\" אמר רב הונא: חמרא לובא בפגי דפרזלא\u0004 \u0005[חמור לובי ברסן של ברזל].\u0006","אגב הזכרת החמור הלובי, מסופר: \u0003לוי שדר זוזי\u0004 \u0005[שלח זוזי,\u0006 כסף\u0005]\u0006 \u0003לבי חוזאי למיזבן ליה חמרא לובא\u0004 \u0005[לקנות לו חמור לובי]\u0006 שהוא משובח ביותר. \u0003צרו שדרו ליה שערי\u0004 \u0005[צררו לו\u0006 את הכסף \u0005ושלחו\u0006 עמו \u0005שעורים],\u0006 ועשו כן כדי \u0003למימר דניגרי דחמרא שערי\u0004 \u0005[לומר לו\u0006 על ידי כך \u0005שפסיעות החמור\u0006 תלויות \u0005בשעורים\u0006 שאוכל\u0005],\u0006 שאם ישפר את מזונו של החמור — יהיה משובח כחמור לובי.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מחליפין\u0004 היו בני הישיבה את הפרטים הכתובים במשנה \u0003לפני רבי,\u0004 ושואלים: \u0003של זו בזו,\u0004 כלומר, נאקה באפסר וגמל בחטם, \u0003מהו\u0004 הדין בכגון זה, האם מאחר ומניח את הריתמה של בעל חיים אחד על האחר האם בכך הוא נחשב כמשא ואין הוא יוצא בו, או לא?","ומסבירים: \u0003נאקה\u0004 היוצאת \u0003באפסר לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 כי \u0003כיון דלא מינטרא ביה\u0004 \u0005[שאינה נשמרת בו]\u0006 — \u0003משאוי\u0004 \u0005[משא]\u0006 \u0003הוא,\u0004 שהרי לצורך הנאקה אין האפסר מספיק, ואם כן הוא משא ללא תועלת. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 הרי זה ב\u0003גמל\u0004 היוצא \u0003בחטם מאי\u0004 \u0005[מה]\u0006 דינו? וצדדי השאלה: האם \u0003כיון דסגי ליה\u0004 \u0005[שדי לו]\u0006 לגמל \u0003באפסר\u0004 בלבד — הרי החטם \u0003משאוי\u0004 \u0005[\u0006ל\u0005משא]\u0006 \u0003הוא\u0004 נחשב, \u0003או דילמא נטירותא יתירתא לא אמרינן משאוי\u0004 \u0005[שמא\u0006 ב\u0005שמירה יתירה איננו אומרים\u0006 של \u0005משא]\u0006 \u0003הוא\u0004 נחשב?","\u0003אמר לפניו ר' ישמעאל בר' יוסי: כך אמר אבא\u0004 ר' יוסי: \u0003ארבע בהמות יוצאות באפסר, הסוס והפרד והגמל והחמור.\u0004 ומעתה יש להבין \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא מנין זה שארבע ולא עוד, \u0003לאו למעוטי\u0004 \u0005[האם לא למעט]\u0006 את ה\u0003גמל\u0004 שלא יצא \u0003בחטם\u0004 אלא באפסר בלבד, ואם כן יהא לנו לכאורה פתרון לשאלה! ודוחים: \u0003לא,\u0004 מנין זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003נאקה\u0004 שאינה יוצאת \u0003באפסר.\u0004","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו]\u0006 \u0003לובדקים וגמל יוצאים באפסר.\u0004 לגופו של ענין אומרים כי השאלה שנשאלה בדבר שמירה יתירה הרי היא \u0003כתנאי\u0004 \u0005[כתנאים,\u0006 שנחלקו בדבר\u0005].\u0006 ששנינו בברייתא: \u0003אין חיה יוצאה בסוגר, חנניה אומר: יוצאה בסוגר ובכל דבר המשתמר.\u0004","וכדי להבין את הדבר תוהים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנחנו]\u0006 כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי עוסקים אנו \u0003בחיה גדולה\u0004 — \u0003מי סגי\u0004 \u0005[האם מספיק]\u0006 \u0003לה\u0004 ב\u0003סוגר?\u0004 ומאחר שאין הסוגר מספיק לה — אסור לשים עליה אותו בשבת, שהרי הוא כמשא! \u0003ואלא\u0004 תאמר שהמדובר \u0003בחיה קטנה, מי\u0004 \u0005[האם]\u0006 \u0003לא סגי\u0004 \u0005[מספיק]\u0006 \u0003לה סוגר?\u0004 ומדוע יבואו אם כן חכמים לאסור?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 תאמר כי ב\u0003חתול איכא בינייהו\u0004 \u0005[\u0006הוא ש\u0005יש ביניהם\u0006 מחלוקת\u0005],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 כי \u0003כיון דסגי\u0004 \u0005[שמספיק]\u0006 \u0003לה\u0004 לחתול \u0003במיתנא בעלמא\u0004 \u0005[בחבל קטן בלבד]\u0006 הרי הסוגר \u0003משאוי\u0004 \u0005[משא]\u0006 \u0003הוא\u0004 על החתול. \u0003וחנניה סבר\u0004 \u0005[סבור]\u0006 כי \u0003כל נטירותא יתירתא\u0004 \u0005[שמירה יתירה]\u0006 \u0003לא אמרינן משאוי\u0004 \u0005[אין אנו אומרים\u0006 ש\u0005משא]\u0006 \u0003הוא.\u0004 ואם כן נחלקו תנאים בשאלה אם שמירה יתירה לבהמה נחשבת כמשאוי עליה, אם לא. \u0003אמר רב הונא בר חייא\u0004 שכך \u0003אמר שמואל: הלכה כחנניה\u0004 שאין דבר שהוא שמירה יתירה נחשב כמשא.","מסופר: \u0003לוי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא בר חייא ורבה בר רב הונא הוו קאזלי באורחא\u0004 \u0005[היו הולכים\u0006 יחד \u0005בדרך].\u0006 \u0003קדמיה חמרא\u0004 \u0005[הקדים\u0006 מעצמו \u0005החמור]\u0006 של \u0003לוי לחמרא\u0004 \u0005[את החמור]\u0006 של \u0003רבה בר רב הונא. חלש דעתיה\u0004 \u0005[חלשה דעתו,\u0006 נפגע\u0005]\u0006 \u0003רבה בר רב הונא.\u0004 שהוא היה הגדול בהם, וחשב שלוי בנו של רב הונא בר חייא רוצה להראות בכך שהוא גדול ממנו, והולך לפניו. \u0003אמר\u0004 לוי בלבו: \u0003אימא ליה מילתא כי היכי\u0004 \u0005[אומר לו דבר כדי]\u0006שמספיק"],["\u0003דאיתותב דעתיה\u0004 \u0005[שתתיישב דעתו]\u0006 ויבין שלא נתכוונתי להעליבו. וכדי לבטא את רצונו \u0003אמר ליה\u0004 \u0005[לו]\u0006 כך: \u0003חמור שעסקיו רעים\u0004 (שאינו ממושמע) \u0003כגון זה\u0004 שאני רוכב עליו, \u0003מהו לצאת בפרומביא בשבת?\u0004 שאף שחמור סתם אינו זקוק לפרומביא ודיו באפסר ולגביו הפרומביא היא שמירה יתירה, אבל חמור פרא כגון זה האם גם בו יש בכך משום שמירה יתירה ויהא אסור לצאת בה בשבת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא: אף אם היא לגביו כשמירה יתירה, מכל מקום \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבוך משמיה\u0004 \u0005[אביך משמו]\u0006 של \u0003שמואל: הלכה כחנניה,\u0004 שאין בשמירה יתירה משום משאוי.","באותו ענין של רצועות שונות לקשור בעלי חיים \u0003תנא דבי\u0004 \u0005[שנא\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשיא: עז שחקק לה\u0004 מקום לאפסר \u0003בין קרניה\u0004 הריהי \u0003יוצאה באפסר\u0004 הקשור בקרניים \u0003בשבת\u0004 כיון שהאפסר נכנס בתוך החקיקה ואינו נשמט. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף: תחב לה\u0004 לעז רצועה \u0003בזקנה מהו?\u0004 וצדדי השאלה: \u0003כיון דאי מנתח לה כאיב\u0004 \u0005[שאם\u0006 תרצה \u0003העז\u0004 \u0005לנתק\u0006 את האפסר \u0005יכאב]\u0006 \u0003לה\u0004 ולכן \u0003לא אתיא לנתוחה\u0004 \u0005[תבוא לנתקו]\u0006 והאפסר ישאר במקומו, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003זימנין דרפי ונפיל\u0004 \u0005[פעמים שירפה\u0006 הקשר \u0005ויפול],\u0006 \u0003ואתי לאתויי\u0004 \u0005[ויבא\u0006 בעל העז \u0005להביאו,\u0006 לטלטלו\u0005]\u0006 לאפסר \u0003ארבע אמות ברשות הרבים.\u0004 לשאלה זו לא נמצא פתרון ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003ולא\u0004 תצא הפרה \u0003ברצועה שבין קרניה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה בר אבא: פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב ושמואל; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי רצועה זו \u0003בין\u0004 ששם אותה על הפרה \u0003לנוי\u0004 ו\u0003בין לשמר\u0004 — \u0003אסור\u0004 לפרה לצאת בה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לנוי\u0004 — \u0003אסור, ולשמר\u0004 — \u0003מותר.\u0004","\u0003אמר רב יוסף תסתיים\u0004 \u0005[תוגדר,\u0006 תתברר\u0005]\u0006 ההנחה כי \u0003שמואל הוא\u0004 ש\u0003אמר\u0004 כי \u0003לנוי אסור\u0004 ו\u0003לשמר מותר.\u0004 שהרי \u0003אמר רב הונא בר חייא\u0004 שכך \u0003אמר שמואל: הלכה כחנניה\u0004 שמותר לבעל חי לצאת ברצועות שהוסיפו לו לשמירה יתירה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אדרבה\u0004 \u0005[להיפך],\u0006 אמור כי \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 תתברר\u0005]\u0006 ההנחה כי \u0003שמואל הוא\u0004 ש\u0003אמר\u0004 כי \u0003בין לנוי בין לשמר\u0004 — \u0003אסור.\u0004 שכן \u0003אמר רב יהודה\u0004 שכך \u0003שמואל: מחליפין\u0004 היו בני הישיבה \u0003לפני רבי של זו בזו,\u0004 ששינו את סוגי הרתמה השונים לבהמות אחרות, ושאלוהו: \u0003מהו\u0004 הדין בכגון זה, האם מותר לצאת בהם בשבת? ו\u0003אמר לפניו ר' ישמעאל בר' יוסי, כך אמר אבא\u0004 ר' יוסי: \u0003ארבע בהמות יוצאות באפסר הסוס והפרד והגמל והחמור.\u0004 ומעתה, \u0003לאו למעוטי\u0004 \u0005[האם\u0006 לא בא זה כדי \u0005למעט]\u0006 \u0003גמל\u0004 מיציאה \u0003בחטם\u0004 לפי שהוא משא יתר? הרי ששמואל סבור שאין להוסיף על הבהמה משא יתר! ומשיבים: \u0003סמי הא מקמי הא\u0004 \u0005[מחוק זו מלפני זו].\u0006","על כך תוהים: \u0003ומאי חזית דמסמית הא מקמי הא\u0004 \u0005[ומה ראית שמוחק אתה\u0006 הלכה \u0005זו מפני זו]?\u0006 \u0003סמי הא מקמי הא\u0004 \u0005[מחוק זו מפני זו]!\u0006 ומסבירים: לשיטה אחת יש חיזוק, \u0003דאשכחן\u0004 \u0005[ש\u0006כן \u0005מצאנו]\u0006 כי \u0003שמואל הוא\u0004 ש\u0003אמר\u0004 כי \u0003לנוי אסור\u0004 ו\u0003לשמר מותר. דאתמר\u0004 \u0005[שנאמר]:\u0006 שכן אמר \u0003רב חייא בר אשי אמר רב: בין לנוי בין לשמר\u0004 — \u0003אסור. ורב חייא בר אבין אמר שמואל: לנוי\u0004 — \u0003אסור\u0004 ו\u0003לשמר\u0004 — \u0003מותר.\u0004","לגופו של דבר \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: פרה אדומה ש\u0003קשרה בעליה במוסרה\u0004 (אפסר) — \u0003כשרה. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003משאוי הוא,\u0004 מדוע אם כן תוכשר הפרה? והלא מפורש \u0003\"\u0004דבר אל בני ישראל ויקחו אליך פרה אדומה תמימה אשר אין בה מום \u0003אשר לא עלה עליה עול\" אמר רחמנא\u0004 (במדבר יט, ב) \u0005[אמרה התורה],\u0006 ובודאי אם כן שנפסלת הפרה במשא!","\u0003אמר אביי:\u0004 המדובר הוא \u0003במוליכה מעיר לעיר,\u0004 שמאחר ומוליכה שלא במקומה הקבוע ודאי שצריכה היא שמירה יתירה, ובאופן כזה המוסרה היא הדרך הרגילה לקשרה ולכן אינה נחשבת למשא. \u0003רבא אמר: שאני\u0004 \u0005[שונה]\u0006 \u0003פרה\u0004 אדומה ש\u0003דמיה יקרין\u0004 (יקרים), ולכך שומרים אותה ביותר. \u0003רבינא אמר:\u0004 המדובר הוא \u0003במורדת,\u0004 פרה משתוללת וצריכה שמירה יותר מהרגיל.","שנינו במשנה ש\u0003הסוס\u0004 יוצא \u0003בשיר,\u0004 וכן כל שאר בעלי החיים יוצאים ונמשכים בשיר. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יוצאין\"? ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"נמשכין\"? אמר רב הונא: או יוצאין כרוכין,\u0004 שהוא מניח את הרצועה כרוכה על צוארה של הבהמה ואינו מושכה בה אלא היא עשוייה לנוי, או \u0003נמשכין\u0004 באמצעות רצועה המחוברת לשיר. \u0003ושמואל אמר:\u0004 בעלי חיים אלה \u0003יוצאין\u0004 כשהם \u0003נמשכין\u0004 ברצועה, \u0003ואין\u0004 הם \u0003יוצאין\u0004 כשהם רק \u0003כרוכין.\u0004","ו\u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו]:\u0006 \u0003יוצאין כרוכין לימשך\u0004 (להימשך), שכורכים אותם בלא חוזק, אלא רק באופן שאפשר יהיה להחזיקם ולמושכם. \u0003אמר רב יוסף: חזינא להן לעיגלי דבי\u0004 \u0005[ראיתי אותם, את העגלים של בית]\u0006 \u0003רב הונא\u0004 שהיה בעל אחוזה שהם \u0003יוצאין באפסריהן\u0004 כשהם \u0003כרוכין\u0004 עליהם \u0003בשבת.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' חנינא: מולאות\u0004 \u0005[פרדות]\u0006 \u0003של בית רבי יוצאות\u0004 היו \u0003באפסריהן בשבת. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: האם הכוונה שהיו הפרדות יוצאות באפסרים \u0003כרוכין\u0004 בלבד \u0003או\u0004 שהיו \u0003נמשכין\u0004 בהם?","כדי לפתור זאת \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שסיפרו ש\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' חנינא: מולאות של בית רבי\u0004 היו \u0003יוצאות באפסריהן\u0004 כשהם רק \u0003כרוכים\u0004 עליהם \u0003בשבת.\u0004","\u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב אסי: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שמסר \u0003רב שמואל בר יהודה לא צריכא\u0004 \u0005[אינה צריכה],\u0006 כי הלכה זו \u0003מ\u0004דברי \u0003רב דימי נפקא\u0004 \u0005[\u0006היא \u0005יוצאת].\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר ש\u0003רב דימי\u0004 רצה לספר שהפרדים של בית רבי היו \u0003נמשכין\u0004 בלבד, הרי לא היה בכך כל חידוש, כי \u0003מ\u0004דברי \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005].\u0006","ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מחליפין היו לפני רבי\u0004 רצועות המיוחדות \u0003של זו,\u0004 בעל חיים אחד, ונתנו \u0003בזו,\u0004 בבעל חיים אחר שדרכו באחרת, \u0003מהו\u0004 הדין בכגון זה, האם יכולים לצאת בהם בשבת? \u0003אמר לפניו ר' ישמעאל בר' יוסי, כך אמר אבא: ארבע בהמות יוצאות באפסר, הסוס והפרד והגמל והחמור.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אסי\u0004 לחכמים ששאלוהו: \u0003איצטריך להו\u0004 \u0005[\u0006יש \u0005צורך להם]\u0006 לשמוע גם את דברי רב שמואל בר יהודה. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה\u0004 שסיפר על מה שאמר ר' ישמעאל בר' יוסי לפני רבי \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 הדבר, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאמנם \u0003אמר לפניו\u0004 ר' ישמעאל בר' יוסי, \u0003ו\u0004אולם \u0003רבי לא קיבלה מיניה\u0004 \u0005[ממנו]\u0006 הלכה זו. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 מה שאמר \u0003רב דימי\u0004 שהפרדות בבית רבי אכן היו יוצאות באפסר.","\u0003ואי\u0004 \u0005[ואם]\u0006 מדברי \u0003רב דימי\u0004 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 שמותר לפרדים לצאת באפסר הרי זה רק באופן שהם \u0003נמשכין\u0004 באפסר, \u0003אבל\u0004 כאשר הם רק \u0003כרוכין\u0004 באפסר — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הלכה זו של \u0003רב שמואל בר רב יהודה.\u0004","שנינו במשנה שטבעות הבהמה אם נטמאו \u0003מזין עליהן\u0004 כשהם על \u0003הבהמה ו\u0004כן \u0003טובלן במקומן,\u0004 על הבהמה, שמטביל את הבהמה והטבעות עליה. ותוהים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 ש\u0003בני קבולי\u0004 \u0005[קבלת]\u0006 \u0003טומאה,\u0004 כלומר, ראויות לקבל טומאה \u0003נינהו\u0004 \u0005[הן]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003טבעת אדם\u0004 — \u0003טמאה. וטבעת בהמה ו\u0004כן טבעת של \u0003כלים ושאר כל הטבעות\u0004 שאינן לצורך בני אדם, אף אם נגעה בהן טומאה —"],["הריהן \u0003טהורות,\u0004 שרק כלי אדם מקבלים טומאה.","\u0003אמר ר' יצחק נפחא:\u0004 המדובר הוא \u0003בבאין מנוי אדם לנוי בהמה,\u0004 שתכשיטים אלה היו שייכים בשעתם לאדם, ואחר כך צירפם לרצועת בהמה, וטומאתם שהיתה בהם קודם, עדיין לא בטלה.","\u0003רב יוסף אמר\u0004 תירוץ איחר: טבעות הבהמה טמאות \u0003הואיל ואדם מושך בהם את הבהמה,\u0004 ואם כן כלי שימושו של אדם הן. \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 כעין זה: \u0003מקל של בהמה\u0004 שבו רודים בבהמה לכוונה בדרך, אם הוא \u0003של מתכת\u0004 הריהו \u0003מקבל טומאה. מה טעם\u0004 מקבלות הן טומאה אף שהן כלי בהמה? — \u0003הואיל ואדם רודה בהן\u0004 ולכן המקל הוא לצורך האדם, ונטמא. \u0003הכא נמי\u0004 \u0005[כך גם כאן]\u0006 בענין הטבעות, \u0003הואיל ואדם מושך בהן,\u0004 הריהן נעשות ככלי אדם.","שנינו במשנה שאת הטבעות שנטמאו \u0003טובלן במקומן\u0004 בצוארה של הבהמה. ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003חציצה,\u0004 שהטבעת בדרך כלל צמודה היטב לשיר, ואין מקום למים לחדור, ובמקרה כזה אין הטבילה מועילה כי דרוש שהמים יוכלו להקיף את הדבר הנטבל מכל צדדיו!","\u0003אמר ר' אמי:\u0004 המדובר הוא \u0003בשריתכן,\u0004 שהיכה בהן בפטיש והרחיב בכך את הרווח בין הטבעות המרכיבות את השיר, שיוכלו המים להיכנס.","ומעירים: \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003ר' אמי כרב יוסף סבירא ליה\u0004 \u0005[סבור הוא]\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שמבין הוא את המשנה \u0003כר' יצחק,\u0004 ש\u0003אמר\u0004 שמדובר כאן \u0003בבאין מנוי אדם לנוי בהמה\u0004 ולכן שייכת בהן טומאה, ו\u0003הרי כיון\u0004 ש\u0003ריתכן\u0004 הלא בכך \u0003עבד בהו\u0004 \u0005[עשה בהן]\u0006 \u0003מעשה ו\u0004בכך \u0003פרחה לה\u0004 ה\u0003טומאה מינייהו\u0004 \u0005[מהן].\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הכלים יורדין לידי טומאתן במחשבה,\u0004 שאף שכלל הוא שכלי בלתי גמור אינו ראוי לקבל טומאה, אם חשב האומן שלא לעבדו יותר — מיד נעשה הוא ככלי גמור, ומקבל טומאה, \u0003ו\u0004אולם \u0003אין\u0004 הכלים \u0003עולין מטומאתן\u0004 (נטהרים) \u0003אלא בשינוי מעשה,\u0004 שאם שבר את הכלי הטמא — שוב אינו טמא. ומכל מקום למדנו כי שינוי מעשה ודאי משנה את מהותו של הכלי מבחינת הטומאה, וריתוך הטבעת הלא הוא שינוי מעשה, הצריך לטהרה מטומאה שקיבלה בעבר!","ודוחים: יתכן ש\u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 ר' אמי בענין זה \u0003כר' יהודה,\u0004 ש\u0003אמר\u0004 ש\u0003מעשה\u0004 שנעשה בכלי במטרה \u0003לתקן\u0004 ולשפר אותו \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מעשה הוא\u0004 לענין זה שיהא הכלי המתוקן נטהר מטומאתו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יהודה אומר: לא אמר\u0004 החכם ש\u0003שינוי מעשה\u0004 בכלי נחשב כביטולו ובכך טהרתו כאשר שינוי \u0003זה הוא לתקן, אלא\u0004 רק כאשר אותו שינוי נעשה בכוונה כדי \u0003לקלקל\u0004 אותו, וכמו שבירתו.","\u0003במתניתא תני\u0004 \u0005[בברייתא שנה\u0006 החכם\u0005]\u0006 שמשנתנו עוסקת \u0003במחוללין,\u0004 שהיה מלכתחילה חלל בין הטבעות המרכיבות את השיר, והמים נכנסים לתוכן ברווח.","בתוספתא שנינו: \u0003שאל תלמיד אחד מגליל העליון את ר' אליעזר: שמעתי שחולקין\u0004 לענין הלכה \u0003בין טבעת לטבעת,\u0004 לפי סוגה של כל טבעת, אבל לא ידע במה המדובר. \u0003אמר לו\u0004 ר' אליעזר: \u0003שמא לא שמעת\u0004 שיש חילוק כזה \u0003אלא לענין שבת,\u0004 ששם מחלקים בין טבעת העשויה לנוי, שמותר לטלטלה בשבת, וטבעות אחרות האסורות בטלטול. \u0003דאי\u0004 \u0005[שאם]\u0006 תחשוב ששמעת כן \u0003לענין טומאה,\u0004 אין הדבר יכול להיות, שכן \u0003דא ודא חדא\u0004 \u0005[זו וזו אחת]\u0006 \u0003היא,\u0004 ואין חילוק בהלכות טומאה.","ומקשים: \u0003ולענין טומאה דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 במפורש: \u0003טבעת אדם טמאה וטבעת בהמה ו\u0004טבעת \u0003כלים ושאר כל הטבעות טהורות,\u0004 והרי שיש חילוק לענין הלכות טומאה בין סוגי הטבעות! ומתרצים: \u0003כי קאמר ליה איהו, נמי\u0004 \u0005[כאשר אמר לו הוא,\u0006 אותו תלמיד, \u0005גם כן]\u0006 בטבעת של \u0003אדם קאמר ליה\u0004 \u0005[אמר לו],\u0006 ובטבעת אדם אין לחלק.","ועוד תוהים: \u0003ו\u0004האם בטבעות של \u0003אדם דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טבעת שהתקינה\u0004 בראשה של חגורה \u0003לחגור בה\u0004 את \u0003מתניו, ו\u0004כן אם עשאה כדי \u0003לקשר בה בין כתפיו\u0004 — \u0003טהורה\u0004 מלקבל טומאה, \u0003ולא אמרו\u0004 על טבעת אדם שהיא \u0003טמאה אלא\u0004 בטבעת \u0003של אצבע בלבד,\u0004 והרי שאף בטבעות אדם יש חילוק! ומתרצים: \u0003כי קאמר ליה איהו, נמי\u0004 \u0005[כאשר אמר לו הוא,\u0006 אותו תלמיד, \u0005גם כן]\u0006 בטבעת של \u0003אצבע קאמר ליה\u0004 \u0005[אמר לו],\u0006 ולא דיברו בטבעות אחרות ובין טבעות האצבע למיניהן אין אכן חילוק.","ועוד מקשים: \u0003ו\u0004בטבעת של \u0003אצבע\u0004 עצמה \u0003דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003טבעת של מתכת וחותמה של אלמוג\u0004 — \u0003טמאה,\u0004 כי הולכים אחר עיקרה של הטבעת, ובתור כלי מתכת מקבלת היא טומאה. אבל אם היתה הטבעת כולה \u0003של אלמוג וחותמה של מתכת\u0004 — \u0003טהורה,\u0004 והרי שיש חילוק בענין טומאה אף בטבעות של אצבע! ומתרצים: \u0003כי קאמר ליה איהו, נמי\u0004 \u0005[כאשר אמר לו הוא,\u0006 אותו תלמיד, \u0005גם כן]\u0006 בטבעת \u0003שכולה של מתכת קאמר ליה\u0004 \u0005[אמר לו],\u0006 ובענין זה אין לחלק בהלכות טומאה.","\u0003ועוד שאל\u0004 אותו תלמיד: \u0003שמעתי שחולקין\u0004 להלכה \u0003בין מחט למחט. אמר ליה\u0004 \u0005[לו]\u0006 ר' אליעזר: \u0003שמא לא שמעת\u0004 שיש חילוק \u0003כזה אלא לענין שבת, דאי\u0004 \u0005[שאם]\u0006 \u0003לענין טומאה\u0004 הלא \u0003דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא.\u0004","על כך שואלים: \u0003ולענין טומאה דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מחט שניטל חורה או עוקצה\u0004 (חודה) — \u0003טהורה,\u0004 כי אינה ראויה לשמש עוד למלאכתה, הרי שיש חילוק בין מחט שלמה לשבורה! ומתרצים: \u0003כי קאמר ליה\u0004 \u0005[כאשר אמר לו]\u0006 שיש חילוק בין מחט למחט היה זה \u0003ב\u0004מחט \u0003שלימה,\u0004 ובשלימה אין חילוק בין המחטים.","ועוד שואלים: \u0003ו\u0004האם \u0003ב\u0004מחט \u0003שלימה\u0004 תמיד \u0003דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003מחט שהעלתה חלודה, אם\u0004 חלודה זו רבה עד שיש בשימוש בה קושי לתפור והוא \u0003מעכב את התפירה\u0004 — \u0003טהורה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003טמאה. ואמרי דבי\u0004 \u0005[ואמרו\u0006 בני \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ינאי: והוא שרישומה\u0004 של החלודה \u0003ניכר\u0004 בתפירה. ולא עד שממש אי אפשר לתחוב את המחט בבד. ומכל מקום למדים אנו שאף במחט שלימה יש חילוק! ומתרצים: \u0003כי קאמר ליה\u0004 \u0005[כאשר אמר לו]\u0006 אותו תלמיד הרי \u0003בשיפא קאמר ליה\u0004 \u0005[ב\u0006מחט \u0005משוייפת\u0006 וחלקה \u0005אמר לו],\u0006 ובחלודה לא דיבר.","ועוד מקשים: \u0003ובשיפא דא ודא\u0004 \u0005[ו\u0006האם \u0005ב\u0006מחט \u0005משוייפת\u0006 וחלקה \u0005זו וזו]\u0006 \u0003אחת היא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מחט בין\u0004 שהיא \u0003נקובה\u0004 (שיש בה נקב להשחלת חוט), \u0003בין\u0004 ש\u0003אינה נקובה מותר לטלטלה בשבת, ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 שיש הבדל בין ה\u0003נקובה\u0004 לשאינה נקובה \u0003אלא לענין טומאה בלבד,\u0004 והרי שיש הבדל בין מחט למחט לדיני טומאה!","ומשיבים: \u0003הא תרגמה\u0004 \u0005[הרי\u0006 כבר \u0005הסבירה]\u0006 \u0003אביי אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003רבא\u0004 שהמדובר הוא \u0003בגלמי\u0004 \u0005[ב\u0006מחט \u0005גולמית],\u0006 במחט שלא עובדה עדיין, וצריכים עוד לעשות בה נקב, שיש הבדל בין מחט נקובה שהינה כבר כלי מושלם ואין הבדל לענין טומאה, לבין מחט שאינה נקובה שאינה עדיין בגדר כלי.","\u0003חמור יוצא במרדעת\u0004 (כעין אוכף העשוי לחמם את גופו של החמור) \u0003בזמן שהיא קשורה בו\u0004 ואין לחשוש לנפילתה. \u0003זכרים\u0004 (אילים) \u0003יוצאים לבובין,\u0004 וה\u0003רחלות יוצאות שחוזות, כבולות וכבונות.\u0004 וכל המונחים הללו נידונים ומתבארים אחר כך בגמרא. \u0003העזים יוצאות צרורות,\u0004 שקושרים את עטיניהן. \u0003ר' יוסי אוסר בכולן, חוץ מן הרחלים הכבונות\u0004 ואת כל השאר חושב הוא כמשאוי.","\u0003ר' יהודה אומר: עזים יוצאות צרורות ליבש,\u0004 כלומר, כאשר קושרים את עטיניהם כדי שתפסיק העז לתת חלב (בדרך כלל לפני לידתה), שאז קושרים קשר יציב וקבוע, \u0003אבל לא\u0004 יוצאות העיזים כשהן צרורות בשבת אם המטרה היא \u0003ל\u0004צורך ה\u0003חלב\u0004 שישתמר."],["\u0003אמר שמואל:\u0004 מה ששנינו שהחמור יוצא בשבת במרדעת, \u0003והוא\u0004 דווקא באופן שהמרדעת \u0003שקשורה לו מערב שבת. אמר רב נחמן: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כך, \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בהמשך הפרק: \u0003אין החמור יוצא\u0004 בשבת \u0003במרדעת בזמן שאינה קשורה לו.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמדובר באופן \u0003שאינה קשורה לו כלל\u0004 — הרי דבר זה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שיש לחשוש \u0003דילמא נפלה ליה ואתי לאתויי\u0004 \u0005[שמא תיפול לו\u0006 המרדעת \u0005ויבוא\u0006 בעל החמור \u0005להביאה]\u0006 ברשות הרבים. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שהכוונה \u0003שאינה קשורה מערב שבת.\u0004 ו\u0003מכלל\u0004 הדברים נלמד \u0003דרישא\u0004 \u0005[שראש,\u0006 התחלת המשנה\u0005],\u0006 כלומר, משנתנו שלנו המתירה במרדעת ומציינת שזהו דווקא כאשר היא קשורה לו, הכוונה היא \u0003שקשורה לו מערב שבת.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003חמור יוצא\u0004 בשבת \u0003במרדעת בזמן שקשורה לו מערב שבת, ו\u0004אולם \u0003לא\u0004 יצא החמור \u0003באוכף אף על פי שקשורה לו מערב שבת. רבן שמעון בן גמליאל אומר: אף\u0004 יוצא החמור \u0003באוכף בזמן שקשורה לו מערב שבת, ובלבד שלא יקשור לו מסריכן\u0004 (רצועת רתמה), \u0003ובלבד שלא יפשול לו רצועה תחת זנבו\u0004 כדרך שנוהגים לקשור את האוכף כרגיל.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב אסי בר נתן מר' חייא בר אשי: מהו\u0004 הדין לענין \u0003ליתן מרדעת על גבי חמור בשבת\u0004 בחצר רשות היחיד כדי שיתחמם, בלא להוציאו לרשות הרבים כשמרדעתו עליו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מותר. אמר ליה\u0004 \u0005[לו]\u0006 רב אסי בר נתן: \u0003וכי מה בין זה לאוכף,\u0004 שאסור לטלטלו בשבת? \u0003אישתיק\u0004 \u0005[שתק]\u0006 ר' חייא בר אשי ולא ענה. וחשב רב אסי בר נתן שסבור ר' חייא שאף אוכף מותר להניח.","על כן \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003אוכף שעל גבי חמור\u0004 ורוצה בעליו להסירה מעליו — \u0003לא יטלטלנה בידו\u0004 להסירה מעליו, \u0003אלא מוליכה\u0004 (את הבהמה) \u0003ומביאה בחצר, ו\u0004על ידי הליכתה זו של הבהמה \u0003הוא,\u0004 האוכף, \u0003נופל מאיליו.\u0004 ואם כן, \u0003השתא\u0004 \u0005[עכשיו]\u0006 לענין \u0003ליטול\u0004 את האוכף מעל החמור \u0003אמרת\u0004 ש\u0003לא\u0004 יטול, \u0003להניח מיבעיא\u0004 \u0005[צריך לומר]\u0006 שאסור?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא\u0004 לרב אסי: \u0003שבקיה\u0004 \u0005[עזוב אותו]\u0006 את ר' חייא, ואל תקשה עליו, שכן הוא \u0003כרביה סבירא ליה\u0004 \u0005[כרבו הוא סבור],\u0006 ש\u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: תולין טרסקל\u0004 (אמתחת שבהמות אוכלות ממנה) \u0003לבהמה בשבת, וקל וחומר למרדעת\u0004 שמותר להניחה על גבי בהמה בשבת. ומהו קל וחומר זה? — \u0003ומה התם\u0004 \u0005[שם]\u0006 בענין טרסקל שיש בו רק \u0003משום תענוג\u0004 — \u0003שרי\u0004 \u0005[מותר],\u0006 שכיון שנוח לבהמה לאכול מן הטרסקל ולא להתכופף — מותר שתישא את הטרסקל, \u0003הכא\u0004 \u0005[כאן]\u0006 בענין המרדעת ש\u0003משום צער\u0004 הבהמה שמים אותה, שלא תסבול מן הקור — \u0003לא כל שכן\u0004 שמותר.","\u0003שמואל אמר:\u0004 ב\u0003מרדעת מותר\u0004 לחמור לצאת בשבת, \u0003ו\u0004אולם ב\u0003טרסקל\u0004 — \u0003אסור. אזל\u0004 \u0005[הלך]\u0006 \u0003ר' חייא בר יוסף אמרה לשמעתא\u0004 \u0005[להלכה]\u0006 זו של \u0003רב קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל. אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אמר אבא,\u0004 רב, \u0003לא ידע במילי דשבתא\u0004 \u0005[אינו יודע בדברי,\u0006 דיני, \u0005שבת]\u0006 \u0003ולא כלום.\u0004","\u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' זירא\u0004 לארץ ישראל \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003לר' בנימין בר יפת דיתיב וקאמר ליה משמיה\u0004 \u0005[שיושב ואומר לו משמו]\u0006 של \u0003ר' יוחנן\u0004 הלכה זו: \u0003נותנין מרדעת על גבי חמור בשבת. אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003יישר\u0004 \u0005[יפה,\u0006 נכון \u0005אמרת\u0006\u0005],\u0006 \u0003וכן תרגמה\u0004 \u0005[תרגם,\u0006 אמר, \u0005אותה]\u0006 \u0003אריוך בבבל.\u0004","ואומרים: \u0003\"אריוך\" מנו\u0004 \u0005[\u0006כינוי של \u0005מי הוא]\u0006 — של \u0003שמואל. והא\u0004 \u0005[והרי]\u0006 \u0003רב נמי\u0004 \u0005[גם כן]\u0006 \u0003אמרה,\u0004 שהרי בענין מרדעת שניהם הסכימו לאותו דבר, ומדוע ייחס זאת לשמואל דווקא? \u0003אלא שמעיה דהוה מסיים ביה\u0004 \u0005[שמע אותו שהיה מסיים בה,\u0006 בהלכה זו\u0005]:\u0006 \u0003ואין תולין טרסקל\u0004 לבהמה \u0003בשבת\u0004 ועל כך \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יישר, וכן תרגמה אריוך\u0004 \u0005[תרגם,\u0006 אמר, \u0005אותה]\u0006 \u0003בבבל.\u0004","\u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל על כל פנים]\u0006 \u0003מרדעת מותר\u0004 לשים על החמור בשבת, ויש לשאול אם כן \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 הדבר \u0003מאוכף,\u0004 שכפי ששנינו אסור אפילו להורידו מעל גבי החמור? ואם מתחשבים אנו בצער בעלי חיים — מדוע לא יתירו גם להוריד את האוכף מעל החמור? ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בדין אוכף שלא התירו להסירו בידים משום ש\u0003אפשר דנפיל ממילא\u0004 \u0005[שיפול מעצמו].\u0006","\u0003רב פפא אמר,\u0004 יש לחלק בין הדברים כך: \u0003כאן\u0004 כשהתירו לשים מרדעת על החמור בשבת היה זה כדי \u0003לחממה, וכאן\u0004 שאסרו להסיר את האוכף היה זה כדי \u0003לצננה.\u0004 וההבדל ביניהם הוא, שאם יניח עליה את המרדעת כדי \u0003לחממה,\u0004 הרי תשאר בקור ו\u0003אית\u0004 \u0005[ויש]\u0006 \u0003לה\u0004 בכך \u0003צערא,\u0004 ולכן התירו. ואולם אף אם לא יסיר מהחמור את האוכף כדי \u0003לצננה,\u0004 הרי החמור אינו סובל מחום יתר, ו\u0003לית\u0004 \u0005[ואין]\u0006 \u0003לה\u0004 בשל כך \u0003צערא\u0004 \u0005[צער],\u0006 ויכול הוא שיישאר באוכף. \u0003והיינו דאמרי אינשי\u0004 \u0005[וזהו שאומרים אנשים]\u0006 כפתגם עממי: \u0003חמרא\u0004 \u0005[חמור]\u0006 \u0003אפילו בתקופת תמוז קרירא\u0004 \u0005[קר]\u0006 \u0003לה,\u0004 וחשוב אם כן יותר לדאוג לחימומו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על אותם חכמים שאסרו לשים את הטרסקל, ממה שנינו בתוספתא: \u0003לא יצא הסוס\u0004 בשבת \u0003בזנב שועל\u0004 שתולים לו כסגולה למניעת עין הרע, \u0003ולא בזהרורית\u0004 (צמר אדום) \u0003ש\u0004תולים לו לנוי \u0003בין עיניו.\u0004 וכן \u0003לא יצא\u0004 האדם \u0003הזב בכיס שלו\u0004 שהוא שם כדי שלא יתלכלכו בגדיו בזוב, \u0003ולא עזים בכיס ש\u0004תולים \u0003בדדיהן\u0004 כדי שלא ישרטו מהאבנים, \u0003ולא פרה בחסום\u0004 (זמם) \u0003שבפיה, ולא סייחים בטרסקלין שבפיהם לרשות הרבים. ולא\u0004 תצא \u0003בהמה בסנדל\u0004 של מתכת \u0003ש\u0004שמים \u0003ברגליה, ולא בקמיע\u0004 שתולים בה לבריאותה \u0003אף על פי ש\u0004קמיע זה \u0003הוא\u0004 של \u0003מומחה\u0004 ונבדק והוכח שהוא מועיל. \u0003ו\u0004בנקודה \u0003זו חומר בבהמה מבאדם,\u0004 שלאדם מותר לצאת בקמיע שהוכחה תועלתו.","\u0003אבל יוצא הוא באגד\u0004 (תחבושת) \u0003שעל גבי המכה, ובקשישין\u0004 (חתיכות עץ) \u0003ש\u0004מניחים \u0003אותן על גבי השבר\u0004 לקיבוע האבר השבור, לשמור שלא יתפרקו העצמות השבורות ממקומן ויתאחו שנית, \u0003ובשיליא המדולדלת בה\u0004 שלא יצאה עם לידת הולד. \u0003ופוקקין לה\u0004 במוך את ה\u0003זוג\u0004 (פעמון) התלוי \u0003בצוארה\u0004 כדי שלא יוכל הענבל לקשקש בתוכו ולהשמיע קול, \u0003ומטיילת עמו\u0004 כשהוא פקוק \u0003בחצר\u0004 שהיא רשות היחיד, אבל לא ברשות הרבים.","\u0003קתני מיהת\u0004 \u0005[שנינו בכל אופן]:\u0006 \u0003ולא\u0004 יצאו ה\u0003סייחין\u0004 בשבת \u0003בטרסקלים שבפיהם לרשות הרבים.\u0004 ונדייק: \u0003לרשות הרבים הוא\u0004 ש\u0003לא\u0004 הותר שתצאנה הבהמות עם הטרסקל, \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003בחצר\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005,\u0006 ו\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ב\u0004סייחים \u0003גדולים\u0004 שתולים את הטרסקלים בצוארם \u0003משום תענוג?!\u0004","ומשיבים: \u0003לא,\u0004 המדובר הוא \u0003ב\u0004סייחים \u0003קטנים, ו\u0004התירו זאת \u0003משום צער,\u0004 כי סייחים אלה כיון שרגליהם ארוכות וצוארם קצר עדיין, קשה להם לאכול עשב מן הקרקע, ותולים עליהם את הטרסקל כדי שלא יצטערו בזמן האכילה. ומוסיפים: \u0003דיקא נמי\u0004 \u0005[מדוייק\u0006 הדבר \u0005גם כן]\u0006 על פי העיון בהקשר, \u0003דקתני\u0004 \u0005[ששנה]\u0006 דבר זה"],["\u0003דומיא\u0004 \u0005בדומה\u0006 ל\u0003קמיע\u0004 ששמים אותו לרפואה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","קודם הוזכר ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שהבהמה \u0003לא\u0004 יוצאת \u0003בקמיע אף על פי ש\u0004קמיע זה \u0003הוא\u0004 של \u0003מומחה\u0004 ונבדק והוכח שהוא מועיל. ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 ש\u0003לא\u0004 יוצא אדם בשבת \u0003בקמיע שאינו\u0004 של \u0003מומחה,\u0004 ומשמע: \u0003הא\u0004 \u0005[הרי]\u0006 אם של \u0003מומחה\u0004 הוא — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005]!\u0006 ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר שמדובר באופן \u0003שאינו\u0004 של \u0003מומחה.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אף על פי שהוא מומחה\" קתני\u0004 \u0005[שנה]!\u0006 ומשיבים: הכוונה היא שקמיע זה \u0003מומחה לאדם ואינו מומחה לבהמה.\u0004 ותוהים: \u0003וכי איכא\u0004 \u0005[והאם יש]\u0006 קמיע שהוא \u0003מומחה לאדם ולא הוי\u0004 \u0005[ואינו]\u0006 \u0003מומחה לבהמה?\u0004 שלכאורה רפואת הבהמה קלה יותר מרפואת האדם. ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 אפשר להבין את הדבר, כי \u0003אדם\u0004 כיון \u0003דאית ליה מזלא\u0004 \u0005[שיש לו מזל,\u0006 מלאך המגן עליו\u0005]\u0006 — \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הקמיע, \u0003בהמה דלית\u0004 \u0005[שאין]\u0006 \u0003לה מזלא\u0004 \u0005[מזל]\u0006 — \u0003לא מסייע לה\u0004 הקמיע.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר בקמיע שאינו מומחה לבהמה, ואולם בזה שהוא מומחה לבהמה אף לבהמה מותר לצאת, \u0003מאי\u0004 \u0005[מהו]\u0006 אם כן זה ששנינו בברייתא \u0003\"זה חומר בבהמה מבאדם\"?\u0004 והרי דינם שווה, שהרי קמיע שאינו מומחה אף אדם אסור לו לטלטלו, בשבת והמומחה אף לבהמה מותר לצאת בו! ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי מאמר זה על \u0003קמיע קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מוסב\u0005]?\u0006 על \u0003סנדל קאי\u0004 \u0005[הוא עומד,\u0006 מוסב\u0005],\u0006 שאף שאין הבהמה יוצאת בשבת כשסנדל לרגלה, לאדם מותר. לגוף הענין אם מתחשבים ועד כמה מתחשבים בצער בעלי חיים בשבת מביאים ראייה ממה ששנינו בברייתא.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003סכין ומפרכסין\u0004 (מורידים קרומים קשים שעל גבי הפצע) בשבת \u0003לאדם, ואין סכין ומפרכסין לבהמה. מאי לאו דאיכא\u0004 \u0005[האם לא\u0006 מדובר באופן \u0005שיש]\u0006 \u0003מכה\u0004 (פצע) \u0003ומשום צער,\u0004 ובכל זאת הותר לאדם ולא לבהמה! ודוחים: \u0003לא,\u0004 מדובר באופן \u0003דגמר\u0004 \u0005[שנגמרה,\u0006 נתרפאה\u0005]\u0006 ה\u0003מכה ו\u0004הסיכה והפירכוס הם רק \u0003משום תענוג\u0004 ונוחיות יתירה.","ושוב מנסים להוכיח: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003בהמה שאחזה דם\u0004 ועלה חומה, \u0003אין מעמידין אותה במים בשביל שתצטנן. אדם שאחזו דם, מעמידין אותו במים בשביל שיצטנן.\u0004 והרי שאין חוששים לצערה של הבהמה! \u0003אמר עולא:\u0004 כאן נאסר הדבר כדרך שנאסר כל דבר רפואה בשבת, \u0003גזירה משום שחיקת סממנין\u0004 כי חלק מן הרפואה הוא שחיקתם של הסממנים המרכיבים את הרפואות, ודבר זה אסור מן התורה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ב\u0003אדם נמי\u0004 \u0005[גם כן]\u0006 יגזרו כמו כן, ויאסר לו להכנס למים ולהצטנן בהם, משום האיסור על רפואה בשבת! ומשיבים: \u0003אדם נראה כמיקר,\u0004 שכשאדם נכנס למים אין זה מוכרח שעושה זאת כדי להתרפא, אלא יתכן שרצונו לצנן עצמו מעט.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003בהמה נמי\u0004 \u0005[גם כן]\u0006 כאשר היא בתוך המים \u0003נראה\u0004 הדבר \u0003כמיקר\u0004 \u0005[כ\u0006אילו ירדה למים \u0005לצנן\u0006 עצמה\u0005]\u0006 ולא לרפואה! ומשיבים: \u0003אין מיקר לבהמה,\u0004 שאין דרכה של הבהמה לרדת למים בעצמה, או שיורידוה לשם צינון בלבד, ואם נמצאת היא במים הרי זה מוכיח שנעשה הדבר לצורך רפואה.","ולעיקרו של דבר, שמשום גזירה מחמירים עד כדי שתמות הבהמה במחלה, שואלים: \u0003ולבהמה מי גזרינן\u0004 \u0005[האם גוזרים אנו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 בהמה ש\u0003היתה עומדת חוץ לתחום\u0004 שבת שאסור לאדם לצאת למקומה, \u0003קורא לה והיא באה\u0004 מעצמה. \u0003ו\u0004הרי ש\u0003לא גזרינן דילמא אתי לאתויי\u0004 \u0005[גוזרים אנו שמא יבוא\u0006 הוא \u0005להביאה],\u0006 והרי שבמקום הפסד לא גזרו חכמים במקום שאין עבירה בפועל לגבי אדם.","\u0003ו\u0004על כך \u0003אמר רבינא:\u0004 אין להביא ראייה מהלכה זו, כי מדובר ב\u0003כגון שהיה תחום שלה מובלע בתוך תחום שלו.\u0004 כלומר, תחום השבת שמותר להוביל בו את הבהמה לא היה זהה לתחום שהוא עצמו מותר לו ללכת בו, ששל הבהמה מסתיים קרוב יותר מזה שלו, ואף שאסור היה להוציא את הבהמה מחוץ לתחומה, ואולם המקום שעמדה בו כיון שהוא נמצא בתוך תחומו של בעל הבהמה הריהו רשאי להגיע לשם ולקחת אותה, ולכן לא גזרו כאשר הוא קורא לה, שאף אם היה בא לשם בעצמו לא היה בכך איסור. ולמה שעושה הבהמה עצמה, שיצאה מחוץ לתחומה, איננו חשים כלל.","\u0003רב נחמן בר יצחק אמר: שחיקת סממנין גופה תנאי\u0004 \u0005[\u0006במחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 שיש חכמים שאסרו כל ריפוי בהמה משום גזירה זו, ויש שהתירו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בהמה שאכלה כרשינין\u0004 הרבה והיא נעצרת במעיה ועשוייה לבוא לידי סכנה \u0003לא יריצנה בחצר בשביל שתתרפה\u0004 (תשתלשל), מחשש גזירת רפואה. \u0003ור' אושעיא מתיר.\u0004 הרי שברפואות שאין בעשייתן משום מלאכה נחלקו התנאים אם יש לגזור משום שחיקת סממנים. \u0003דרש רבא: הלכה\u0004 בענין זה \u0003כר' אושעיא.\u0004","שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא ש\u0003לא יצא הזב בכיס שלו ולא עזים בכיס שבדדיהן.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 מפורשת ש\u0003יוצאות עזים בכיס שבדדיהן!\u0004","\u0003אמר רב יהודה: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שיוצאות, הרי זה באופן \u0003דמיהדק\u0004 \u0005[שמהודק]\u0006 הכיס בדד ואין חשש שיפול, ולכן מותר. \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאינן יוצאות, הרי זה באופן \u0003דלא מיהדק\u0004 \u0005[שאינו מהודק].\u0006","\u0003רב יוסף אמר:\u0004 וכי \u0003תנאי שקלת מעלמא\u0004 \u0005[\u0006את \u0005התנאים הוצאת מן העולם]?\u0006 הלא \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]\u0006 \u0003העזים יוצאות\u0004 כשהן \u0003צרורות,\u0004 שעטיניהן קשורים. ו\u0003ר' יוסי אוסר בכלן חוץ מן הרחילות הכבונות. ר' יהודה אומר: עזים יוצאות\u0004 כשהן \u0003צרורות ליבש,\u0004 כלומר, כאשר קושרים את עטיניהם כדי שתפסיק העז לתת חלב (בדרך כלל לפני לידתה), שאז קושרים קשר יציב וקבוע, \u0003אבל לא\u0004 יוצאות העיזים כשהן צרורות בשבת אם המטרה היא \u0003ליחלב\u0004 \u0005[לצורך החלב]\u0006 שישתמר. הרי שבענין כיסים על עטיני העיזים יש תנאים אוסרים ומתירים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003הא והא\u0004 \u0005[זו וזו,\u0006 שתי הברייתות\u0005]\u0006 כדברי \u0003ר' יהודה, ולא קשיא\u0004 \u0005[ואינו קשה],\u0006 \u0003כאן\u0004 שהתירו לעיזים לצאת בכיס היה זה כששמו את הכיס \u0003ליבש,\u0004 ו\u0003כאן\u0004 כשאסרו היה זה \u0003ליחלב.\u0004","ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה: מעשה בעזים\u0004 מ\u0003בית אנטוכיא שהיו דדיהן גסין\u0004 (גדולים) והיו נגררים על הקרקע ונשרטים, \u0003ועשו להן כיסין כדי שלא יסרטו דדיהן.\u0004","כיון שדובר בענין הדדים מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מעשה באחד שמתה אשתו והניחה\u0004 לו \u0003בן\u0004 שהיה צריך \u0003לינק ולא היה לו שכר מניקה ליתן, ונעשה לו נס ונפתחו לו דדין כשני דדי אשה והניק את בנו.\u0004","\u0003אמר רב יוסף: בוא וראה כמה גדול אדם זה שנעשה לו נס כזה! אמר לו אביי: אדרבא\u0004 (להיפך) \u0003כמה גרוע אדם זה שנשתנו לו סדרי בראשית.\u0004 שאף שאירע לו נס, מכל מקום בצורה לא נוחה ולא נעימה אירע לו.","והוסיף ו\u0003אמר רב יהודה: בוא וראה כמה קשים מזונותיו של אדם\u0004 להשיגם, \u0003שנשתנו עליו סדרי בראשית\u0004 וקרוב היה יותר הדבר מלהמציא לו פרנסה. \u0003אמר רב נחמן: תדע\u0004 שכן הוא, \u0003דמתרחיש ניסא\u0004 \u0005[שמתרחש נס]\u0006 לכמה בני אדם \u0003ו\u0004אולם עוד \u0003לא\u0004 קרה בצורה כזו ש\u0003אברו מזוני\u0004 \u0005[יבראו\u0006 לאדם \u0005מזונות]\u0006 בתוך ביתו.","ואגב המסופר באנשים יוצאים מגדר הרגיל \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003מעשה באדם אחד שנשא אשה גידמת ולא הכיר בה\u0004 שהיא גדמת \u0003עד יום מותה. אמר רב: בוא וראה כמה צנועה\u0004 היתה \u0003אשה זו שלא הכיר בה בעלה. אמר לו ר' חייא: זו דרכה בכך,\u0004 שדרכה בכלל כאשה להתכסות, ובפרט אשה גדמת שבדרך כלל דואגת להסתיר את מומה. \u0003אלא\u0004 כך אמור: \u0003כמה צנוע אדם זה שלא הכיר באשתו.\u0004","שנינו במשנה שהאילים ה\u0003זכרים יוצאין\u0004 כשהם \u0003לבובין.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לבובין\"? אמר רב הונא: תותרי\u0004 \u0005[צמודים\u0006 זה לזה\u0005].\u0006 ומסבירים: \u0003מאי משמע דהאי\u0004 \u0005[מה המשמעות,\u0006 מהיכן אתה למד \u0005ש\u0006לשון \u0005זו]\u0006 \u0003\"לבובין\" לישנא דקרובי\u0004 \u0005[לשון של קירבה]\u0006 \u0003הוא,\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לבבתני אחתי כלה\"\u0004 (שיר השירים ד, ט), ומפרשים זאת: קרבתיני.","\u0003עולא אמר:\u0004 לבובים משמעו \u0003עור שקושרין להם\u0004 לזכרים \u0003כנגד לבם\u0004 (ומכאן \"לבובים\" — מכוסי לב) \u0003כדי שלא יפלו עליהם זאבים.\u0004 ותוהים: האם ה\u0003זאבים\u0004 רק על ה\u0003זכרים נפלי\u0004 \u0005[\u0006הם \u0005מתנפלים],\u0006 ואולם על \u0003נקבות\u0004 הם \u0003לא נפלי\u0004 \u0005[מתנפלים]?\u0006 ומדוע עושים הגנה זו רק לזכרים? ומשיבים: \u0003משום דמסגו בריש עדרא\u0004 \u0005[ש\u0006הזכרים \u0005מהלכים בראש העדר].\u0006 ושואלים: \u0003ו\u0004כי \u0003זאבין בריש עדרא נפלי\u0004 \u0005[בראש העדר\u0006 הם \u0005מתנפלים]\u0006 ו\u0003בסוף עדרא\u0004 \u0005[העדר]\u0006 הם \u0003לא נפלי\u0004 \u0005[מתנפלים]?\u0006 \u0003אלא\u0004 יש לומר: \u0003משום דשמני\u0004 \u0005[משום ש\u0006הזכרים \u0005שמנים]\u0006 ולכן הזאבים מתנפלים דווקא עליהם. ומקשים: \u0003ו\u0004כי \u0003בנקבות ליכא שמני\u0004 \u0005[אין שמנות]?\u0006 \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003מי ידעי\u0004 \u0005[האם יודעים,\u0006 מכירים\u0005]\u0006 הזאבים \u0003בין הני להני\u0004 \u0005[אלה לאלה,\u0006 בין שמן לרזה\u0005]?\u0006 \u0003אלא משום דזקפי חוטמייהו ומסגי כי דוו\u0004 \u0005[ש\u0006הזכרים \u0005זוקפים\u0006 את \u0005חוטמם והולכים ומסתכלים\u0006 סביב \u0005]\u0006 וחושבים הזאבים שפניהם למלחמה ואז מתנפלים הם עליהם.","\u0003רב נחמן בר יצחק אמר:\u0004 הכוונה בלבובים הוא \u0003עור שקושרין להן\u0004 לזכרים \u0003תחת\u0004 אבר \u0003זכרותן כדי שלא יעלו על הנקבות. וממאי\u0004 \u0005[וממה\u0006 מסיק הוא שבכך מדובר\u0005]?\u0006 — \u0003מדקתני סיפא\u0004 \u0005[ממה ששנינו בסוף\u0006 המשנה\u0005]:\u0006 \u0003והרחלים יוצאות שחוזות. מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שחוזות\"\u0004 — כמו \"שאחוזות\", \u0003שאוחזין\u0004 וקושרים \u0003האליה שלהן למעלה כדי שיעלו עליהן זכרים\u0004 בנקל. ומתקבל על הדעת ש\u0003רישא\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 מדובר על דבר שעושים כדי \u0003שלא יעלו על\u0004 הזכרים \u0003הנקבות, וסיפא\u0004 \u0005[ובסוף]\u0006 מדובר בנושא דומה \u0003כדי שיעלו עליהן זכרים.\u0004","ושואלים: \u0003מאי משמע דהאי\u0004 \u0005[מה המשמעות,\u0006 מהיכן לומדים אנו \u0005שזה]\u0006 לשון \u0003\"שחוזות\" לישנא דגלויי\u0004 \u0005[לשון של]\u0006 \u0003הוא?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בתיאור האשה הרעה: \u0003\"והנה אשה לקראתו\u0004"],["\u0003שית זונה ונצרת לב\"\u0004 (משלי ז, י), ושחוזות דומה ל\"שית זונה\".","שנינו במשנה ש\u0003הרחלים יוצאות כבולות.\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כבולות\"?\u0004 — \u0003שמכבלין\u0004 (קושרין) \u0003אליה שלהן למטה כדי שלא יעלו עליהן הזכרים.\u0004 ומסבירים: \u0003מאי משמע דהאי\u0004 \u0005[מה המשמעות,\u0006 מהיכן אתה למד \u0005שזה]\u0006 לשון \u0003\"כבול\" לישנא דלא עביד פירי הוא\u0004 \u0005[\u0006מ\u0005לשון\u0006 דבר \u0005שאיננו עושה פירות]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שכאשר נתן שלמה לחירם חבל ארץ התאונן חירם ואמר: \u0003\"מה הערים אשר נתת לי אחי ויקרא להם ארץ כבול עד היום הזה\"\u0004 (מהזהם א', ט, יג).","\u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"ארץ כבול\"? אמר רב הונא: שהיו בה בני אדם שמכובלין\u0004 (קשורים ומוקפים) \u0003בכסף ובזהב. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי, היינו דכתיב\u0004 \u0005[אם כך,\u0006 האם \u0005זהו\u0006 מה \u0005שנאמר]\u0006 \u0003\"\u0004ויצא חירם לראות את הערים אשר נתן לו שלמה \u0003כי לא ישרו בעיניו\"?\u0004 וכי \u0003מפני שמכובלין בכסף ובזהב לא ישרו בעיניו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 אכן לא ישרו בעיניו ודווקא בשל עושרם הרב כי \u0003כיון דעתירי ומפנקי לא עבדי עבידתא\u0004 \u0005[ש\u0006הם \u0005עשירים ומפונקים אינם עושים עבודה],\u0006 וחירם רצה אנשים שיוכל לגייס לעבודת המלך.","\u0003רב נחמן בר יצחק אמר: ארץ חומטון\u0004 (חולות) \u0003היתה. ואמאי קרי\u0004 \u0005[ומדוע קורא]\u0006 \u0003לה \"כבול\"\u0004 — \u0003דמשתרגא\u0004 \u0005[שטובעת]\u0006 \u0003בה כרעא\u0004 \u0005[הרגל]\u0006 \u0003עד כבלא\u0004 \u0005[הקרסול].\u0006 \u0003ו\u0004כן \u0003אמרי אינשי\u0004 \u0005[וכך\u0006 אכן נוהגים \u0005אנשים לומר]\u0006 על אדמה רעה: \u0003ארעא מכבלא דלא עבד פירי\u0004 \u0005[ארץ כבולה,\u0006 קשורה, \u0005שאינה עושה פירות].\u0006","שנינו במשנה שהרחלים יוצאות \u0003כבונות.\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כבונות\"?\u0004 — \u0003שמכבנין אותו למילת,\u0004 שעוטפים את הכבש מיומו הראשון במעין בגד כדי שהצמר ישאר נקי מאד, וישמש לכלי צמר משובחים. וכפי ששנינו במשנה שה\u0003שאת\u0004 שהיא אחת מדרגות הצרעת, לבנה היא \u0003כצמר לבן.\u0004 ואמרו: \u0003מאי\u0004 \u0005מהו\u0006 וכיצד הוא \u0003צמר לבן\u0004 \u0005[מהו\u0006 וכיצד הוא אותו \u0005צמר לבו]\u0006 ו\u0003אמר רב ביבי בר אביי: כצמר נקי בן יומו שמכבנין אותו למילת.\u0004","שנינו במשנה שנחלקו חכמים אם מותר לעיזים לצאת צרורות, שלדעת חכמים \u0003העזים יוצאות צרורות,\u0004 ור' יוסי אוסר, ור' יהודה מחלק שאם היו צרורות להתייבש — מותר, ולהיחלב — אסור. \u0003איתמר\u0004 \u0005[נאמר]\u0006 מפי האמוראים, ש\u0003רב אמר: הלכה כר' יהודה, ושמואל אמר: הלכה כר' יוסי.\u0004","\u0003ואיכא דמתני להא שמעתא באפי נפשיה\u0004 \u0005[ויש שהיה שונה הלכה זו בפני עצמה]\u0006 \u0005כמחלוקת לגופה של הלכה ולא לגבי המשנה, ובלשון זו,\u0006 \u0003רב אמר: ליבש מותר ולא לחלב, ושמואל אמר: אחד זה ואחד זה אסור.\u0004","\u0003ואיכא דמתני לה אהא\u0004 \u0005[ויש\u0006 \u0005שהיה שונה\u0006 מחלוקת זו \u0005על\u0006 ברייתא \u0005זו],\u0006 ששנינו: \u0003עזים יוצאות צרורות ליבש אבל לא לחלב. משום\u0004 (בשם) \u0003ר' יהודה בן בתירא אמרו: כך הלכה\u0004 מעיקר הדין, \u0003אבל מי מפיס\u0004 (מטיל גורל). כלומר, מי יכול להבחין בדבר שאי אפשר להכירו בראייה בלבד, \u0003איזה ליבש ואיזה לחלב? ומתוך שאין מכירין,\u0004 אמרו חכמים: \u0003אחד זה ואחד זה אסור. אמר שמואל: ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: הלכה כר' יהודה בן בתירא.\u0004 ולענין הלכה למעשה לכל הלשונות דברי שמואל מכוונים לדבר אחד. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: הלכה כתנא קמא\u0004 \u0005[הראשון]\u0006 שמתיר בכל מקרה.","\u0003ובמה\u0004 הבהמה \u0003אינה יוצאה\u0004 בשבת לרשות הרבים? — \u0003לא יצא גמל במטולטלת\u0004 שהיא כעין מרדעת, וכן לא יצא \u0003לא עקוד ולא רגול\u0004 שהם סוגי קשירת הרגליים זו לזו כאשר יבואר בגמרא. \u0003וכן שאר כל הבהמות\u0004 אסור לקשור אותן כך.","וכן \u0003לא יקשור גמלים זה בזה וימשוך\u0004 אותם אחריו כשיירה, \u0003אבל מכניס חבלים\u0004 של כל גמל וגמל \u0003לתוך ידו וימשוך\u0004 את כולם. \u0003ובלבד שלא יכרוך\u0004 את החבלים הללו יחד.","\u0003תנא\u0004 \u0005[שנינו]\u0006 בתוספתא: \u0003לא יצא הגמל במטולטלת הקשורה לו בזנבו\u0004 בלבד, \u0003אבל יוצא הוא במטולטלת הקשורה\u0004 גם \u0003בזנבו ו\u0004גם \u0003בחוטרתו\u0004 (דבשתו), כיון שיש לשער שבכגון זה לא תיפול המטולטלת. \u0003אמר רבה בר רב הונא: יוצא\u0004 נקבת \u0003הגמל במטולטלת הקשורה לה בשילייתה,\u0004 כי מטולטלת זו הקשורה במקום המכאיב לה, ודאי לא תנתקה.","שנינו במשנה שלא יצא הגמל \u0003לא\u0004 כשהוא \u0003עקוד ולא\u0004 כשהוא \u0003רגול. אמר רב יהודה: \"עקוד\"\u0004 משמעו — \u0003עקידת יד ורגל\u0004 שקושרים יד אחת ורגל אחת, \u0003כ\u0004עין עקידת \u0003יצחק בן אברהם\u0004 שנאמר בו לשון \"עקידה\". \u0003\"רגול\"\u0004 — \u0003שלא יכוף ידו\u0004 של הגמל \u0003על גבי זרועו ויקשור,\u0004 שכך עושים כדי שילך הגמל על שלוש רגליים בלבד ולא יוכל לברוח.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא בהגדרת \"עקוד\" ו\"רגול\": \u0003\"עקוד\"\u0004 משמעו — קשירת \u0003שתי ידים ושתי רגלים. \"רגול\"\u0004 — \u0003שלא יכוף ידו על גבי זרועו ויקשור\u0004. והרי זה שלא כדברי רב יהודה בענין עקידה! ומשיבים: \u0003הוא\u0004 ש\u0003אמר כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה]\u0006 שהובא בברייתא, \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"עקוד\"\u0004 — \u0003עקידת יד ורגל או שתי ידים ושתי רגלים, \"רגול\"\u0004 — \u0003שלא יכוף ידו\u0004 של הגמל \u0003על גבי זרועו ויקשור.\u0004","ועוד מקשים: \u0003ואכתי לא דמי\u0004 \u0005[ועדיין אינו דומה]\u0006 שכן \u0003בשלמא רישא וסיפא\u0004 \u0005[נניח לראש וסוף\u0006 הברייתא\u0005]\u0006 — \u0003ניחא\u0004 \u0005[נוח,\u0006 מובן\u0005],\u0006 ואולם \u0003מציעתא קשיא\u0004 \u0005[האמצע קשה],\u0006 שהרי בברייתא נאמר כי \"עקוד\" הינו גם עקידת ידיים ורגליים, ולא כדברי רב יהודה!","\u0003אלא\u0004 יש לומר כי \u0003הוא,\u0004 רב יהודה ש\u0003אמר כי האי תנא\u0004 \u0005[כמו תנא זה,\u0006 תנא אחר\u0005]\u0006 שדבריו מפורשים בברייתא אחרת, שלדבריו \u0003\"עקוד\"\u0004 משמעו — \u0003עקידת יד ורגל, כ\u0004עקידת \u0003יצחק בן אברהם. \"רגול\"\u0004 — \u0003שלא יכוף ידו על גבי זרועו ויקשור.\u0004","שנינו במשנה ש\u0003לא יקשור גמלים\u0004 זה בזה ויצא. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רב אשי: משום דמיחזי כמאן דאזיל לחינגא\u0004 \u0005[שנראה כמי שהולך לשוק]\u0006 למכור סחורות או להוביל שיירה של גמלים, ואינו לכבוד השבת.","עוד שנינו במשנה שאסור לכרוך את החבלים השונים הקשורים בגמלים על גבי היד, \u0003אבל מכניס\u0004 את החבלים של כל הגמלים בידו ומושך. \u0003אמר רב אשי: לא שנו\u0004 איסור זה משום דיני שבת, \u0003אלא לענין\u0004 איסור \u0003כלאים.\u0004 ושואלים: \u0003כלאים דמאי\u0004 \u0005[של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהבעייה היא כאן ב\u0003כלאים\u0004 של \u0003אדם,\u0004 שיהא אסור לאדם ובהמה להיות קשורים זה בזה, כדרך שאסור בכלאיים לחרוש בשור וחמור, \u0003ו\u0004אולם דבר זה לא יתכן, שכן \u0003התנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אדם מותר עם\u0004 כל בעלי החיים \u0003כולם לחרוש ולמשוך,\u0004 שאיסור כלאיים לענין זה הוא בבהמות בלבד!","\u0003אלא\u0004 תאמר שהאיסור הוא משום \u0003כלאים\u0004 שב\u0003חבלים,\u0004 שאם היה חבל אחד עשוי צמר וחבל אחד של פשתן אסור לכרוך אותם יחד משום כלאי בגדים (שעטנז). ואולם גם דבר זה קשה, שכן \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003התוכף תכיפה אחת,\u0004 כלומר, שמכניס את המחט פעם אחת בלבד בבד או כורך דברים פעם אחת בלא קשר כפול — אותה תכיפה \u0003אינה\u0004 משמשת \u0003חיבור\u0004 לכל דבר, ומה חשש יש אם יכרוך את החבלים על ידו?","ומשיבים: \u0003לעולם\u0004 המדובר ב\u0003כלאים\u0004 שב\u0003חבלים, והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003ובלבד שלא יכרוך ויקשור,\u0004 שאז נוצר קשר כפול שהוא חיבור גמור לדיני שעטנז.","הגבלה נוספת לגבי משיכת הגמלים בחבלים בשבת \u0003אמר שמואל: ובלבד שלא יצא חבל מתחת ידו טפח,\u0004 שלא ייראה כנושא חבל בידו בשבת. ומקשים: \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל\u0004 שלא יצא החבל \u0003טפחיים!\u0004","\u0003אמר אביי: השתא\u0004 \u0005[עכשיו]\u0006 ששמענו ש\u0003אמר שמואל טפח, ותנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל טפחיים,\u0004 הרי \u0003שמואל הלכה למעשה אתא לאשמעינן\u0004 \u0005[בא להשמיענו]\u0006 שאף על פי שהתירו התנאים בברייתא טפחיים, ואולם הלכה למעשה יש להחמיר עד טפח."],["\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ובלבד שיגביה מן הקרקע טפח\u0004 ואין הגבלה לגבי אורך החבל היוצא מן היד! ומשיבים: \u0003כי תניא\u0004 \u0005[כאשר נשנתה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 הרי זה \u0003בחבלא דביני ביני\u0004 \u0005[בחבל שבינתיים],\u0006 שהחבל בין הגמל לבין המחזיק בו לא ייגרר על גבי הקרקע, אלא יהיה מוגבה למעלה, שיראו הכל שהחבל קשור בגמל.","במשנה זו רשימה נוספת של דברים שאסור להניח לבהמה לצאת בהם בשבת. \u0003אין חמור יוצא במרדעת בזמן שאינה קשורה לו\u0004 מבעוד יום, \u0003ולא בזוג\u0004 (פעמון) \u0003אף על פי שהוא פקוק\u0004 במוך כדי למנוע מהענבל לקשקש בתוכו ולהשמיע קול, \u0003ולא בסולם\u0004 (שמהותו תבואר בגמרא) \u0003שבצוארו\u0004, \u0003ולא ברצועה שברגלו.\u0004","\u0003ו\u0004כן \u0003אין התרנגולים יוצאין בחוטין ולא ברצועה שברגליהם\u0004 ששמים להם לסימן, \u0003ואין\u0004 האילים \u0003הזכרים יוצאין בעגלה שתחת האליה שלהן,\u0004 שהיו נוהגים לעשות מתחת לאליותיהם של כבשים מגודלים כעין עגלה קטנה, כדי שלא תגרר האליה על גבי הקרקע ותיפצע.","\u0003ואין הרחלים יוצאות חנונות, ואין העגל יוצא בגימון, ולא פרה בעור הקופר\u0004 (קיפוד), \u0003ולא ברצועה שבין קרניה.\u0004 ומסופר כי \u0003פרתו של ר' אלעזר בן עזריה היתה יוצאה\u0004 בשבת \u0003ברצועה שבין קרניה\u0004 והיה זה \u0003שלא ברצון חכמים.\u0004","שנינו במשנה שאין החמור יוצא במרדעת בשבת. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסור לשים אותה על גב החמור — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו],\u0006 שיש לחשוש שמא תיפול המרדעת, ויבוא בעל החמור לטלטלה ברשות הרבים.","עוד שנינו במשנה ש\u0003לא\u0004 יוצא החמור \u0003בזוג אף על פי שהוא פקוק.\u0004 וטעם הדבר — \u0003משום דמיחזי כמאן דאזיל לחינגא\u0004 \u0005[שנראה כמי שהולך לשוק]\u0006 ומקשט את חמורו בפעמונים לכבוד יום השוק.","שנינו במשנה ש\u0003לא\u0004 יוצא החמור בשבת \u0003בסולם שבצוארו. אמר רב הונא:\u0004 סולם זה הוא \u0003בי לועא\u0004 \u0005[\u0006מכשיר ששמים \u0005על הלחי].\u0006 ו\u0003למאי עבדי ליה\u0004 \u0005[ל\u0006שם \u0005מה עושים אותו]?\u0006 מה צורך באותו מכשיר? — \u0003להיכא דאית ליה\u0004 \u0005[למקום שיש לו,\u0006 לחמור\u0005]\u0006 \u0003מכה,\u0004 ש\u0003לא הדר חייך ביה\u0004 \u0005[יחזור\u0006 החמור \u0005ו\u0006\u0005יחכך\u0006 אותו\u0005]\u0006 ויחמיר בכך את הפציעה.","עוד שנינו במשנה ש\u0003לא\u0004 יוצא החמור בשבת \u0003ברצועה שברגלו.\u0004 ומסבירים: רצועה זו למה היא נדרשת — \u0003דעבדו ליה לגיזרא\u0004 \u0005[שעושים לו ל\u0006צורך \u0005פסיעותיו],\u0006 שאם רגליו עקומות מעט ופוגעות זו בזו, קושרים לו רצועה במקום המועד לפגיעה, שלא יפצע.","עוד שנינו ש\u0003אין התרנגולין יוצאין בחוטין.\u0004 ומה סיבת קשירתם לתרנגול — \u0003דעבדי ליה סימנא כי היכי\u0004 \u0005[שעושים לו\u0006 בכך \u0005סימן כדי]\u0006 ש\u0003לא ליחלפו\u0004 \u0005[יתחלפו]\u0006 באחרים.","עוד שנינו שהתרנגולים \u0003לא\u0004 יוצאים בשבת \u0003ברצועה\u0004 שברגליהם. וסיבת קשירת אותה רצועה — \u0003דעבדי ליה כי היכי\u0004 \u0005[שעושים לו כדי]\u0006 ש\u0003לא ליתברו מאני\u0004 \u0005[ישברו כלים],\u0006 שעל ידי קשירת הרגליים זו בזו ממעטים הם בקפיצה. שנינו ש\u0003אין\u0004 האילים \u0003הזכרים יוצאים בעגלה\u0004 שתחת האליה שלהם. ומסבירים כי מטרת אותה עגלה \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לחמטן אלייתיה\u0004 \u0005[יפצעו אליותיהם].\u0006","שנינו במשנה ש\u0003אין הרחלים יוצאות חנונות.\u0004 מסופר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אחא בר עולא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא ויתיב וקאמר\u0004 \u0005[וישב ואמר]\u0006 שלדעתו \"חנונות\" פירושו: ש\u0003משעה שגוזזין אותה טומנין לה עזק\u0004 (צמר או דברים רכים אחרים) \u0003בשמן ומניחין לה\u0004 לכבשה על גבי \u0003פדחתה\u0004 (מצחה) \u0003כדי שלא תצטנן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: אם כן\u0004 דעתך שזהו הטיפול הראוי בכל כבשה גזוזה, אם כן \u0003עשיתה\u0004 והחשבת כל כבשה כראש הגולה \u0003מר עוקבא,\u0004 שלכאורה רק הוא ראוי לטיפול כל כך טוב, וכי יבואו לטפל כך בכל כבשה גזוזה?","\u0003אלא יתיב\u0004 \u0005[ישב]\u0006 \u0003רב פפא בר שמואל קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא ויתיב וקאמר\u0004 \u0005[וישב ואמר]\u0006 שלדעתו \"חנונות\" פירושו: ש\u0003בשעה שכורעת\u0004 הכבשה \u0003לילד טומנין לה שני עזקין\u0004 (צרורות צמר רכים) \u0003של שמן, ומניחין לה אחד על פדחתה ואחד על הרחם כדי שתתחמם. אמר לו רב נחמן: אם כן\u0004 דעתך שזהו הטיפול הראוי בכל כבשה גזוזה, אם כן \u0003עשיתה\u0004 והחשבת כל כבשה כ\u0003ילתא\u0004 אשת רב נחמן שאף היא היתה מבית ראש הגולה, ובודאי אין מטפלים כך בכבשה.","\u0003אלא אמר רב הונא: עץ אחד יש בכרכי הים ו\"חנון\" שמו, ומביאין קיסם\u0004 ממנו \u0003ומניחין לה בחוטמה כדי שתתעטש\u0004 הכבשה \u0003ויפלו דרני\u0004 \u0005[\u0006ה\u0005קרציות]\u0006 שב\u0003ראשה.\u0004 על כך שואלים: אם זהו פירוש \"חנונות\", \u0003אי הכי\u0004 \u0005[אם כן]\u0006 \u0003זכרים נמי\u0004 \u0005[גם כן]\u0006 יעשו להם טיפול זה! ומשיבים: \u0003כיון דמנגחי\u0004 \u0005[שמנגחים]\u0006 ה\u0003זכרים בהדדי\u0004 \u0005[זה את זה]\u0006 \u0003ממילא נפלן\u0004 \u0005[נופלות]\u0006 הקרציות. \u0003שמעון נזירא אמר:\u0004 \"חנונות\" פירושו ששמים להם \u0003קיסמא דריתמא\u0004 \u0005[קיסם של רותם]\u0006 בחוטמן לצורך זה.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 להסבר של \u0003רב הונא\u0004 שמשתמשים בעץ ה\"חנון\", \u0003היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 בלשון \u0003\"חנונות\"\u0004 על שם אותו עץ, \u0003אלא לרבנן מאי\u0004 \u0005[ל\u0006פי הסבריהם של שאר ה\u0005חכמים מהו]\u0006 לשון \u0003\"חנונות\"?\u0004 ומסבירים: \u0003דעבדינן להו מילתא דמרחמינן עלייהו\u0004 \u0005[שאנו עושים להן דבר שמרחמים עליהן]\u0006 ו\"חנונות\" הריהו לשון \"חנינה\".","שנינו במשנה ש\u0003אין העגל יוצא בגימון.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 גימון זה שאמרנו שאין ה\u0003עגל\u0004 יוצא \u0003בגימון? אמר רב הונא:\u0004 גימון זה הוא \u0003בר נירא\u0004 \u0005[בן עול,\u0006 עול קטן\u0005]\u0006 ששמים על העגל כדי להרגילו מצעירותו לשאת בעול. \u0003אמר ר' אלעזר: מאי משמע דהאי\u0004 \u0005[מה\u0006 \u0003המשמעות,\u0004 מהיכן אתה למד\u0005]\u0006 ש\u0003\"גימון\" לישנא דמיכף\u0004 \u0005[לשון כפיפה]\u0006 הוא — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הלכף כאגמון ראשו\"\u0004 (ישעיהו נח, ה), ולדעתו \"גימון\" ו\"אגמון\" שורש אחד להם.","עוד שנינו במשנה ש\u0003לא\u0004 יוצאת ה\u0003פרה בעור הקופר\u0004 ששמים לה בעטיניה בשבת. ומסבירים: \u0003דעבדי\u0004 \u0005[שעושים]\u0006 \u0003לה כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא למציוה יאלי\u0004 \u0005[ינקו ממנה שרצים].\u0006","עוד שנינו ש\u0003לא\u0004 יוצאת הפרה \u0003ברצועה שבין קרניה.\u0004 ומעירים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר\u0004 כפי שכבר שנינו שאף שמירה יתירה של בעל חיים יש בה משום משא, הרי \u0003בין\u0004 כאשר רצועה זו נקשרה בקרני הפרה \u0003לנוי\u0004 ו\u0003בין\u0004 כאשר נקרשה לקרניו כדי \u0003לשמר\u0004 — \u0003אסור.\u0004 ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר\u0004 ששמירה יתירה של בעל חיים אין בה משום משא, הרי אם כן \u0003לנוי\u0004 — \u0003אסור,\u0004 ו\u0003לשמר\u0004 — \u0003מותר.\u0004","מסופר ש\u0003פרתו של ר' אלעזר בן עזריה\u0004 היתה יוצאת בשבת שלא ברצון חכמים ברצועה בין קרניה. ושואלים: \u0003וחדא פרה הויא ליה\u0004 \u0005[ו\u0006כי \u0005פרה אחת היתה לו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב יהודה\u0004 שכך \u0003אמר רב: תריסר אלפי עגלי הוה\u0004 \u0005[שנים עשר\u0006 \u0003אלף עגלים היה] מעשר ר' אלעזר בן עזריה מעדריה\u0004 \u0005[מעדרו]\u0006 ב\u0003כל שתא ושתא\u0004 \u0005[שנה ושנה].\u0006 וכיון שאין מפרישים למעשר אלא מן העגלים הנולדים באותה שנה, בהכרח שהיה לו עדר עצום, ובודאי אי אפשר לדבר על \"פרתו של ר' אלעזר בן עזריה\".","ואכן, \u0003תנא\u0004 \u0005[שנינו]\u0006 בתוספתא שנו: \u0003לא שלו היתה\u0004 הפרה \u0003אלא של שכינתו היתה, ומתוך שלא מיחה בה\u0004 לומר לה שאסור הדבר כדעת חכמים \u0003נקראת על שמו\u0004 לגנאי, כאילו היתה זו פרה שלו.","מסופר: \u0003רב ור' חנינא ור' יוחנן ורב חביבא מתנו\u0004 \u0005[שונים].\u0006 ומעירים מיד: \u0003בכוליה\u0004 \u0005[בכל]\u0006 \u0003סדר מועד כל כי האי זוגא חלופי\u0004 \u0005[בכל סדר מועד כל כמו\u0006 זוג \u0005זה, מחליפים]\u0006 בגרסה אחת את \u0003ר' יוחנן ומעייל\u0004 \u0005[ומכניסים]\u0006 במקומו את \u0003ר' יונתן.\u0004 על כל פנים ארבעה חכמים אלה אמרו: \u0003כל מי שאפשר\u0004 לו \u0003למחות לאנשי ביתו\u0004 על מעשה שאינו ראוי שהם עושים \u0003ולא מיחה\u0004 — הרי הוא עצמו \u0003נתפס על\u0004 עוונם של \u0003אנשי ביתו.\u0004 ואם יכול למחות \u0003באנשי עירו\u0004 ולא מחה — הריהו \u0003נתפס על\u0004 עוון \u0003אנשי עירו.\u0004 ואם יכול למחות \u0003בכל העולם כולו\u0004 — הריהו \u0003נתפס על\u0004 עוון \u0003כל העולם כולו.\u0004","\u0003אמר רב פפא: והני דבי ריש גלותא נתפסו על כולי עלמא\u0004 \u0005[ואותם\u0006 אנשי \u0005בית ראש הגולה נתפסים על\u0006 עוונות \u0005כל העולם],\u0006 לפי שכח שררתם מוטל היה כמעט על כל העולם היהודי, ובידם היה לדאוג שלא יבואו לעבור עבירה. וזהו \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר ר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ה' במשפט יבא עם זקני עמו ושריו\u0004 ואתם בערתם הכרם גזילת העני בבתיכם\u0003\"\u0004 (ישעיה ג, יד). ולכאורה \u0003אם שרים חטאו\u0004 בגזל,"],["\u0003זקנים\u0004 שהם חכמי הדור \u0003מה חטאו? אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003על זקנים,\u0004 חברי הסנהדרין, יבוא ה' במשפט משום \u0003שלא מיחו בשרים.\u0004","ומסופר: \u0003רב יהודה הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003שמואל. אתאי ההיא איתתא קא צווחה קמיה\u0004 \u0005[באה אשה אחת\u0006 ו\u0005צוחה לפניו,\u0006 לפני שמואל\u0005],\u0006 על עוול שנעשה \u0003לה, ולא הוה משגח\u0004 \u0005[היה משגיח]\u0006 \u0003בה. אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה לשמואל: וכי \u0003לא סבר ליה מר\u0004 \u0005[אין אדוני סבור]\u0006 כדברי הכתוב: \u0003\"אטם אזנו מזעקת דל גם הוא יקרא ולא יענה\"\u0004 (משלי כא, יג) \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שיננא, רישך בקרירי, רישא דרישיך בחמימי\u0004 \u0005[גדול השיניים. ראשך,\u0006 כלומר, רבך, נמצא בעניין זה \u0005בצוננים, ראש ראשך,\u0006 הממונה עליו, הוא שייכווה \u0005ברותחים].\u0006 \u0003הא יתיב\u0004 \u0005[הרי יושב]\u0006 \u0003מר עוקבא\u0004 שהוא \u0003אב בית דין,\u0004 וכאב בית דין חובתו היא לדאוג לדברים.","ומנין שחובה זו אכן מוטלת על בית ראש הגולה? — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"בית דוד כה אמר ה' דינו לבקר משפט והצילו גזול מיד עושק פן תצא כאש חמתי ובערה ואין מכבה מפני רע מעלליכם\"\u0004 (ירמיהו כא, יב).","בנושא זה של תוכחה מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' סימון: לוכחינהו מר להני דבי ריש גלותא\u0004 \u0005[יוכיח אדוני אותם, את\u0006 בני \u0005בית ראש הגולה]\u0006 שהיתה לר' סימון השפעה עליהם. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא מקבלי מינאי\u0004 \u0005[אין\u0006 הם \u0005מקבלים ממני]\u0006 דברי תוכחה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף על גב דלא מקבלי לוכחינהו מר\u0004 \u0005[אף על פי שאינם מקבלים יוכיחם אדוני].\u0006","שכן \u0003אמר ר' אחא בר' חנינא: מעולם לא יצתה\u0004 (יצאה) \u0003מדה טובה\u0004 (הבטחה טובה) \u0003מפי הקדוש ברוך הוא וחזר בה לרעה חוץ מדבר זה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ה' אליו עבר בתוך העיר בתוך ירושלם והתוית תו על מצחות האנשים הנאנחים והנאנקים על כל התועבות הנעשות בתוכה.\u0004 זקן בחור ובתולה וטף ונשים תהרגו למשחית ועל כל איש אשר עליו התו אל תיגשו\u0003\"\u0004 (יחזקאל ט, ד. יחזקאל ט, ו).","שכך \u0003אמר לו הקדוש ברוך הוא לגבריאל\u0004 המלאך: \u0003לך ורשום על מצחן של צדיקים תיו של דיו\u0004 כדי \u0003ש\u0004יהיה זה להם סימן ו\u0003לא ישלטו בהם מלאכי חבלה. ועל מצחם של\u0004 ה\u0003רשעים\u0004 רשום \u0003תיו של דם כדי ש\u0004יהיה זה להם סימן ו\u0003ישלטו בהן מלאכי חבלה.\u0004","\u0003אמרה מדת הדין לפני הקדוש ברוך הוא: רבונו של עולם! מה נשתנו אלו מאלו? אמר לה: הללו צדיקים גמורים והללו רשעים גמורים. אמרה לפניו: רבונו של עולם!\u0004 והרי \u0003היה בידם\u0004 של צדיקים אלה \u0003למחות\u0004 ברשעים \u0003ולא מיחו!\u0004","\u0003אמר לה: גלוי וידוע לפני ש\u0004גם \u0003אם מיחו בהם לא\u0004 היו \u0003מקבלים מהם\u0004 אותה תוכחה ולא היו נמנעים ממעשיהם הרעים. \u0003אמר\u0004 מידת הדין \u0003לפניו: רבונו של עולם! אם לפניך\u0004 אכן \u0003גלוי\u0004 שלא היתה תוכחתם מועילה, ואולם \u0003לפניהם,\u0004 לפי הצדיקים \u0003מי\u0004 \u0005[האם]\u0006 \u0003גלוי?\u0004 וחזר בו הקדוש ברוך הוא מההבטחה להגנה על הצדיקים, והסכים שאף אלה שלא מיחו ייענשו.","\u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"זקן בחור ובתולה טף ונשים תהרגו למשחית ועל כל איש אשר עליו התו אל תגשו וממקדשי תחלו\"\u0004 (יחזקאל ט, ו). \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד באותו פסוק: \u0003\"ויחלו באנשים הזקנים אשר לפני הבית\"\u0004 (פסוק ו). ו\u0003תני רב יוסף: אל תקרי \"מקדשי\" אלא \"מקודשי\"\u0004 — \u0003אלו בני אדם שקיימו את התורה כולה מאלף ועד תיו. ומיד\u0004 לפניו סמוך לענין זה נאמר: \u0003\"והנה ששה אנשים באים מדרך שער העליון אשר מפנה צפונה ואיש כלי מפצו בידו ואיש אחד בתוכם לבש הבדים וקסת הספר במתניו ויבאו ויעמדו אצל מזבח הנחשת\"\u0004 (יחזקאל ט, ב).","ומתחילה תוהים: \u0003מזבח הנחשת מי הוה\u0004 \u0005[האם היה]\u0006 בזמנו של יחזקאל בבית המקדש? והלוא כבר מימי שלמה לא היה אלא מזבח אבנים! אלא יש להבין על דרך המליצה: \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003הקדוש ברוך הוא: התחילו ממקום שאומרים שירה לפני,\u0004 שהוא בית המקדש שמשתמשים שם בכלי שיר העשויים מנחושת. \u0003ומאן נינהו\u0004 \u0005[ומי הם]\u0006 אותם \u0003ששה אנשים\u0004 המתוארים כאן? \u0003אמר רב חסדא: קצף, אף, וחימה, ומשחית, ומשבר, ומכלה.\u0004","ועוד שואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה,\u0006 מיוחדת\u0005]\u0006 האות \u0003\"תיו\"\u0004 שעל מצחם של הצדיקים? \u0003אמר רב: \"תיו\"\u0004 היא ראש התיבה \u0003תחיה, \"תיו\"\u0004 היא ראש המלה \u0003\"תמות\". ושמואל אמר:\u0004 האות \"תיו\" היא ראש התיבה \"תמה\", ובאה ללמד כי \u0003תמה זכות אבות. ור' יוחנן אמר:\u0004 האות \"תיו\" היא ראש התיבה \"תחון\", ובאה ללמד כי \u0003תחון זכות אבות.\u0004","\u0003וריש לקיש אמר:\u0004 האות \u0003\"תיו\"\u0004 היא \u0003סוף חותמו של הקדוש ברוך הוא,\u0004 שכן \u0003אמר ר' חנינא: חותמו של הקדוש ברוך הוא \"אמת\".\u0004 והאות האחרונה בחותמו זה הרי היא האות ת'. \u0003אמר ר' שמואל בר נחמני:\u0004 האות ת' באה לרמז ש\u0003אלו בני אדם שקיימו את התורה כולה מאלף ועד תיו.\u0004","לגופם של הדברים שהוזכרו מקודם שתמה זכות אבות שואלים: ו\u0003מאימתי\u0004 באמת \u0003תמה זכות אבות? אמר רב: מימות\u0004 הנביא \u0003הושע בן בארי, שנאמר: \"\u0004ועתה \u0003אגלה את נבלתה לעיני מאהביה ואיש לא יצילנה מידי\"\u0004 (הושע ב, יב). שאף האבות כבר אין בזכותם כח כדי להגן על ישראל.","\u0003ושמואל אמר:\u0004 זכות אבות תמה \u0003מימי חזאל, שנאמר: \"וחזאל מלך ארם לחץ את ישראל כל ימי יהואחז\"\u0004 (מלכים ב' יג, כב). \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם בהמשך: \u0003\"ויחן ה' אותם וירחמם ויפן אליהם למען בריתו את אברהם יצחק ויעקב ולא אבה השחיתם ולא השליכם מעל פניו עד עתה\"\u0004 (מלכים ב' יג, פסוק כג), שתאריך זה היה האחרון שבו עדיין נזכרת זכות אבות.","ואילו \u0003ר' יהושע בן לוי אמר:\u0004 זכות האבות תמה כבר \u0003מימי אליהו, שנאמר: \"ויהי בעלות המנחה ויגש אליהו הנביא ויאמר ה' אלהי אברהם יצחק וישראל היום יודע כי אתה אלהים בישראל ואני עבדך ובדברך עשיתי את כל הדברים האלה\"\u0004 (מלכים א, יח, לו), והוא מדייק: \"היום יוודע\" — ולא מאוחר יותר, כי היום תמה זכות האבות.","\u0003ור' יוחנן אמר:\u0004 תמה זכות האבות \u0003מימי חזקיהו, שנאמר: \"למרבה המשרה ולשלום אין קץ על כסא דוד ועל ממלכתו להכין אותה ולסעדה במשפט ובצדקה מעתה ועד עולם קנאת ה' צבאות תעשה זאת\"\u0004 (ישעיהו ט, ו), כלומר, מעתה לא זכות האבות מגינה על ישראל כי אם רק קנאת ה'.","כיון שנידונו כאן דברים השייכים לבעיית העונש בכלל, והקשר בין המעשה לבין העונשים הבאים על האדם, מוסיפים לדון בענין זה. \u0003אמר רב אמי: אין מיתה\u0004 באה על האדם \u0003בלא חטא,\u0004 שאילו לא היה האדם חוטא לא היה מת. \u0003ואין יסורין\u0004 באים לאדם \u0003בלא עון.\u0004","וראיות לדבר: \u0003אין מיתה בלא חטא\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"הנפש החטאת היא תמות בן לא ישא בעון האב ואב לא ישא בעון הבן. צדקת הצדיק עליו תהיה ורשעת הרשע עליו תהיה\"\u0004 (יחזקאל יח, כ), לאמור, רק חטאו של אדם גורם לו מיתה, ואין לדבר על חטא קדמון. ו\u0003אין יסורין בלא עון\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ופקדתי בשבט פשעם ובנגעים עונם\"\u0004 (תהלים פט, לג)."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם! מפני מה קנסת מיתה על אדם הראשון? אמר להם: מצוה קלה צויתיו ועבר עליה. אמרו לו: והלא משה ואהרן שקיימו\u0004 את \u0003כל התורה כולה, ומתו! אמר להם\u0004 הקדוש ברוך הוא כלשון הכתוב: \"הכל כאשר לכל \u0003מקרה אחד לצדיק ולרשע לטוב\u0004 ולטהור ולטמא ולזובח ולאשר איננו זובח כטוב כחוטא הנשבע כאשר שבועה ירא\" (קהלת ט, ב), והרי שהמוות אינו קשור במעשיו של אדם, אלא נגזר על הכל בשווה!","ומשיבים: רב אמי \u0003הוא\u0004 ש\u0003אומר\u0004 דבריו אלה \u0003כי האי תנא\u0004 \u0005[כתנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: אף משה ואהרן בחטאם מתו, שנאמר:\u0004 \"ויאמר ה' אל משה ואל אהרן \u0003יען לא האמנתם בי\u0004 להקדישני לעיני בני ישראל לכן לא תביאו את הקהל הזה אל הארץ אשר נתתי להם\" (במדבר כ, יב). \u0003הא\u0004 \u0005[הרי]\u0006 אם כן \u0003האמנתם בי\u0004 — \u0003עדיין לא הגיע זמנכם ליפטר מן העולם,\u0004 הרי שאף מות משה ואהרן תלוי בחטאם.","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003ארבעה\u0004 אנשים \u0003מתו בעטיו\u0004 (בגללו) \u0003של נחש.\u0004 כלומר, לא משום חטאיהם, אלא מפני שנגזר מאז מעשה הנחש על בני אדם שימותו, והם עצמם נקיים היו מכל חטא. \u0003ואלו הם: בנימין בן יעקב, ועמרם אבי משה, וישי אבי דוד, וכלאב בן דוד. וכולהו גמרא, לבר\u0004 \u0005[וכולם\u0006 למדנו \u0005ממסורת],\u0006 \u0003מישי אבי דוד דמפרש ביה קרא\u0004 \u0005[שמפורש בו הכתוב]\u0006 בדרך הדרש, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת עמשא שם אבשלום תחת יואב שר הצבא ועמשא בן איש ושמו יתרא הישראלי אשר בא אל אביגיל בת נחש אחות צרויה אם יואב\"\u0004 (שמואל ב' יז, כה).","ושואלים: \u0003וכי\u0004 אביגיל \u0003בת נחש הואי\u0004 \u0005[היתה]?\u0006 \u0003והלא בת ישי הואי, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"ואישי הוליד את בכורו את אליאב ואבינדב השני ושמעא השלישי. נתנאל הרביעי רדי החמישי. אוצם השישי דוד השביעי. \u0003ואחיתיהם צרויה ואביגיל\u0004 ובני צרויה אבשי ויואב ועשה־אל שלושה. ואביגיל ילדה את עמשא ואבי עמשא יתר הישמעאלי\" (דברי הימים א' ב, יג–יז), ואם כן היתה אביגיל בת ישי. \u0003אלא\u0004 נקרא נחש כדי לומר \u0003שמת בעטיו של נחש.\u0004","ועכשיו באים לברר: \u0003מני\u0004 \u0005[של מי\u0006 היא] ברייתא זו המספרת על הארבעה שמתו בלא חטא ? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שזהו ה\u0003תנא\u0004 שמספר מה אמרו \u0003מלאכי השרת, והא איכא\u0004 \u0005[והרי יש]\u0006 לדעתו גם \u0003משה ואהרן\u0004 שאף הם מתו שלא בעוונם! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 ברייתא זו כ\u0003ר' שמעון בן אלעזר היא,\u0004 הסבור שמשה ואהרן אף הם חטאו. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 כי בעיקרו של דבר אף הוא מסכים ש\u0003יש מיתה בלא חטא ויש יסורין בלא עון. ו\u0004אם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא על \u0003רב אמי,\u0004 ואכן לפי זה נשאר הדבר \u0003בתיובתא\u0004 \u0005[קושיה חמורה]\u0006 ואין לה תשובה.","וכיון שהוזכרו בדרך אגב חטאי אבות האומה, באים לברר דברים אחדים בנושא זה. \u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: כל האומר\u0004 ש\u0003ראובן חטא\u0004 בבלהה \u0003אינו אלא טועה,\u0004 וכפי \u0003שנאמר: \"\u0004ויהי בשכון ישראל בארץ ההיא וילך ראובן וישכב את בלהה פילגש אביו וישמע ישראל \u0003ויהיו בני יעקב שנים עשר\"\u0004 (בראשית לה, כב), ואמרו חכמים כי מה שנאמר \"ויהיו בני יעקב שנים עשר\" \u0003מלמד שכולן שקולים כאחת\u0004 בצדקתם, ואם כן הרי שאף ראובן לא חטא. \u0003אלא מה אני מקיים\u0004 (כיצד אני מבין) את דברי הכתוב \u0003\"וישכב את בלהה פילגש אביו\"\u0004 — \u0003מלמד שבלבל\u0004 (הפך) \u0003מצעו של אביו,\u0004 שהתרעם על שהיה באוהלה של בלהה, \u0003ומעלה עליו הכתוב כאילו שכב עמה.\u0004","וכן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: מוצל אותו צדיק מאותו עון, ולא בא מעשה זה לידו,\u0004 שכן וכי \u0003אפשר\u0004 ש\u0003עתיד זרעו לעמוד על הר עיבל ולומר \"ארור שכב עם אשת אביו\u0004 כי גילה כנף אביו ואמר כל העם אמן\u0003\"\u0004 (דברים כז, כ), \u0003ויבא חטא זה לידו?\u0004 וכי אפשר לתאר שיקללו בני השבט את אביהם? \u0003אלא מה\u0004 (כיצד) \u0003אני מקיים\u0004 את דברי הכתוב \u0003\"וישכב את בלהה פילגש אביו\"\u0004 — יש להבין זאת ש\u0003עלבון אמו תבע. אמר: אם אחות אמי\u0004 רחל \u0003היתה צרה לאמי,\u0004 האם גם \u0003שפחת אחות אמי תהא צרה לאמי?\u0004 על כן \u0003עמד ובלבל את מצעה,\u0004 כדי שיהא יעקב באוהל לאה.","\u0003אחרים אומרים: שתי מצעות בלבל, אחת של שכינה ואחת של אביו, והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"\u0004פחז כמים אל תותר כי עלית משכבי אביך \u0003אז חללת יצועי עלה\"\u0004 (בראשית מט, ד), \u0003אל תקרי \"יצועי\" אלא \"יצועיי\"\u0004 כי \"משכבי אביך\" כוונתן הן למיטתו של אביו והן להשראת השכינה המצויה באוהלי הצדיקים.","ומעירים כי גופו של ענין הרי הוא \u0003כתנאי\u0004 \u0005[כ\u0006\u0005מחלוקת\u0006 \u0005תנאים]\u0006 שנחלקו בדבר זה במקום אחר. ששנינו שנחלקו חכמים בפירוש המלים \u0003\"פחז כמים אל תותר\",\u0004 ובמיוחד בפרוש בדרך ראשי תיבות את המלה \"פחז\". \u0003ר' אליעזר אומר\u0004 כי מלה זו היא ראשי התיבות של המילים \u0003\"פזתה\"\u0004 (מלשון פזיזות), \u0003\"חבתה\"\u0004 (התחייבת), \u0003\"זלתה\"\u0004 (עשית מעשה זלזול, קלון). \u0003ר' יהושע אומר,\u0004 ראשי תיבות אלה הם: \u0003\"פסעתה על דת\", \"חטאת\", \"זנית\". רבן גמליאל אומר\u0004 ש\"פחז\" מתייחס לתשובתו של ראובן: \u0003\"פיללתה\"\u0004 (התפללת להנצל מן החטא), \u0003\"חלתה\"\u0004 (רעדת מלחטוא), \u0003\"זרחה תפלתך\".\u0004","\u0003אמר רבן גמליאל: עדיין צריכין אנו\u0004 בהבנת מדרש זה \u0003למודעי.\u0004 ש\u0003ר' אלעזר המודעי אומר: הפוך את התיבה\u0004 (המלה) \u0003ודורשה: זעזעתה, הרתעתה\u0004 (שדורש ה' במקום ח' במלת \"פחז\" כמקובל), וכל כדי שלא תחטא ואכן \u0003\"פרחה חטא ממך\".\u0004 ואם כן הרי שרבן גמליאל ור' אלעזר המודעי סבורים שלא חטא ראובן. \u0003רבא אמר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 את השמועה הזאת משמו של \u0003ר' ירמיה בר אבא,\u0004 בראשי תיבות אחרים: \u0003\"זכרת עונשו של דבר\", \"חלית עצמך חולי גדול\"\u0004 כדי להימנע מן החטא, \u0003\"פירשת מלחטוא\".\u0004","המילים \u0003ראובן, בני עלי, בני שמואל, דוד, ושלמה, ויואש\u0004 הם \u0003סימן\u0004 לדיונים הבאים בשאלה אם אמנם חטאו גדולי הדור.","\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: כל האומר\u0004 ש\u0003בני עלי חטאו אינו אלא טועה, שנאמר: \"ושם שני בני עלי (עם ארון ברית האלהים) חפני ופנחס כהנים לה'\"\u0004(שמואל א' א, ג).","ומעירים כי ר' יונתן \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כרב,\u0004 ש\u0003אמר רב: פנחס לא חטא.\u0004 ומנין לו דבר זה? — הוא \u0003מקיש\u0004 (משוה) את \u0003חפני לפנחס: מה פנחס לא חטא\u0004 — \u0003אף חפני לא חטא. אלא מה אני מקיים\u0004 את דברי הכתוב \"ועלי זקן מאד ושמע את כל אשר יעשון בניו לכל ישראל ואת \u0003אשר ישכבן את הנשים\u0004 הצובאות פתח אוהל מועד\" (שמואל א' ב, כב) — יש להסביר זאת ש\u0003מתוך ששהו\u0004 בני עלי \u0003את\u0004 הקרבת \u0003קיניהן\u0004 של הנשים שילדו והביאום כחלק מסדר טהרתן, שכן יולדת עניה צריכה להביא לטהרתה שני תורים או בני יונה לקרבן, והם הנקראים \"קן\", ומאחר שלא הזדרזו בני עלי בהקרבה גרמו \u0003שלא הלכו\u0004 הנשים \u0003אצל בעליהן\u0004 ובשל כך \u0003מעלה עליהן הכתוב כאילו שכבום,\u0004 אבל חטאם היה רק ברשלנות ובחוסר תשומת לב.","\u0003גופא\u0004 \u0005[לגוף\u0006 הדבר\u0005]\u0006 הרי הזכרנו מקודם ש\u0003אמר רב\u0004 ש\u0003פנחס לא חטא.\u0004 וראייה לדבריו — ממה \u0003שנאמר: \"ואחיה בן אחיטוב אחי איכבוד בן פנחס בן עלי כהן ה'\u0004 בשילה נושא אפוד והעם לא ידע כי הלך יונתן\u0003\"\u0004 (שמואל א' יד, ג), ולכאורה האם \u0003אפשר\u0004 ש\u0003חטא בא לידו\u0004 של פנחס \u0003והכתוב מייחסו\u0004 ומונה את דורות הכהנים שאחריו?","\u0003והלא כבר נאמר\u0004 לגבי החוטאים בזנות \u0003\"יכרת ה' לאיש אשר יעשנה ער וענה מאהלי יעקב ומגיש מנחה לה' צבאות\"\u0004 (מלאכי ב, יב), ודרשו: \u0003אם ישראל הוא\u0004 החוטא — \u0003לא יהיה לו\u0004 בצאצאיו אדם \u0003ער\u0004 ומבין בין ה\u0003חכמים, ו\u0004אף \u0003לא\u0004 מבניו שיוכל להיות \u0003עונה\u0004 לשאלות בין ה\u0003תלמידים\u0004 שלפניהם. \u0003ואם כהן הוא\u0004 — \u0003לא יהיה לו בן מגיש מנחה,\u0004 ומאחר שבכל זאת היו לפנחס בנים ובני בנים ששמשו ככהנים, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ש\u0003פנחס לא חטא.\u0004","ומקשים: \u0003אלא הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"אשר ישכבן\"\u0004 ומשמע ששניהם עשו זאת! ומתרצים: במקרא כתוב הדבר בכתיב חסר, ויש אפשרות לומר כי \u0003\"ישכבן\" כתיב\u0004 \u0005[כתוב]\u0006 בלשון יחיד, ולא חטאו שניהם.","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 שאמר עלי: \u0003\"אל בני כי לוא טובה השמעה\u0004 אשר אנכי שומע מעבירים עם ה'\u0003\"\u0004 (שמואל א' ב, כד), ואם כן הפנייה כאן היא לשני הבנים! \u0003אמר רב נחמן בר יצחק:\u0004 גם כאן יתכן לומר כי \u0003\"בני\" כתיב\u0004 \u0005[נאמר],\u0006 שאפשר לקרוא זאת בלשון יחיד.","ומקשים: והלא כתוב \u0003\"מעברים\"\u0004 והוא נדרש כאן שכוונתו: גורמים לעבור עבירה, וכתוב על שניהם בלשון רבים! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: \"מעבירם\" כתיב\u0004 \u0005[נאמר],\u0006 בכתיב חסר, שאפשר להבינו כלשון יחיד.","ובכל זאת מקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \"ובני עלי \u0003בני בליעל\u0004 לא ידעו את ה'\" (שמואל א' ב, יב)! ומשיבים: \u0003מתוך שהיה לו לפנחס למחות לחפני\u0004 על מעשיו \u0003ולא מיחה, מעלה עליו הכתוב כאילו\u0004 גם הוא \u0003חטא.\u0004","\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: כל האומר\u0004"],["\u0003בני שמואל חטאו אינו אלא טועה, שנאמר: \"ויהי כאשר זקן שמואל\u0004 וישם את בניו שופטים לישראל... \u0003ובניו לא הלכו בדרכיו\u0004 ויטו אחרי הבצע ויקחו שוחד ויטו משפט\u0003\"\u0004 (שמואל א' ח, א-ג), ומן ההדגשה \"ולא הלכו בניו בדרכיו\" נלמד: \u0003בדרכיו הוא\u0004 ש\u0003לא הלכו,\u0004 ואולם \u0003מיחטא נמי\u0004 \u0005[לחטוא גם כן]\u0006 \u0003לא חטאו,\u0004 שאמנם לא היו מושלמים כאביהם, אך לא חטאו.","\u0003אלא מה\u0004 (כיצד) \u0003אני מקיים\u0004 את דברי הכתוב \u0003\"ויטו אחרי הבצע\"\u0004 — \u0003שלא עשו כמעשה אביהם,\u0004 שכן \u0003היה שמואל הצדיק מחזר בכל מקומות ישראל ודן אותם בעריהם, שנאמר: \"והלך מדי שנה בשנה וסבב בית אל והגלגל והמצפה ושפט את ישראל\u0004 את כל המקומות האלה\u0003\"\u0004 (שמואל א' ז, טז), \u0003והם לא עשו כן\u0004 ללכת ממקום למקום ולזכות את ישראל, \u0003אלא ישבו בעריהם כדי להרבות שכר לחזניהן\u0004 (שמשיהם) \u0003ולסופריהן,\u0004 ולכן מעלה עליהם הכתוב שחטאו ברדיפת בצע ושוחד.","ומעירים: דבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו בכך במקום אחר. ששנינו שנחלקו במשמעות דברי הכתוב \u0003\"ויטו אחרי הבצע\",\u0004 ש\u0003ר' מאיר אומר\u0004 ש\u0003חלקם שאלו בפיהם,\u0004 שהיו מבקשים את המעשרות המגיעים להם בתור לויים, ועל ידי כך קפחו לויים אחרים. \u0003ר' יהודה אומר: מלאי הטילו על בעלי בתים,\u0004 שהיו מטילים על בני העיר חובה לדאוג לפרנסתם. \u0003ר' עקיבא אומר: קופה יתירה של מעשר נטלו בזרוע,\u0004 שלקחו בכוח יותר מן הראוי לחלקם. \u0003ר' יוסי אומר: מתנות\u0004 הראויות להם \u0003נטלו בזרוע,\u0004 ולא נהגו כראוי, שהלוי צריך לקבל ולא לקחת בעצמו.","\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: כל האומר\u0004 ש\u0003דוד חטא אינו אלא טועה, שנאמר: \"ויהי דוד לכל דרכיו משכיל וה' עמו\"\u0004 (שמואל א' יח, יד). שכן וכי \u0003אפשר\u0004 ש\u0003חטא בא לידו ו\u0004בכל זאת תהא ה\u0003שכינה עמו?!\u0004","\u0003אלא מה אני מקיים\u0004 את דברי התוכחה של נתן \u0003\"מדוע בזית את דבר ה' לעשות הרע\u0004 בעיני את אוריה החיתי הכית בחרב ואת אשתו לקחת לך לאשה ואותו הרגת בחרב בני עמון\u0003\"\u0004 (שמואל ב' יב, ט), — יש להבין זאת \u0003שביקש לעשות\u0004 כן \u0003ולא עשה.\u0004","\u0003אמר רב: רבי\u0004 (ר' יהודה הנשיא) \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003מ\u0004בית \u0003דוד מהפך ודריש בזכותיה\u0004 \u0005[ודורש בזכותו]\u0006 של \u0003דוד.\u0004 ועל מה שנאמר \u0003\"מדוע בזית את דבר ה' לעשות הרע\" רבי אומר: משונה\u0004 \u0005[שונה]\u0006 \u0003רעה זו\u0004 שנאמרה בדוד \u0003מכל רעות\u0004 אחרות \u0003ש\u0004נאמרו \u0003בתורה,\u0004 שהמלים \"לעשות הרע\" מיוחדות, \u0003שכל\u0004 ה\u0003רעות\u0004 האחרות \u0003ש\u0004נאמרו \u0003בתורה כתיב בהו\u0004 \u0005[נאמר בהן]\u0006 לשון \u0003\"ויעש\", וכאן כתיב\u0004 \u0005[נאמר]\u0006 לשון \u0003\"לעשות\",\u0004 והדגשה זו באה לומר \u0003שביקש לעשות ולא עשה,\u0004 וכוונתו אכן לא היתה לטובה, ואולם לא כן מעשיו.","ומה שנאמר \u0003\"את אוריה החתי הכית בחרב\"\u0004 — \u0003שהיה לך לדונו בסנהדרין\u0004 כמורד במלכות, \u0003ולא דנת\u0004 אותו בדרך זו, אלא הרגתו שלא לפי כללי הדין המקובלים. \u0003\"ואת אשתו לקחת לך לאשה\"\u0004 — שבסופו של דבר \u0003ליקוחין\u0004 (נישואין) \u0003יש לך בה,\u0004 כלומר, אף שאין הדבר נאה, מכל מקום לא היתה על פי החוק אשת איש שבה אין נשואין תופסים כלל.","וטעמו של דבר, ש\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: כל היוצא למלחמת בית דוד\u0004 ושאר מלחמות ישראל במלכותם, \u0003כותב גט כריתות לאשתו,\u0004 שאם יקרה דבר וייהרג לא תישאר אשתו עגונה, ותוכל להינשא כרצונה. וכפי \u0003שנאמר: \"ואת עשרת חריצי החלב האלה תביא לשר האלף ואת אחיך תפקד לשלום ואת ערבתם תקח\"\u0004 (שמואל א' יז, יח),","ו\u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"ערבתם\"?\u0004 — \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף:\u0004 משמעו — \u0003דברים המעורבים בינו לבינה,\u0004 כלומר, את הגט שקובע יחסים בינו לבינה — הרי שכבר נהגו אנשי הצבא לשלוח גט לנשיהם.","\u0003\"ואתו הרגת בחרב בני עמון\"\u0004 — \u0003מה חרב בני עמון אי\u0004 (אין) \u0003אתה נענש עליו,\u0004 על האנשים שנהרגו במלחמה, \u0003אף אוריה החתי אי אתה נענש עליו.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003מורד במלכות הוה\u0004 \u0005[היה].\u0006 שכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 לדוד: \u0003\"ואדני יואב ועבדי אדני על פני השדה חנים\"\u0004 (שמואל ב' יא, יא), שבפני המלך אין מזכירים אדנותו של אחר, ולכן היה אסור לו להזכיר את אדנותו של יואב בפני דוד, שהזכרה כזאת כמוה כמרידה בו.","\u0003אמר רב: כי מעיינת ביה\u0004 \u0005[כאשר אתה מעיין בו],\u0006 בעניינו של \u0003דוד לא משכחת ביה בר מדאוריה\u0004 \u0005[אינך מוצא בו\u0006 עוון \u0005חוץ]\u0006 \u0003מ\u0004זה של \u0003אוריה. דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004אשר עשה דוד את הישר בעיני ה' ולא סר מכל אשר ציוהו כל ימי חייו \u0003רק בדבר אוריה החתי\"\u0004 (מלכים א' טו, ה).","\u0003אביי קשישא רמי\u0004 \u0005[הזקן השליך,\u0006 הקשה\u0005]\u0006 מדברי \u0003רב\u0004 במקום אחד על דברי \u0003רב\u0004 במקום אחר: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כך]\u0006 בענין דוד? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: קיבל דוד לשון הרע.\u0004 וכידוע, כשם שאסור לומר לשון הרע כך אסור לקבלו ולהאמין לו. לדבר זה לא מצאו תשובה, ועל כן עדיין \u0003קשיא\u0004 \u0005[\u0006\u0005קשה]\u0006 הדבר.","\u0003גופא\u0004 \u0005[לגופו\u0006 של דבר\u0005]\u0006 \u0003אמר רב: קיבל דוד לשון הרע, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שכשחיפש דוד את בנו יונתן \u0003\"ויאמר לו המלך\u0004 (דוד לציבא עבד שאול) \u0003איפוא הוא ויאמר ציבא אל המלך הנה הוא בית מכיר בן עמיאל בלא דבר\"\u0004 (שמואל ב' ט, ד), ואת משמעות \"בלא דבר\", מפרשים: שרצה לומר שבן יהונתן הוא אדם ריק בלא דבר תורה. ומסופר: \u0003\"וישלח המלך\u0004 דוד \u0003ויקחהו מבית מכיר בן עמיאל מלא דבר\"\u0004 (שמואל ב' ט, פסוק ה'), ומשמעות \"מלא דבר\" — שמצא אותו מלא בדברי תורה.","וכמו כן \u0003מכדי חזייה דשקרא\u0004 \u0005[הרי ראה ששקרן]\u0006 \u0003הוא\u0004 ציבא, ואם כן \u0003כי הדר אלשין עילויה מאי טעמא קיבלה מיניה\u0004 \u0005[כאשר חזר והלשין עליו מדוע קיבל ממנו]?\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שבבריחת דוד מאבשלום פגש את ציבא \u0003\"ויאמר המלך\u0004 ו\u0003איה בן אדניך ויאמר ציבא אל המלך הנה יושב בירושלם\u0004 כי אמר היום ישיבו לי בית ישראל את ממלכות אבי\u0003\"\u0004 (שמואל ב' טז, ג), \u0003ומנא לן\u0004 \u0005[ומניין לנו]\u0006 ש\u0003קיבל מיניה\u0004 \u0005[ממנו]?\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויאמר המלך\u0004 לציבא \u0003הנה לך כל אשר למפיבשת ויאמר ציבא השתחויתי אמצא חן בעיני\u0004 אדוני \u0003המלך\"\u0004 (שמואל ב' טז, ד).","\u0003ושמואל אמר: לא קיבל דוד לשון הרע\u0004 כי \u0003דברים הניכרים חזא ביה\u0004 \u0005[ראה בו]\u0006 במפיבושת, ובשלהם נדמה היה לו שאכן צדק ציבא. \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומפיבשת בן שאול ירד לפני המלך ולא עשה רגליו ולא עשה שפמו ואת בגדיו לא כבס\u0004 למן היום לכת המלך עד היום אשר בא בשלום\u0003\"\u0004 (שמואל ב' יט, כה), וחשב דוד שהוא מתאבל על שובו בשלום. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי כי בא ירושלם לקראת המלך ויאמר לו המלך למה לא הלכת עמי מפיבשת. ויאמר אדני המלך עבדי רמני כי אמר עבדך אחבשה לי החמור וארכב עליה ואלך את המלך כי פסח\u0004"],["\u0003עבדך. וירגל בעבדך אל אדני המלך ואדני המלך כמלאך האלהים ועשה הטוב בעיניך\"\u0004 (שמואל ב' כו–כח). \u0003\"ויאמר לו המלך למה תדבר עוד דבריך אמרתי אתה וציבא תחלקו את השדה. ויאמר מפיבשת אל המלך גם את הכל יקח אחרי אשר בא אדני המלך בשלום אל ביתו\"\u0004 (שמואל ב' ל–לא) ומתפרש ש\u0003אמר לו\u0004 מפיבושת: \u0003אני אמרתי \"מתי תבא בשלום\" ואתה עושה לי כך? לא עליך יש לי תרעומות אלא על מי שהביאך בשלום.\u0004","ו\u0003היינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"ובן יהונתן מריב בעל\"\u0004 (דברי הימים א' ח, לד), ותמוה הדבר, שכן \u0003וכי \"מריב בעל\" שמו? והלא מפיבשת שמו! אלא מתוך שעשה מריבה עם בעליו\u0004 הקדוש ברוך הוא, ובא בתרעומת מדוע ניצל דוד המלך, נקרא בכנוי זה. \u0003יצתה\u0004 (יצאה) \u0003בת קול ואמרה לו: נצא בר נצא\u0004 \u0005[מתקוטט בן מתקוטט].\u0006 ומסבירים: \u0003\"נצא\"\u0004 \u0005[מתקוטט]\u0006 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 שבא בתרעומת בענין דוד. \u0003\"בר נצא\"\u0004 \u0005[בן מתקוטט]\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויבא שאול עד עיר עמלק וירב בנחל\"\u0004 (שמואל א' טו, ה), ו\u0003אמר ר' מני:\u0004 שעשה מריבה עם הקדוש ברוך הוא \u0003על עסקי נחל,\u0004 שאמר: אם על אדם אחד שנהרג עורפים את העגלה בנחל (ראה דברים כא, א-ט) מדוע יש להרוג את כל העמלקים הללו?","ולענייננו \u0003אמר רב יהודה אמר רב: בשעה שאמר דוד למפיבשת: אתה וציבא תחלקו את השדה, יצתה בת קול ואמרה לו: רחבעם וירבעם יחלקו את המלוכה.\u0004 ו\u0003אמר רב יהודה אמר רב: אילמלי לא קיבל דוד לשון הרע\u0004 בענין מפיבושת \u0003לא נחלקה מלכות בית דוד, ולא עבדו ישראל עבודה זרה\u0004 בשל ירבעם, \u0003ולא גלינו מארצנו.\u0004","","\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: כל האומר\u0004 ש\u0003שלמה\u0004 המלך \u0003חטא אינו אלא טועה, שנאמר: \"ולא היה לבבו שלם עם ה' אלהיו כלבב דויד אביו\"\u0004 (מלכים א' יא, ד). ויש להבין: \u0003כלבב דוד אביו הוא\u0004 ש\u0003לא הוה\u0004 \u0005[היה],\u0006 ואולם \u0003מיחטא נמי\u0004 \u0005[לחטוא גם כן]\u0006 \u0003לא חטא.\u0004","\u0003אלא מה\u0004 (כיצד) \u0003אני מקיים\u0004 את דברי הכתוב \u0003\"ויהי לעת זקנת שלמה נשיו הטו את לבבו\u0004 ללכת אחרי אלהים אחרים\" (מלכים א' יא, ד) — יש להבין כי \u0003ההיא\u0004 שאמרנו מפורשת \u0003כ\u0004דברי \u0003ר' נתן.\u0004 ש\u0003ר' נתן רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בדברי הכתובים. שבמצד אחד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויהי לעת זקנת שלמה נשיו הטו את לבבו\", והכתיב\u0004 \u0005[ו\u0006מצד אחר \u0005הרי נאמר]:\u0006 \u0003\"כלבב דויד אביו\"\u0004 ומשמע: \u0003כלבב דוד אביו הוא\u0004 ש\u0003לא הוה\u0004 \u0005[היה],\u0006 ואולם \u0003מיחטא נמי\u0004 \u0005[לחטוא גם כן]\u0006 \u0003לא חטא!\u0004 אלא יש לומר כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003\"ויהי לעת זקנת שלמה נשיו הטו את לבבו ללכת אחרי אלהים אחרים\", ו\u0004אולם הוא \u0003לא הלך.\u0004 ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אז יבנה שלמה במה לכמוש שקץ מואב\u0004 בהר אשר על פני ירושלים ולמולך שקוץ בני עמון\u0003\"\u0004 (מלכים א' יד, ז), והרי שכן הלך אחר עבודה זרה! ומתרצים: \u0003שבקש לבנות ולא בנה.\u0004","","ומקשים: אם כך מבינים אנו צורה זו של לשון עתיד, \u0003אלא מעתה\u0004 וכי תפרש את דברי הכתוב \u0003\"אז יבנה יהושע מזבח לה'\u0004 אלהי ישראל בהר עיבל\u0003\"\u0004 (יהושע ח, ל) וכי תפרש \u0003שבקש לבנות ולא בנה?! אלא\u0004 ודאי מדובר ש\u0003בנה,\u0004 ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בשלמה, הכוונה ש\u0003בנה!\u0004 \u0003אלא\u0004 יש להבין זאת \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר:\u0004 את הכתוב ביאשיהו \u0003\"ואת הבמות אשר על פני ירושלם אשר מימין להר המשחה אשר בנה שלמה מלך ישראל לעשתרת שקץ צדונים\u0004 ולכמוש שקוץ מואב ולמלכום תועבת בני עמון טימא המלך\u0003\"\u0004 (מלכים ב' כג, יג).","","שיש לתמוה: וכי \u0003אפשר\u0004 ש\u0003בא\u0004 המלך הצדיק \u0003אסא ולא ביערם,\u0004 וכן בא \u0003המלך יהושפט ולא ביערם, עד שבא יאשיה וביערם? והלא כל עבודה זרה שבארץ ישראל אסא ויהושפט ביערום! אלא מקיש\u0004 \u0005[משווה]\u0006 \u0003ראשונים לאחרונים, מה אחרונים,\u0004 כלומר, יאשיהו, \u0003לא עשו\u0004 ביעור זה, ונעשה עוד קודם לכן, \u0003ו\u0004אף על פי כן \u0003תלה בהן\u0004 הכתוב \u0003לשבח\u0004 כאילו ביער יאשיהו בתוך שאר עבודה זרה גם במות אלה, \u0003אף ראשונים,\u0004 שלמה, \u0003לא עשו\u0004 את הבמות, \u0003ו\u0004אף על פי כן \u0003תלה בהן\u0004 הכתוב \u0003לגנאי\u0004 כאילו בנה.","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויעש שלמה הרע בעיני ה'\"\u0004(מלכים א, יא, ו)! \u0003אלא מפני שהיה לו למחות בנשיו ולא מיחה מעלה עליו הכתוב כאילו חטא\u0004 בעצמו.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: נוח\u0004 היה \u0003לו לאותו צדיק\u0004 שלמה, \u0003שיהא שמש\u0004 ועובד עבודה קשה \u0003לדבר אחר\u0004 (עבודה זרה) \u0003ואל יכתב בו \"ויעש הרע בעיני ה'\",\u0004 אף שלא עשה. \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל:\u0004 חטא שלמה היה ש\u0003בשעה שנשא\u0004 שלמה \u0003את בת פרעה, הכניסה לו אלף מיני זמר, ואמרה לו: כך עושים לעבודה זרה פלונית, וכך עושים לעבודה זרה פלונית, ולא מיחה בה\u0004 על דיבורים אלה. ו\u0003אמר רב יהודה אמר שמואל: בשעה שנשא שלמה את בת פרעה ירד גבריאל ונעץ קנה בים ו\u0004אחר זמן \u0003עלה\u0004 ונדבק \u0003בו,\u0004 בקנה, \u0003שירטון\u0004 והצטברה אדמה משנה לשנה, \u0003ו\u0004על מקום זה \u0003נבנה כרך גדול של רומי\u0004 שהיא המכשיר להעניש בסוף דורות את ישראל.","","","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנו]:\u0006 \u0003אותו היום שהכניס ירבעם שני עגלי זהב, אחד בבית אל ואחד בדן, נבנה צריף\u0004 (סוכה קלועה) \u0003אחד,\u0004 שהיה הבית הראשון באותו מקום, \u0003וזהו\u0004 ראשית \u0003איטליאה\u0004 (איטליה) \u0003של יון.\u0004 ו\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: כל האומר\u0004 ש\u0003יאשיהו חטא\u0004 — \u0003אינו אלא טועה, שנאמר: \"ויעש הישר בעיני ה' וילך בכל דרך דוד אביו\u0004 ולא סר ימין ושמאל\u0003\"\u0004 (מלכים ב' כב, ב). \u0003אלא מה אני מקיים\u0004 בדברי הכתוב \u0003\"וכמהו לא היה לפניו מלך אשר שב\u0004 אל ה' בכל לבבו ובכל נפשו ובכל מאודו ככל תורת משה ואחריו לא קם כמוהו\u0003\"\u0004 (מלכים ב' כג, כה), שלכאורה אפשר להבין מכאן שבימיו הראשונים היה חוטא, אלא שאחר כך שב אל ה' — לא תשובה על חטאים ממש עשה, אלא","","\u0003שכל דין\u0004 דין שהיה בו הוא הדיין \u0003שדן מ\u0004אז היה \u0003בן שמנה\u0004 שנים כשעלה למלוכה, \u0003עד\u0004 בן \u0003שמנה עשרה החזירן להן\u0004 לאותם שחייב בדין, שחשש שמא בשנות ילדותו לא דן כהלכה. ו\u0003שמא תאמר\u0004 כי \u0003נטל מזה\u0004 שזיכהו אז \u0003ונתן לזה\u0004 שחייבו — \u0003תלמוד לומר\u0004 ששב \u0003\"\u0004ו\u0003בכל מאדו\"\u0004 שמובנו בכל ממונו, וכוונתו: \u0003שנתן להם משלו.\u0004","\u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 אימרה זו על דעת \u0003רב,\u0004 ש\u0003אמר רב: אין לך גדול בבעלי תשובה יותר מיאשיהו בדורו ואחד בדורנו.\u0004 ושואלים: \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 אחד זה בדורו של רב? ומשיבים: הוא \u0003אבא אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' ירמיה בר אבא. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003אחא אחוה\u0004 \u0005[אחיו]\u0006 של \u0003אבא אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב ירמיה בר אבא.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ר' אבא ואחא אחי הוו\u0004 \u0005[אחים היו].\u0006","\u0003אמר רב יוסף: ועוד אחד\u0004 בעל תשובה גדול יש \u0003בדורנו. ומנו\u0004 \u0005[ומי הוא]?\u0006 — \u0003עוקבן בר נחמיה ריש גלותא\u0004 \u0005[ראש הגולה].\u0006 \u0003והיינו\u0004 \u0005[וזהו]\u0006 המכונה \u0003\"נתן דצוציתא\". אמר רב יוסף: הוה יתיבנא בפירקא, והוה קא\u0004 \u0005[הייתי יושב בדרשת הרגל, והייתי]\u0006 \u0003מנמנם, וחזאי בחילמא דקא פשט\u0004 \u0005[וראיתי בחלומי שפשט\u0006 המלאך\u0005]\u0006 \u0003ידיה וקבליה\u0004 \u0005[ידו וקיבל אותו]\u0006 את נתן דצוציתא, להראות שחזר בתשובה שלימה.",""],["במשנה זו נמנים הדברים שמותר ושאסור לאשה לצאת בהם בשבת. ודבר זה תלוי בהכרעה אם חפץ מסויים נחשב כתכשיט לאשה או כמשא בלבד. ואף אם נחשב כתכשיט, שמא יש לחשוש לטלטולו ביד ברשות הרבים. ואמרו: \u0003במה,\u0004 באלו דברים \u0003אשה יוצאה\u0004 (יוצאת) בשבת \u0003ובמה,\u0004 באלו דברים \u0003אינה יוצאה?\u0004","— \u0003לא תצא אשה לא בחוטי צמר ולא בחוטי פשתן ולא ברצועות\u0004 מחומרים אחרים \u0003ש\u0004אשה קולעת \u0003ב\u0004שערות \u0003ראשה. ו\u0004אשה הרוצה לטבול לטהרתה \u0003לא תטבול בהן,\u0004 בכל אלה, \u0003עד שתרפם,\u0004 שכאשר החוטים והרצועות מהודקים בשערות ראשה אין המים יכולים להכנס ברווח בין השיער והרצועה ולא עולה לה טבילה.","\u0003ו\u0004כן אסור לאשה לצאת \u0003לא ב\u0004תכשיט הקרוי \u0003\"טוטפת\", ולא בסרביטין בזמן שאינן תפורים\u0004 וצמודים לכיסוי ראשה. וכן \u0003לא\u0004 תצא אשה \u0003בכבול לרשות הרבים. \u0004","ואף \u0003לא בעיר של זהב ולא ב\u0004תכשיט \u0003קטלא ולא בנזמים ולא בטבעת שאין עליה חותם\u0004 ועשויה לקישוט בלבד, \u0003ולא במחט שאינה נקובה\u0004 המשמשת כתכשיט.","\u0003ו\u0004אולם \u0003אם יצאת\u0004 (יצאה) בכל אחד מאלה \u0003אינה חייבת חטאת,\u0004 כי מדין תורה מותר לאשה לצאת בתכשיטיה, ורק החכמים גזרו על מקצת תכשיטים שלא תצא אשה בהם, שמא תבוא להראותם לחברותיה ותטלטלם ארבע אמות ברשות הרבים.","שנינו במשנה כי אין אשה טובלת בקישוטי השיער המהודקים בראשה. ושואלים: \u0003טבילה מאן דכר\u0004 \u0005[מי הזכיר]\u0006 את \u0003שמה?\u0004 והלא המשנה מדברת בדיני שבת, ומדוע דנה בהלכות טבילה?","\u0003אמר רב נחמן בר יצחק\u0004 שכך \u0003אמר רבה בר אבוה: מה טעם קאמר\u0004 \u0005[אמר],\u0006 שיש להבין דין זה כדבר הסבר, ולא כתוספת שאינה מן הענין. וכך יש להבין את המשנה: \u0003מה טעם לא תצא אשה לא בחוטי צמר ולא בחוטי פשתן\u0004 — \u0003מפני שאמרו חכמים\u0004 כי אף \u0003ב\u0004ימות ה\u0003חול לא תטבול בהן עד שתרפם. וכיון\u0004 ש\u0003ב\u0004ימות ה\u0003חול לא תטבול בהן עד שתרפם, בשבת\u0004 — \u0003לא תצא\u0004 בהם, \u0003דילמא מיתרמי\u0004 \u0005[שמא תזדמן]\u0006 \u0003לה טבילה של מצוה ושריא להו\u0004 \u0005[ותתיר אותם]\u0006 בשעת הטבילה, \u0003ואתי לאתויינהו\u0004 \u0005[ותבוא להביאם,\u0006 לטלטלם\u0005]\u0006 \u0003ארבע אמות ברשות הרבים.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב כהנא מרב: תיכי חלילתא מאי\u0004 \u0005[\u0006חוטים העשויים \u0005כשרשרות חלולות, מה\u0006 דינם\u0005]\u0006 האם מותר לנשים לצאת בהם בשבת, או לא? והדבר תלוי בשאלה אם יש בהם משום חציצה בטבילה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אריג קאמרת\u0004 \u0005[אמרת]?\u0006 \u0003כל שהוא אריג לא גזרו\u0004 בו חכמים, כי באריג נכנסים המים ואין צורך לרפותו ואין איפוא חשש שתתירו לטבילה ותבוא לידי טלטול. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר רב הונא בריה\u0004 \u0005[שמו]\u0006 של \u0003רב יהושע: כל שהוא אריג לא גזרו\u0004 בו חכמים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת, ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: חזינא לאחוותי דלא קפדן עלייהו\u0004 \u0005[ראיתי את אחיותי שאינן מקפידות עליהם]\u0006 ומתרחצות גם כאשר אותן שרשרות אריג קשורות בשערן, ואם כן נראה שהמים נכנסים בתוכן היטב וממילא אינן חוצצות אף לענין טבילה.","ושואלים: \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל למעשה \u0005יש]\u0006 \u0003בין הך לישנא\u0004 \u0005[לשון זו],\u0006 בראשונה, \u0003ובין הך לישנא\u0004 \u0005[לשון זו],\u0006 השניה?","ומסבירים: \u0003איכא בינייהו דטניפן\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה כשהשרשרות \u0005מטונפות,\u0006 מלוכלכות\u0005];\u0006 \u0003להך לישנא דאמר\u0004 \u0005[לאותה לשון\u0006 \u0003שאמרה]\u0004 כי \u0003כל שהוא אריג לא גזרו\u0004 בו חכמים — \u0003הני נמי\u0004 \u0005[אלא\u0006 הלא \u0005גם כן]\u0006 \u0003ארוג\u0004 הם, \u0003ולהך לישנא\u0004 \u0005[וללשון זו]\u0006 ש\u0003אמרת\u0004 שמשמע ממנה שטעם הדבר \u0003משום קפידא\u0004 \u0005[הקפדה],\u0006 \u0003כיון דטניפא מקפד קפדא עלייהו\u0004 \u0005[ש\u0006הן \u0005מטונפות,\u0006 מלוכלכות, \u0005מקפידה\u0006 היא \u0005עליהן]\u0006 ובודאי תתיר אותן בשעת רחיצה, ומחויבת לעשות כן בשעת טבילה.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת מקוואות: \u0003ואלו\u0004 הדברים \u0003החוצצין באדם: חוטי צמר, וחוטי פשתן, והרצועות שבראשי הבנות. ר' יהודה אומר:\u0004 חוטים \u0003של צמר ושל שער אין חוצצין מפני שהמים באין בהן. אמר רב הונא: וכולן,\u0004 חוטי הצמר והפשתן, \u0003בראשי הבנות שנינו,\u0004 שהם חוטים שנועדו לקשור את השיער, ולא במקום אחר.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הלכה זו של רב הונא \u0003רב יוסף: למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 אמר רב הונא את דבריו? \u0003אילימא למעוטי\u0004 \u0005[אם נאמר\u0006 שבא \u0005למעט]\u0006 את החוטים שקושרים ב\u0003צואר, ודמאי\u0004 \u0005[ושל מה,\u0006 מאיזה חומר\u0005]\u0006 הם עשויים, \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 חוטי \u0003צמר, השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003רך על גבי קשה,\u0004 כלומר, חוט הצמר הרך, על גבי השערות שהן קשות ביחס אליו אמרנו שהוא \u0003חוצץ,\u0004 שנכרך הצמר סביב השיער בהידוק רב עד כדי חציצה בפני המים, \u0003רך על גבי רך\u0004 כצמר על בשר הצואר \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 ודאי הוא שיש בכך חציצה.","\u0003ואלא\u0004 תאמר שבאו דברי רב הונא \u0003למעוטי\u0004 \u0005[למעט]\u0006 של \u0003חוטי פשתן.\u0004 ושוב יש לשאול: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אמרת כי \u0003קשה על גבי קשה,\u0004 פשתן על גבי שיער, נכרך בהידוק רב עד כדי שהוא \u0003חוצץ, קשה על גבי רך מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","\u0003אלא אמר רב יוסף:\u0004 רב הונא לא דן באפשרות הצמר או הפשתן להתהדק מסביב לבשר, אלא \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003רב הונא: לפי שאין אשה חונקת את עצמה\u0004 כאשר היא מהדקת את הרצועה בצוארה. ובודאי לא תהדק את הרצועות והחוטים עד כדי שלא יוכלו המים לבוא פנימה.","אף על מסקנה אחרונה זו \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי:\u0004 שנינו בברייתא ש\u0003הבנות יוצאות\u0004 בשבת \u0003בחוטין\u0004 הקשורים בנקבים \u0003שבאזניהן,\u0004 שנהגו לנקוב לבנות הקטנות נקבים על מנת שיוכלו לשים בתוכם עגילים, וכשאין עגילים באוזן שמים לפי שעה חוטים בנקב כדי שלא יסתם, \u0003אבל לא בחבקין\u0004 (רצועות) \u0003שבצואריהן. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי יש לקבל כנימוק בעל תוקף בהלכה, ש\u0003אין אשה חונקת\u0004 את \u0003עצמה,\u0004 אם כן \u0003חבקין שבצואריהן אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 תצא עמם? והרי ודאי אינם מהודקים עד כדי להוות חציצה לטבילה!","\u0003אמר רבינא:\u0004"],["\u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004מין חבק מיוחד הקרוי \u0003קטלא עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהיא רצועה רחבה ומקושטת התלויה בצואר, ושממנה יוצא כעין סינור קטן על החזה, ובקטלא זו \u0003אשה חונקת את עצמה\u0004 כי הרצועה רחבה והידוקה אינו מכאיב. והטעם לקשירה זו — משום \u0003דניחא\u0004 \u0005[שנוח]\u0006 \u0003לה שתראה כבעלת בשר,\u0004 כאשר הבשר בולט מצדי הקטלא, שנחשב אז לנוי לאשה כשהיא בעלת בשר.","באותה משנה במסכת מקוואות שנינו ש\u0003ר' יהודה אומר\u0004 שחוטים \u0003של צמר ושל שער אין חוצצין\u0004 בטבילה, \u0003מפני שהמים באין בהן.\u0004","\u0003אמר רב יוסף\u0004 שכך \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: הלכה כר' יהודה בחוטי שער,\u0004 אף כי אין הלכה כמותו בחוטי צמר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אחר שאומר אתה כי \u0003הלכה\u0004 כדבריו, \u0003מכלל\u0004 הדברים אתה למד \u0003דפליגי\u0004 \u0005[שנחלקו]\u0006 חכמים בענין חוטי שיער. ואולם במשנה לא נזכרה כלל דעה שחוטי שיער יש בהם משום חציצה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003אי לאו דשמעינן\u0004 \u0005[שאם לא היינו שומעים,\u0006 לא היתה ידועה\u0005]\u0006 דעת \u0003התנא קמא\u0004 \u0005[הראשון]\u0006 \u0003דאיירי\u0004 \u0005[שעוסק,\u0006 דן\u0005]\u0006 \u0003ב\u0004ענין \u0003חוטי שער, איהו נמי\u0004 \u0005[הוא\u0006 ר' יהודה, \u0005גם כן]\u0006 \u0003לא הוה מיירי\u0004 \u0005[היה דן]\u0006 בהם, ולכן יש מקום להניח כי דעת התנא קמא היתה לאסור בחוטי שיער, ובא ר' יהודה לחלוק עליו. ואולם הדברים ניתנים להתפרש גם אחרת: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 בדרך \u0003\"כשם\" קאמר להו\u0004 \u0005[אמר להם],\u0006 כלומר, \u0003כי היכי דמודיתו\u0004 \u0005[כשם שאתם מודים]\u0006 \u0003לי בחוטי שער\u0004 שאינם חוצצים, \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי נמי\u0004 \u0005[גם כן]\u0006 \u0003בחוטי צמר,\u0004 והזכרת חוטי שיער לא לציין ולהבליט מחלוקת באה, אלא להיפך, להסתמך על הלכה מוסמכת,","ואכן \u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003אמר רב נחמן\u0004 שכך \u0003אמר שמואל: מודים חכמים לר' יהודה בחוטי שער.\u0004","וכן \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003חוטי צמר חוצצין, חוטי שער אין חוצצין. ר' יהודה אומר: של צמר ושל שער אין חוצצים.\u0004","\u0003אמר רב נחמן בר יצחק: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן\u0006 מובנת כך בדרך \u0005דיוק],\u0006 \u0003דקתני\u0004 \u0005[ששנינו]\u0006 במשנה אחרת בפרקנו: \u0003יוצאה אשה בחוטי שער בין משלה בין משל חברתה.\u0004 ולכאורה משנה זו \u0003מני\u0004 \u0005[\u0006של \u0005מי היא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שדעת \u0003ר' יהודה\u0004 היא — \u0003אפילו חוטי צמר נמי\u0004 \u0005[גם כן]\u0006 צריך היה להתיר! \u0003אלא לאו רבנן\u0004 \u0005[האם לא\u0006 תאמר כי שיטת \u0005חכמים]\u0006 \u0003היא, ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 כי \u0003בחוטי שער לא פליגי\u0004 \u0005[אינם חלוקים].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","בין תכשיטי הנשים ששנינו במשנה שלא תצא האשה בהם נאמר \u0003כי לא\u0004 תצא האשה \u0003ב\u0004תכשיט הקרוי \u0003\"טוטפת\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה היא]\u0006 \u0003\"טוטפת\"\u0004 זו? \u0003אמר רב יוסף: חומרתא דקטיפתא\u0004 \u0005[צרור בשמים]\u0006 כנגד עין הרע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ותהוי\u0004 \u0005[ותהא]\u0006 עטיפה זו \u0003כקמיע מומחה,\u0004 כלומר, קמיע שנבדקה והוכחה יעילותה, \u0003ותשתרי\u0004 \u0005[ותותר],\u0006 שהרי קמיע כזה מותר לטלטלו בשבת!","\u0003אלא אמר רב יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי:\u0004 הטוטפת היא \u0003אפוזיינו,\u0004 שהוא תכשיט שעונדים על המצח. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003יוצאה אשה בסבכה המוזהבת\u0004 שהיא שמה כעין רשת על גבי שערותיה כדי להחזיקן, \u0003ובטוטפת ובסרביטין הקבועין בה\u0004 בסבכה, כי ודאי לא תסיר האשה את כל כיסוי ראשה להראות לחברתה את תכשיטיה.","ואמרו: \u0003איזו טוטפת ואיזו סרביטין? אמר ר' אבהו: טוטפת\u0004 היא זו המונחת על המצח ו\u0003מוקפת לה מאזן לאזן. סרביטין\u0004 הם אלה שמוסיפים בהם ו\u0003המגיעין לה עד לחייה.\u0004","\u0003אמר רב הונא:\u0004 תכשיטים אלה \u0003עניות עושין אותן של מיני צבעונין,\u0004 ואילו \u0003עשירות עושין אותן של כסף ושל זהב.\u0004","שנינו במשנה כי \u0003לא\u0004 תצא האשה בשבת \u0003בכבול. אמר ר' ינאי: כבול זה איני יודע מהו, אי כבלא דעבדא תנן\u0004 \u0005[אם חותמת של עבד שנינו\u0006 במשנתנו\u0005],\u0006 שהיו העבדים נוהגים להלך וחותם על בגדיהם כדי שידעו שעבדים הם, וכבול זה הוא שנאסר. \u0003אבל\u0004 מין הכבול במשמעות האחרת, שהוא \u0003כיפה של צמר\u0004 ששמה אשה על שערותיה \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005].\u0006 \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כיפה של צמר תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 שאסורה, \u0003וכל שכן כבלא דעבדא\u0004 \u0005[כבל של עבד].\u0006","\u0003אמר ר' אבהו: מסתברא כמאן דאמר\u0004 \u0005[מסתבר\u0006 לומר \u0005כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003כיפה של צמר תנן\u0004 \u0005[מסתבר כמי שאמר כיפה של צמר שנינו].\u0006 \u0003ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003יוצאה אשה בכבול ובאיסטמא לחצר\u0004 בשבת, \u0003ר' שמעון בן אלעזר אומר: אף בכבול\u0004 שאמרנו, אין ההיתר מוגבל רק לרשות היחיד, אלא אף \u0003לרשות הרבים. כלל אמר ר' שמעון בן אלעזר: כל\u0004 דבר \u0003שהוא למטה מן השבכה יוצאין בו\u0004 בשבת לרשות הרבים, שודאי לא תגלה אשה את הסבכה כדי להראות תכשיט הנתון מתחתיה ברשות הרבים, \u0003כל שהוא למעלה מן השבכה\u0004 כעין כובע וכיוצא בו — \u0003אין יוצאין בו.\u0004 ומהקשר ומסמיכות ההלכה העוסקת בכבול לדברי ר' שמעון בן אלעזר למדים שכבול היא כיפה של צמר הנמצאת תחת הסבכה.","כיון שהוזכרה \"איסטמא\" בברייתא, שואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003איסטמא\u0004 זו? \u0003אמר ר' אבהו:\u0004 איסטמא היא הדבר הנקרא בארמית \u0003\"ביזיוני\".\u0004 ואולם הסבר זה של ר' אבהו שהיה בניב הארמי של ארץ ישראל לא הובן בבבל, ושאלו שם: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003ביזיוני\u0004 זה? \u0003אמר אביי\u0004 שכך \u0003אמר רב:\u0004 הכוונה היא למה שקרוי בבבל \u0003\"כליא פרוחי\",\u0004 שהוא מעין סרט או כובע קטן שאוספים וקושרים בו אותן שערות היוצאות מתחת לסבכה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא, \u0003שלושה דברים נאמרו באיסטמא: אין בה משום כלאים\u0004 (כלאי בגדים, \u0003שעטנז),\u0004 כיון שאיננה ארוגה אלא היא עשוייה מלבד קשה, ובכגון זה אין כלאיים נוהגים. \u0003ואינה מטמאה בנגעים\u0004 כי בצרעת הבגד נטמאים רק בגדים ארוגים, \u0003ואין יוצאים בה לרשות הרבים\u0004 בשבת.","\u0003משום\u0004 (בשם) \u0003ר' שמעון אמרו: אף\u0004"],["\u0003אין בה משום עטרות כלות,\u0004 שגזרו חכמים כזכר לחורבן הבית שלא תתקשט כלה בעטרה בחופה, ואיסטמא אינה כלולה באיסור זה.","\u0003ושמואל אמר:\u0004 \"כבול\" זה ששנינו במשנה שאסור לצאת בו בשבת לרשות הרבים, \u0003כבלא דעבדא תנן\u0004 \u0005[חותם של עבד שנינו].\u0006 ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: יוצא העבד\u0004 בשבת \u0003בחותם שבצוארו, אבל לא בחותם שבכסותו,\u0004 ואם חותם זה שבצווארו כבול הוא, הרי אמרו במשנה שאין יוצאים בו לרשות הרבים!","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאמר שמואל שיוצא בו בשבת — הרי זה באופן \u0003דעבד ליה רביה\u0004 \u0005[שעשה לו\u0006 אותו \u0005אדונו],\u0006 שבכגון זה חושש הוא מרבו ולא יבוא להסירו, ואין אם כן חשש לטלטול, ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו במשנתנו שאסור לצאת בכבול ולדעת שמואל זהו חותם העבד, הרי זה באופן \u0003דעבד איהו לנפשיה\u0004 \u0005[שעשה\u0006 העבד אותו \u0005לעצמו],\u0006 כדי שידעו עבדו של מי הוא ותהא עליו הגנת אדוניו, ומאחר והדבר תלוי בדעתו, יתכן שיבוא להסירו ועלול לבוא לידי טלטול ולכן אסרוהו.","ומקשים: \u0003במאי אוקימתא להא\u0004 \u0005[במה העמדת את זו]\u0006 של \u0003שמואל\u0004 — בחותם \u0003דעבד ליה רביה\u0004 \u0005[שעשה לו רבו],\u0006 אם כן \u0003בחותם שבכסותו אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יצא בו? והלא גם חותם שבכסותו אם עשה לו אותו רבו לא יבוא להסירו!","ומתרצים: החשש הוא \u0003דילמא מיפסק, ומירתת ומיקפל ליה ומחית ליה אכתפיה\u0004 \u0005[שמא יפסק\u0006 החותם וישבר, \u0005ומפחד\u0006 העבד \u0005ומקפל\u0006 את הטלית \u0005ומניחה על כתפו]\u0006 כדי שלא יראה האדון שנשבר החותם בבגד. והאיסור בדבר. ו\u0003כ\u0004פי ששנה \u0003רב יצחק בר יוסף,\u0004 ש\u0003אמר רב יצחק בר יוסף\u0004 שכך \u0003אמר ר' יוחנן: היוצא\u0004 לרשות הרבים \u0003בטלית מקפלת ומונחת לו על כתפיו בשבת\u0004 — \u0003חייב חטאת,\u0004 כי אין זו דרך מלבוש, אלא דרך הוצאת משא.","\u0003וכי הא\u0004 \u0005[וכמו זה]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב חיננא בר שילא: כולהו רבנן דבי ריש גלותא לא ליפקו בסרבלי חתימי, לבר מינך, דלא קפדי עליך דבי ריש גלותא\u0004 \u0005[כל חכמי בית ראש הגולה אל יצאו בסרבלים חתומים,\u0006 בעלי חותם, בשבת, \u0005חוץ ממך, שאין מקפידים עליך בבית ראש הגולה].\u0006 שחכמי ראש הגולה נחשבו רשמית לעבדי הבית, והיו מהלכים בחותם של בית ראש הגולה ובשבת אסור להם ללכת בסרבל חתום, שמא יישבר החותם ומפחד ראש הגולה יבואו להסירו מעליהם ולקפלו ולהניחו על כתפיהם ולטלטלו בשבת. ורק רב חיננא בר שילא שאנשי ראש הגולה אינם מקפידים עליו, ואף אם אין חותם בלבושו אין רואים בכך מרידה בראש הגולה מותר לו לצאת בחותם זה בשבת.","מעתה באים לדון \u0003גופא\u0004 \u0005[לגוף]\u0006 הדברים ש\u0003אמר שמואל\u0004 שמותר לעבד לצאת \u0003בחותם שבצוארו אבל לא בחותם שבבגדו\u0004. ואומרים: \u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003יוצא העבד בחותם שבצוארו אבל לא בחותם שבכסותו.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003לא יצא העבד בחותם שבצוארו ולא בחותם שבכסותו\u0004 בשבת, ולענין טומאה \u0003זה וזה אין מקבלים טומאה. ולא\u0004 יצא \u0003בזוג\u0004 (פעמון) התלוי \u0003בצוארו, אבל יוצא הוא בזוג שבכסותו,\u0004 ולענין טומאה \u0003זה וזה מקבלין טומאה.\u0004","\u0003ולא תצא בהמה לא בחותם שבצוארה, ולא בחותם שבכסותה, ולא בזוג שבכסותה, ולא בזוג שבצוארה\u0004 כיון שלגבי הבהמה אין בכך זה נחשב כתכשיט אלא כמשא, ולענין טומאה \u0003זה וזה,\u0004 החותם והזוג, \u0003אין מקבלין טומאה,\u0004 משום שתכשיטי בהמה וכליה אינם בכלל הדברים המקבלים טומאה. והרי שאסור לעבד לצאת אף בחותם שבצווארו, ושלא כשיטת שמואל!","ומשיבים: \u0003לימא\u0004 \u0005[נאמר]\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 הברייתא שהתירה — הרי זה באופן \u0003דעבד ליה רביה\u0004 \u0005[שעשה לו רבו]\u0006 חותם זה, שמאחר והוא חושש להסירו אין חשש שיבוא לטלטלו, ואילו \u0003הא\u0004 \u0005[זו]\u0006 הברייתא שאסרה — הרי זה באופן \u0003דעבד איהו לנפשיה\u0004 \u0005[שעשה הוא לעצמו]\u0006 ויש חשש שיבוא להסירו ולטלטלו.","את התירוץ הזה דוחים: \u0003לא, אידי ואידי דעבד ליה רביה\u0004 \u0005[וזה וזה\u0006 מדובר באופן \u0005שעשה לו רבו],\u0006 אלא יש להסביר את ההבדל באופן אחר; \u0003וכאן\u0004 שאסרו מדובר בחותם של \u0003מתכת, וכאן\u0004 שהתירו \u0003הרי זה בשל טיט. וכ\u0004מו שאמר \u0003רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה: דבר המקפיד עליו רבו\u0004 אם יאבד — \u0003אין יוצאים בו\u0004 בשבת, שמא יינתק מן הבגד, ומתוך פחד יטלטלנו העבד בידו. \u0003דבר שאין מקפיד עליו\u0004 האדון — \u0003יוצאין בו.\u0004","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להבין את דברי הברייתא, \u0003מדקתני\u0004 \u0005[ממה ששנינו]\u0006 שם: \u0003זה וזה אין מקבלין טומאה.\u0004 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי מדובר בחותם \u0003של מתכת\u0004 אפשר להבין את החידוש שבברייתא כך: \u0003הני הוא דלא מקבלי\u0004 \u0005[אלה הם שאינם מקבלים]\u0006 \u0003טומאה, הא\u0004 \u0005[אבל]\u0006 \u0003כלים דידהו\u0004 \u0005[שלהם,\u0006 ממינם\u0005]\u0006 — \u0003מקבלי\u0004 \u0005[מקבלים]\u0006 \u0003טומאה.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003בשל טיט תנן\u0004 \u0005[שנינו],\u0006 האם תוכל לדייק כמו כן ולומר כי \u0003הני הוא דלא מקבלי\u0004 \u0005[אלה הם שאינם מקבלים]\u0006 \u0003טומאה, הא\u0004 \u0005[אבל]\u0006 \u0003כלים דידהו מקבלי\u0004 \u0005[שלהם,\u0006 ממינם\u0005]\u0006 — \u0003מקבלי\u0004 \u0005[מקבלים]\u0006 \u0003טומאה?!\u0004","\u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כלי אבנים כלי גללים וכלי אדמה\u0004 שלא נשרפה ולא נעשתה חרס — \u0003אין מקבלין טומאה לא מדברי תורה ולא מדברי סופרים.\u0004 נמצא שאף כלי גמור העשוי טיט אינו נטמא! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבכלים \u0003של מתכת\u0004 דיברה ברייתא זו, ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","באותה ברייתא שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 ש\u0003לא\u0004 יצא העבד ב\u0003זוג שבצוארו, אבל יוצא הוא בזוג שבכסותו.\u0004","ושואלים: ב\u0003זוג שבצוארו אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יצא — מתוך החשש \u0003דילמא מיפסיק ואתא לאיתויי\u0004 \u0005[שמא ייקרע ויבוא להביאו,\u0006 לטלטלו\u0005],\u0006 אם כן, \u0003זוג שבכסותו נמי ליחוש דילמא מיפסיק ואתי לאיתויי\u0004 \u0005[גם כן נחשוש שמא ייקרע ויבוא לטלטלו]!\u0006","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דמיחא ביה מומחא\u0004 \u0005[\u0006כשהזוג \u0005ארוג בו,\u0006 בבגד\u0005].\u0006 \u0003וכ\u0004פי ששנה \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: כל שהוא ארוג\u0004 בבגד \u0003לא גזרו\u0004 לאסור יציאה בו.","בברייתא שהובאה קודם \u0003אמר מר\u0004 \u0005[החכם]\u0006 ש\u0003לא תצא בהמה לא בחותם שבצוארה, ולא בחותם שבכסותה, ולא בזוג שבצוארה, ולא בזוג שבכסותה,\u0004 ולענין טומאה \u0003זה וזה,\u0004 החותם והזוג, \u0003אין מקבלין טומאה.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מקשים\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003זוג של בהמה\u0004 — \u0003טמאה\u0004"],["\u0003של\u0004 (התלוי על) \u0003דלת\u0004 — \u0003טהור,\u0004 כי הפעמון בטל לגבי הדלת, והדלת עצמה אינה נחשבת לכלי אלא לחלק מן הבית, ולכן דינה כמותו, שמאחר והוא מחובר בקרקע אינו מקבל טומאה וכן דין כל המחובר לו.","ואם לקח זוג \u0003של דלת ועשאו לבהמה\u0004 — \u0003טמאה,\u0004 כלומר הריהו מקבל טומאה, ואילו זוג \u0003של בהמה ועשאו לדלת, אף על פי שחיברו לדלת ו\u0004אף \u0003קבעו במסמרים\u0004 — הריהו נשאר \u0003טמא,\u0004 שדינו עדיין כזוג של בהמה, \u0003שכל הכלים יורדין לידי טומאתן\u0004 להיחשב ככלים גמורים או ככלים המסוגלים לקבל טומאה \u0003במחשבה\u0004 בלבד, שעל ידי החלטה להקצותם לצורך מסויים שעל ידו יקבלו טומאה הריהם מוכשרים מיד לקבל טומאה, \u0003ואין עולים מידי טומאתן אלא בשינוי מעשה\u0004 שעושים בגוף הכלי, אבל שינוי ייעוד בלבד אינו מועיל. ולענייננו, הלא נאמר כאן שזוג בהמה מקבל טומאה בניגוד למה ששנינו בברייתא הקודמת!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהזוג טמא הרי זה באופן \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003עינבל,\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהזוג טהור הרי זה באופן \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003עינבל.\u0004","ושואלים: \u0003מה נפשך,\u0004 בכל אופן קשה הדבר, שכן \u0003אי מנא\u0004 \u0005[אם\u0006 הפעמון \u0005כלי]\u0006 \u0003הוא,\u0004 אם כן \u0003אף על פי דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003עינבל\u0004 יקבל טומאה. ומצד אחר, \u0003אי לאו מנא\u0004 \u0005[אם לא כלי]\u0006 \u0003הוא\u0004 — וכי ה\u0003עינבל משוי ליה מנא\u0004 \u0005[\u0006הוא ש\u0005עושה אותו כלי]?!\u0006","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 אכן העינבל קובע לגבי טומאת הפעמון. ו\u0003כ\u0004מו ש\u0003ר' שמואל בר נחמני אמר\u0004 בשם \u0003ר' יונתן.\u0004 ש\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: מנין ל\u0004מכשיר ה\u0003משמיע קול בכלי מתכות שהוא טמא\u0004 (מקבל טומאה) לפי שהוא נחשב לכלי — ממה \u0003שנאמר : \"כל דבר אשר יבא באש תעבירו באש\u0004 וטהר אך במי נידה יתחטא, וכל אשר לא יבוא באש תעבירו במים\u0003\"\u0004 (במדבר לא, כג). ודורשים: \"כל דבר\" — \u0003אפילו דיבור,\u0004 כלומר, כלי המשמיע קול (\"דבר\") \u0003יבא באש\u0004 לטהרו.","ואולם עדיין יש מקום לבירור, \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת\u0005]\u0006 את הברייתא — \u0003בדלית ליה\u0004 \u0005[ב\u0006זוג \u0005שאין לו]\u0006 \u0003עינבל,\u0004 אם כן \u0003אימא מציעתא\u0004 \u0005[אמור\u0006 את \u0005אמצעה\u0006 של הברייתא\u0005]\u0006 ששנינו בה: שאדם \u0003לא\u0004 יוצא \u0003בזוג שבצוארו, אבל יוצא הוא בזוג שבכסותו, ו\u0004לענין טומאה \u0003זה וזה מקבלין טומאה.\u0004 ומעתה \u0003אי דלית ליה\u0004 \u0005[אם מדובר\u0006 באופן \u0005שאין לו\u0006 \u0003עינבל מי מקבלי\u0004 \u0005האם\u0006 הוא \u0005מקבל\u0006 \u0003טומאה?\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים\u0005]\u0006 על כך ממה ששנינו בתוספתא: \u0003העושה זגין\u0004 (פעמונים) \u0003למכתשת ולעריסה ולמטפחות ספרים\u0004 שעוטפים בהם את ספרי התורה, \u0003ולמטפחות תינוקות\u0004 — כל אלה אם \u0003יש להם עינבל\u0004 — \u0003טמאין\u0004 (מקבלים טומאה), ואם \u0003אין להם עינבל\u0004 — \u0003טהורים\u0004 (אינם מקבלים טומאה). ואם לאחר שנטמאו \u0003ניטלו עינבליהן\u0004 — \u0003עדיין טומאתן עליהם.\u0004 הרי שאף בפעמוני אדם העינבל קובע אם הפעמון נחשב לכלי!","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003ב\u0004זוג של \u0003תינוק, דלקלא עבידי ליה\u0004 \u0005[שלקול עושים לו\u0006 את הפעמון\u0005],\u0006 ואם אין הפעמון משמיע קול — אין בו שימוש ואינו בר קבלת טומאה. \u0003אבל\u0004 אצל \u0003גדול\u0004 הזוג עצמו \u0003תכשיט הוא ליה\u0004 \u0005[לו]\u0006 \u0003אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לו]\u0006 \u0003עינבל.\u0004","שנינו בתוספתא ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שפעמונים שנטמאו ולאחר מכן \u0003ניטלו עינבליהן עדיין טומאתן עליהן.\u0004 ותוהים: \u0003למאי חזו\u0004 \u0005[למה ראויים\u0006 הם\u0005]\u0006 אחר שניטלו עינבליהם? והרי כשבורים הם ולכאורה נטהרים הם בכך! \u0003אמר אביי:\u0004 הטעם לכך שטומאתם בעינה עומדת, \u0003הואיל שההדיוט יכול להחזירו\u0004 לעינבל זה ולקובעו בזוג. שלדעת אביי כל כלי שנתפרק, אם יכול כל אדם (שאינו אומן) להרכיבו מחדש אינו קרוי שבור ולא בטלה טומאתו.","על הסבר זה \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו: \u0003הזוג והעינבל\u0004 הם \u0003חיבור\u0004 זה לזה;","ומכאן — שאם הפרידם שוב אינם נחשבים כמחוברים! והוא מוסיף, \u0003וכי תימא, הכי קאמר\u0004 \u0005[ואם תאמר\u0006 כי \u0005כך אמר,\u0006 נתכוון לומר\u0005]:\u0006 ש\"חיבור\" משמעו — \u0003אף על גב דלא מחבר\u0004 \u0005[אף על פי שאינו מחובר]\u0006 — \u0003כמאן דמחבר דמי\u0004 \u0005[כמו שמחובר\u0006 הוא \u0005נחשב],\u0006 ואולם הרי שנינו: \u0003מספורת\u0004 (מספריים) \u0003של פרקים\u0004 (שאפשר לפרק את להביה) \u0003ואיזמל של רהיטני\u0004 (הסכין שבמקצוע) מהווים \u0003חיבור לטומאה\u0004 כאשר הם מחוברים, \u0003ואין\u0004 הם מהווים \u0003חיבור להזאה.\u0004 שבזמן שמטהרים את הכלי מטומאת מת ומזים עליו מי חטאת (במדבר יט) יש להזות על כל חלק לעצמו.","\u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 בבירור הדבר: \u0003מה נפשך,\u0004 בכל אופן שתסביר ותאמר אין זה מובן, שכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003חיבור הוא\u0004 — ייחשב אם כן חיבור \u0003אפילו להזאה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא חיבור הוא\u0004 — \u0003אפילו לטומאה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ייחשב כחיבור!","\u0003ואמר רבה: דבר תורה\u0004 (מיסוד ההלכה האמור בתורה), \u0003בשעת מלאכה,\u0004 כששני החלקים מחוברים הרי זה נחשב כ\u0003חיבור בין לטומאה בין להזאה.\u0004 ו\u0003שלא בשעת מלאכה\u0004 — \u0003אינו\u0004 נחשב כ\u0003חיבור לא לטומאה ולא להזאה. ו\u0004אולם \u0003גזרו\u0004 חכמים להחמיר \u0003על טומאה שלא בשעת מלאכה\u0004 שייחשב הכלי כמחובר \u0003משום טומאה שהיא בשעת מלאכה. ו\u0004כן \u0003על הזאה שהיא בשעת מלאכה\u0004 שלא תועיל לכל החלקים אם הזה על חלק אחד בלבד \u0003משום הזאה שלא בשעת מלאכה,\u0004 שנחשב הכלי כמפורק. ומכל מקום למדנו שחיבור מסוג זה נחשב רק כאשר שני החלקים מחוברים בפועל, אך כשהחלקים נפרדים אפילו עשויים הם להתחבר בקלות — נחשב הכלי כשבור, ויש איפוא לדחות את הסברו של אביי.","\u0003אלא אמר רבא:\u0004 יש להסביר באופן אחר:"],["\u0003הואיל וראוי\u0004 הפעמון בלא הזוג \u0003להקישו\u0004 \u0005[להכות בו]\u0006 \u0003על גבי חרס\u0004 והוא משמיע קול כבתחילה, ואם כן, אף משניטל העינבל ממשיך הפעמון במלאכתו הראשונה ונחשב איפוא ככלי שלם.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר ר' יוסי בר' חנינא\u0004 שפעמון שניטל העינבל שלו עדיין נחשב לכלי שלם \u0003הואיל וראוי להקישו על גבי חרס.\u0004 ואילו \u0003ר' יוחנן אמר:\u0004 הפעמון אף לאחר שניטל עינבלו נחשב עדיין ככלי \u0003הואיל ו\u0004הוא עדיין \u0003ראוי לגמע בו מים לתינוק.\u0004","ולעיקר דברי ר' יוחנן שואלים: \u0003ו\u0004כי \u0003ר' יוחנן לא בעי\u0004 \u0005[אינו צריך,\u0006 אינו סבור\u0005]\u0006 שכלי שביטלוהו משימושו הראשון נשאר טמא רק כאשר עדיין עושה הוא \u0003מעין מלאכה ראשונה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \"כל המשכב אשר ישכב עליו הזב יטמא \u0003וכל\u0004 ה\u0003כלי אשר ישב עליו\u0004 יטמא\" (ויקרא טו, ד), ולכאורה \u0003יכול\u0004 שבכלל זה גם אם \u0003כפה\u0004 (הפך) כלי מידה של \u0003סאה וישב עליה,\u0004 או \u0003כפה תרקב\u0004 (חצי סאה) \u0003וישב עליה יהא\u0004 הכלי \u0003טמא\u0004 — \u0003תלמוד לומר: \"אשר ישב עליו הזב\",\u0004 והכוונה: \u0003מי שמיוחד לישיבה, יצא\u0004 כלי \u0003זה שאומרים לו\u0004 לזב: \u0003עמוד\u0004 מן הכלי \u0003ונעשה\u0004 בו \u0003מלאכתנו.\u0004","ונחלקו בכך אמוראים; \u0003ר' אלעזר אומר: במדרסות,\u0004 כלומר, בהלכות הנוגעות לזב ונידה היושבים או שוכבים על חפץ, משמש נימוק זה של הצורך בלומר \"\u0003עמוד ונעשה מלאכתנו\u0004\" כדי לטהר את הכלי. \u0003ו\u0004אולם \u0003אין אומרים בטמא מת \"עמוד ונעשה מלאכתנו\".\u0004 שחפץ שנטמא בטומאת מת ונשבר, כיון שאפשר להשתמש בו למלאכה כלשהי הריהו עדיין כלי, ומוכשר לקבל טומאה. ואילו \u0003ר' יוחנן אמר: אף אומר בטמא מת \"עמוד ונעשה מלאכתנו\",\u0004 כדי לטהר את הכלי.","הרי שלשיטתו כלי שאינו ראוי עוד למלאכתו הראשונה, אף על פי שהוא משמש לצורך אחר דינו כשבור. ואף הפעמון, כיון שאינו ראוי לצלצל עוד צריך להיות טהור לדעת ר' יוחנן, אף אם ראוי הוא עדיין לגמוע בו מים. ומשיבים: \u0003איפוך קמייתא\u0004 \u0005[הפוך את הראשונה]\u0006 שלא ר' יוחנן אמר טעם זה, אלא ר' יוסי בר' חנינא. ומקשים: \u0003ומאי חזית דאפכת קמייתא\u0004 \u0005[ומה ראית שהפכת את\u0006 המימרה \u0005הראשונה]?\u0006 \u0003איפוך בתרייתא\u0004 \u0005[הפוך\u0006 את \u0005האחרונה]\u0006 וגם אז לא תהיה סתירה בדברי ר' יוחנן!","ומשיבים: כך אכן מסתבר לומר, שכן \u0003הא שמעינן ליה\u0004 \u0005[הרי\u0006 כבר \u0005שמענו אותו]\u0006 את \u0003ר' יוחנן דבעי\u0004 \u0005[שמצריך]\u0006 כדי להשאיר את הכלי בטומאתו שיהא עדיין עושה \u0003מעין מלאכה ראשונה,\u0004 ולשיטתו הוא הולך. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סנדל של בהמה\u0004 אם הוא \u0003של מתכת\u0004 הריהו \u0003טמא\u0004 (מקבל טומאה). ושואלים: \u0003למאי חזי\u0004 \u0005[למה\u0006 הוא \u0005ראוי]?\u0006 שהרי כלי בהמה אינם מטמאים אלא אם כן יש בהם שימוש לאדם! \u0003אמר רב: ראוי\u0004 סנדל זה \u0003לשתות בו מים במלחמה\u0004 כאשר אין כלים אחרים. \u0003ור' חנינא אמר: ראוי לסוך בו שמן במלחמה. ור' יוחנן אמר: בשעה שבורח מן הקרב\u0004 הריהו \u0003מניחו ברגליו ורץ על קוצין ועל הברקנים.\u0004 שלדעתו אין לקבל נימוקים אלה, שלפיהם אין הסנדל משמש עוד למלאכתו הקבועה. ומכאן נראה שסבור ר' יוחנן שכלי נשאר טמא רק אם משמש עדיין מעין מלאכתו הראשונה.","ואגב שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 ההבדל המעשי \u0003בין\u0004 הסברו של \u0003רב ל\u0004זה של \u0003ר' חנינא?\u0004 ומשיבים: \u0003איכא בינייהו דמאיס\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה באופן \u0005ש\u0006הסנדל \u0005מאוס\u0006 ומלוכלך\u0005],\u0006 שלדעת רב כיון שאינו ראוי לשתות בו — אינו מטמא עוד. ולר' חנינא, כיון שעדיין אפשר לסוך ממנו — הריהו מטמא.","ואילו \u0003בין\u0004 הסברו של \u0003ר' יוחנן ל\u0004זה של \u0003ר' חנינא איכא בינייהו דיקיר\u0004 \u0005[יש ביניהם\u0006 הבדל מעשי באופן \u0005ש\u0006הסנדל \u0005כבד]\u0006 שאמנם ראוי הוא לסיכה, אך אינו ראוי לברוח בו, ויהא טהור לשיטת ר' יוחנן.","שנינו במשנה ש\u0003לא\u0004 תצא אשה בשבת לרשות הרבים \u0003בעיר של זהב.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"בעיר של זהב \"? רבה בר בר חנה אמר\u0004 שכך \u0003אמר ר' יוחנן\u0004 שהוא \u0003ירושלים דדהבא\u0004 \u0005[של זהב],\u0006 תכשיט זהב כעין עטרה שעליו תבנית העיר ירושלים,"],["\u0003כדעבד ליה\u0004 \u0005[כמו שעשה לה]\u0006 \u0003ר' עקיבא לדביתהו\u0004 \u0005[לאשתו].\u0006","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003לא תצא אשה בעיר של זהב. ואם יצתה\u0004 (יצאה) בו לרשות הרבים הריהי \u0003חייבת חטאת,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 מלכתחילה \u0003לא תצא\u0004 בו, \u0003ו\u0004אולם \u0003אם יצתה\u0004 — \u0003פטורה.\u0004 ו\u0003ר' אליעזר אומר: יוצאה אשה בעיר של זהב לכתחלה.\u0004","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005הם חלוקים]?\u0006 \u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 כי תכשיט זה כ\u0003משוי\u0004 (משא) \u0003הוא\u0004 נחשב ולא כתכשיט, והנושא משא ברשות הרבים חייב חטאת. \u0003ורבנן סברי\u0004 \u0005[סבורים]\u0006 כי \u0003תכשיט הוא.\u0004 ומדוע אסרוהו? — משום החשש \u0003דילמא שלפא ומחויא ליה ואתיא לאתויי\u0004 \u0005[שמא תשלוף,\u0006 תוציא את התכשיט ממקומו \u0005ותראה אותו\u0006 לחברתה \u0005ותבוא לטלטלו\u0006 ברשות הרבים\u0005].\u0006 \u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 \u0003דרכה למיפק\u0004 \u0005[לצאת]\u0006 בעיר של זהב? רק \u0003אשה חשובה, ו\u0004אם כן אין מקום לחשש זה, שכן \u0003אשה חשובה לא משלפא ומחויא\u0004 \u0005[אינה שולפת ומראה].\u0006","מאחר ודובר אודות היתר היציאה בתכשיט הנקרא עיר של זהב, מוסיפים עוד לדון בענין תכשיטים אחרים. \u0003כלילא,\u0004 שהוא תכשיט כעין עטרה, נחלקו אמוראים האם מותר לצאת בו, \u0003רב אסר\u0004 לצאת בו \u0003ושמואל שרי\u0004 \u0005[התיר].\u0006","ומגדירים את המחלוקת: בכלילא \u0003דאניסכא\u0004 \u0005[של מתכת]\u0006 \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ולדעת הכל \u0003אסור\u0004 לצאת בו. \u0003כי פליגי דארוקתא\u0004 \u0005[כאשר נחלקו\u0006 היה זה \u0005באריג\u0006 משובץ מתכת\u0005].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב האוסר, \u0005סבור]\u0006 כי בתכשיט מעין זה \u0003אניסכא\u0004 \u0005[\u0006ה\u0005מתכת]\u0006 היא ה\u0003עיקר,\u0004 ואסור. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שמואל המתיר, \u0005סבור]\u0006 כי \u0003ארוקתא\u0004 \u0005[\u0006ה\u0005אריג]\u0006 הוא ה\u0003עיקר,\u0004 ולכן יש להתיר.","\u0003רב אשי מתני לקולא\u0004 \u0005[שנה\u0006 מחלוקת זו בפירוש \u0005מיקל]\u0006 שאמר: \u0003דארוקתא כולי עלמא לא פליגי דשרי\u0004 \u0005[של אריג הכל אינם חלוקים שמותר].\u0006 \u0003כי פליגי דאניסכא\u0004 \u0005[וכאשר נחלקו\u0006 היה זה ב\u0005של מתכת].\u0006 ומחלוקתם: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב האוסר, \u0005סבור]\u0006 כי יש לחשוש \u0003דילמא שלפא ומחויא ואתיא לאתויי\u0004 \u0005[שמא תשלוף,\u0006 תוציא \u0005ותראה\u0006 אותו לחבירתה, \u0005ו\u0006בתוך כך \u0005תבוא להביאו,\u0006 לטלטלו\u0005].\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שמואל המתיר, \u0005סבור]\u0006 כי \u0003מאן\u0004 \u0005[מי]\u0006 \u0003דרכה למיפק\u0004 \u0005[לצאת]\u0006 \u0003בכלילא\u0004 — \u0003אשה חשובה, ואשה חשובה לא שלפא ומחויא\u0004 \u0005[אינה שולפת ומראה]\u0006 את הכלילא שלה.","באותו ענין \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמואל בר בר חנה לרב יוסף\u0004 שחלה ושכח תלמודו: \u0003בפירוש אמרת לן משמיה\u0004 \u0005[לנו משמו]\u0006 של \u0003רב\u0004 שבתכשיט \u0003כלילא שרי\u0004 \u0005[מותר]\u0006 לצאת בשבת.","אגב דבר זה מסופר כי יום אחד \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרב: אתא גברא רבה אריכא\u0004 \u0005[בא אדם גדול גבה קומה]\u0006 \u0003לנהרדעא ומטלע\u0004 \u0005[והוא צולע],\u0006 \u0003ודרש\u0004 כי \u0003כלילא שרי\u0004 \u0005[מותר]\u0006 לצאת בה בשבת. \u0003אמר\u0004 רב: \u0003מאן גברא רבה אריכא דאיטלע\u0004 \u0005[מי הוא אדם גבה קומה שהוא צולע]\u0006 — \u0003לוי,\u0004 ואם כן \u0003שמע מינה נח נפשיה\u0004 \u0005[למד מכך\u0006 כי \u0005נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' אפס ויתיב\u0004 \u0005[ויושב]\u0006 \u0003ר' חנינא ברישא\u0004 \u0005[בראש\u0006 הישיבה\u0005],\u0006 \u0003ולא הוה ליה איניש\u0004 \u0005[היה לו אדם]\u0006 \u0003ללוי למיתב גביה\u0004 \u0005[לשבת אצלו],\u0006 \u0003וקאתי להכא\u0004 \u0005[ובא לכאן].\u0006 כי בשעה שהיה ר' אפס בראש הישיבה, היה ר' חנינא יושב מחוץ לבית המדרש. כי כניסה לבית המדרש היתה בה קבלת מרותו של ראש הישיבה ולא רצה ר' חנינא שהיה חשוב לעשות כן. ומשום כבודו ישב לוי אתו כחבר מחוץ לבית המדרש. ומאחר שבא לוי מארץ ישראל וודאי נפטר ר' אפס, ולוי שלא רצה להיות כפוף לר' חנינא, מכיון שלא היה ר' חנינא גדול ממנו לא בשנים ולא בתורה, החליט ללכת למקום אחר, לבבל.","ושואלים: מדוע הסיק רב מסקנה זו דווקא? \u0003ודילמא נח נפשיה\u0004 \u0005[ושמא נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' חנינא, ור' אפס כדקאי קאי\u0004 \u0005[כפי שעמד\u0006 עדיין הוא \u0005עומד],\u0006 שעדיין הוא ראש הישיבה, \u0003ולא הוה ליה איניש\u0004 \u0005[היה לו אדם]\u0006 \u0003ללוי למיתב גביה\u0004 \u0005[לשבת אצלו]\u0006 מחוץ לבית המדרש, \u0003וקאתי להכא\u0004 \u0005[ובא לכאן]?\u0006 ומשיבים כי דבר זה לא יתכן, משני טעמים: ראשית \u0003אם איתא\u0004 \u0005[יש,\u0006 קרא\u0005]\u0006 אכן ש\u0003ר' חנינא\u0004 הוא ש\u0003שכיב\u0004 \u0005[נפטר]\u0006 — \u0003לוי לר' אפס מיכף הוה כייף ליה\u0004 \u0005[היה כפוף לו],\u0006 שאף מתחילה, רק מפני כבודו של ר' חנינא לא נכנס לוי לבית המדרש. \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003ר' חנינא לא סגי\u0004 \u0005[יתכן]\u0006 ש\u0003לא מליך\u0004 \u0005[ימלוך,\u0006 יעמוד בראש הישיבה\u0005],\u0006 \u0003דכי הוה קא ניחא נפשיה\u0004 \u0005[ש\u0006כן \u0005כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבי\u0004 (ר' יהודה הנשיא) \u0003אמר\u0004 בדברי צוואתו: \u0003חנינא בר' חמא יתיב\u0004 \u0005[ישב]\u0006 \u0003בראש\u0004 הישיבה. \u0003וכתיב בהו\u0004 \u0005[ונאמר בהם]\u0006 \u0003בצדיקים: \"ותגזר אמר ויקם לך\u0004 ועל דרכיך נגה אור\u0003\"\u0004 (איוב כב, כח), וכיון שיצא הדבר מפי צדיק לא יתכן שלא יתקיימו דבריו שישב ר' חנינא בראש.","ואנו חוזרים לענין \"כלילא\". כאשר \u0003דרש לוי בנהרדעא\u0004 שהתכשיט \u0003כלילא שרי\u0004 \u0005[מותר]\u0006 לצאת בו בשבת, \u0003נפיק עשרין\u0004 \u0005[יצאו עשרים]\u0006 \u0003וארבע כלילי מכולא\u0004 \u0005[\u0006נשים לבושות בתכשיט \u0005כלילא מכל]\u0006 \u0003נהרדעא.\u0004 ואילו כאשר \u0003דרש רבה בר אבוה במחוזא\u0004 כי \u0003כלילא שרי\u0004 \u0005[מותר]\u0006 \u0003נפקו תמני סרי כלילי מחדא מבואה\u0004 \u0005[שמונה עשרה\u0006 נשים לבושות בתכשיט \u0005כלילא ממבוא אחד],\u0006 שהעיר מחוזא היתה עיר מסחר עשירה, ונשים רבות היו בה בעלות תכשיטים יקרים.","\u0003אמר רב יהודה אמר רב שמואל: קמרא שרי\u0004 \u0005[חגורה מוזהבת\u0006 יקרה \u0005מותרת]\u0006 לצאת בה בשבת. \u0003איכא דאמרי דארוקתא\u0004 \u0005[יש אומרים\u0006 שהמדובר הוא בקמרא העשוי \u0005אריג\u0006 ומשובץ בזהב\u0005],\u0006 \u0003ואמר רב ספרא: מידי דהוה\u0004 \u0005[כשם שהוא\u0006 הדין\u0005]\u0006 ב\u0003טלית מוזהבת\u0004 שמותר לצאת בה בשבת.","\u0003ואיכא דאמרי דאניסכא\u0004 \u0005[ויש אומרים ש\u0006המדובר בקמרא \u0005העשויה\u0006 \u0005ממתכת],\u0006 \u0003ואמר רב ספרא: מידי דהוה\u0004 \u0005[כשם שהוא\u0006 הדין\u0005]\u0006 ב\u0003אבנט של מלכים\u0004 שעשוי כולו זהב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: קמרא עילוי המיינא מאי\u0004 \u0005[על גבי אבנט מהו]\u0006 דינו, המותר לצאת בו בשבת? \u0003אמר ליה תרי המייני קאמרת\u0004 \u0005[שתי חגורות אמרת],\u0006 וודאי אין דרכו של אדם לצאת בשתי חגורות, ואחת מהן אם כן משא הוא.","\u0003אמר רב אשי: האי רסוקא\u0004 (מעין גלימה קצרה), \u0003אי אית ליה מפרחייתא\u0004 \u0005[אם יש לה רצועות\u0006 קצרות לקושרה\u0005]\u0006 — \u0003שרי\u0004 \u0005[\u0006\u0005מותר]\u0006 לצאת בה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003אסיר\u0004 \u0005[אסור].\u0006","עוד שנינו במשנה ש\u0003לא\u0004 תצא האשה בשבת \u0003בקטלא.\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003קטלא\u0004 זו — \u0003מנקטא פארי\u0004 \u0005[\u0006כעין \u0005סינור קטן\u0006 התלוי על הצואר\u0005].\u0006 ו\u0003נזמים\u0004 ששנינו במשנה שלא תצא האשה בהם בשבת, מסבירים כי הם \u0003נזמי האף,\u0004 ולא נזמי אוזניים.","שנינו במשנה ש\u0003לא\u0004 תצא האשה בשבת \u0003בטבעת שאין עליה חותם.\u0004 ומנסים להסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 כאשר \u0003יש עליה חותם\u0004 — הריהי \u0003חייבת\u0004 חטאת. שאינה נפטרת מקרבן אלא כאשר היא יוצאת בטבעת שאין עליה חותם והיא כתכשיט, אבל טבעת שיש עליה חותם, ומשמשת בעיקר לגברים לחתום בה על מסמכים שונים נחשבת לאשה בשבת כמשאוי. \u0003אלמא לאו\u0004 \u0005[מכאן\u0006 שטבעת זו \u0005לא]\u0006 \u0003תכשיט הוא.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו במסכת כלים: \u0003תכשיטי נשים טמאים\u0004 (בני קבלת טומאה). \u0003ואלו הן תכשיטי נשים: קטלאות, נזמים וטבעות, וטבעת בין שיש עליה חותם ובין שאין עליה חותם, ונזמי האף.\u0004 והרי שאף טבעת שיש עליה חותם נחשבת כתכשיט נשים!","\u0003אמר ר' זירא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 אלא \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו בהבנת דברי המשנה שיש לחלק בין טבעת בעלת חותם לזו שאינה בעלת חותם שיטת \u0003ר' נחמיה\u0004 היא, ואילו \u0003הא\u0004 \u0005[זו]\u0006 המשנה במסכת כלים שאינה מחלקת בין הטבעות שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם היתה \u0003היא,\u0004 הטבעת, \u0003של מתכת וחותמה של אלמוג\u0004 — \u0003טמאה\u0004 (מקבלת טומאה). משום שעיקר החפץ הוא גוף הטבעת, והוא עשוי מתכת המקבלת טומאה. ואולם, אם \u0003היא של אלמוג וחותמה של מתכת\u0004 — \u0003טהורה\u0004 (אינה מקבלת טומאה). ואילו \u0003ר' נחמיה מטמא, שהיה ר' נחמיה אומר: בטבעת הלך\u0004 (לך) \u0003אחר חותמה,\u0004 ואם החותם עשוי מחומר המקבל טומאה — טמא, ואם מחומר שאינו מקבל טומאה — טהור. וכן \u0003בעול הלך אחר סמלוניו,\u0004 שהם כעין מסמרים ששמים בו להדקו ולפי החומר שממנו עשויים הסמלונים דנים אם העול כולו טמא."],["\u0003בקולב הלך\u0004 (לך) \u0003אחר מסמרותיו,\u0004 שבהם תולים את החפצים. \u0003בסולם הלך אחר שליבותיו, בערסא\u0004 (מאזניים גדולות) \u0003הלך אחר שלשלותיו\u0004 ולא לפי כפות המאזניים. \u0003וחכמים אומרים:\u0004 בכל הכלים \u0003הכל הולך אחר המעמיד,\u0004 שאין אנו דנים לפי החלק החשוב מבחינת התפקיד, אלא לפי עיקר מבנהו של הכלי. ואם כן, לדעת ר' נחמיה יש לחלק, אף בדיני שבת, בין טבעת שיש בה חותם ושאין בה חותם, שהרי לדעתו החותם הוא עיקרה של הטבעת. וחכמים הסבורים, לדיני טומאה, שעיקרה של הטבעת הוא גופה ולא חותמה, מתירים משום כך בשבת אף בטבעת שיש עליה חותם.","\u0003רבא אמר:\u0004 אפשר לתרץ את הסתירה בצורה אחרת, והמשנה בדיני טומאה יש להבינה כי \u0003לצדדים קתני,\u0004 וכל קטע בה מתייחס לצד (ענין) אחר. וכך יש להבינה: טבעת ש\u0003יש עליה חותם\u0004 — הריהי \u0003תכשיט\u0004 של \u0003איש, אין עליה חותם\u0004 — הריהי \u0003תכשיט\u0004 של \u0003אשה.\u0004","ו\u0003רב נחמן בר יצחק אמר\u0004 ליישב את הסתירה בין המשניות בדרך זו: וכי מהלכות \u0003טומאה\u0004 על הלכות \u0003שבת קרמית\u0004 \u0005[\u0006\u0005מקשה אתה]?!\u0006 והלא העקרונות היסודיים שבדינים אלה אינם דומים כלל, שכן ב\u0003טומאה \"\u0004כל \u0003כלי מעשה\"\u0004 (במדבר לא, נא) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ו\u0004לכן טבעת שיש עליה חותם \u0003כלי הוא,\u0004 ומקבלת טומאה. ואילו ב\u0003שבת משום משוי\u0004 (משא) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שיש לחשוש, ולכן כש\u0003אין עליה חותם\u0004 — הריהי \u0003תכשיט,\u0004 ומותרת בטלטול, \u0003יש עליה חותם\u0004 — הריהי \u0003משוי ,\u0004 ואסור.","שנינו במשנה ש\u0003לא\u0004 תצא האשה בשבת \u0003במחט שאינה נקובה.\u0004 ושואלים: \u0003למאי חזיא\u0004 \u0005[למה ראויה]\u0006 כקישוט מחט כזו? \u0003אמר רב יוסף: הואיל ואשה אוגרת\u0004 (אוספת) \u0003בה\u0004 את \u0003שערה,\u0004 שהיא מכניסה סיכה זו בתוך שערותיה ומצמידה אותן על ידי כך אל הסבכה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אם כן \u0003ותהוי\u0004 \u0005[תהא]\u0006 מחט זו \u0003כבירית טהורה, ותשתרי\u0004 \u0005[ותותר].\u0006 שבין הביריות השונות יש סוג בירית שאינו מקבל טומאה, והוא בירית העשויה כרצועה המחזיקה את הגרב שלא תפול, ומותר לצאת בה בשבת, אפילו היתה מקושטת, שמפני הצניעות ודאי לא תבוא אשה להראות או להסיר את הבירית ברשות הרבים. ואף במחט זו התחובה בסבכה — אין להניח שתפרע אשה את שערה ברחוב.","\u0003אלא תרגמא\u0004 \u0005[הסביר\u0006 אותה\u0005]\u0006 \u0003רב אדא נרשאה קמיה\u0004 \u0005[מ\u0006העיר \u0005נרש לפני]\u0006 \u0003רב יוסף: הואיל ואשה חולקת בה שערה,\u0004 שעושה בשערותיה כעין שביל על ידי מחט זו. ומקשים: \u0003בשבת\u0004 שאסור לסרוק את השערות \u0003למאי חזיא\u0004 \u0005[למה ראויה]\u0006 מחט זו? \u0003אמר רבא: טס של זהב יש לה על ראשה,\u0004 ובקצהו מחט זו, \u0003בחול חולקת בה שערה,\u0004 ואילו \u0003בשבת\u0004 מכניסה את המחט בכיסוי ראשה, והחלק המקושט \u0003מניחתה כנגד פדחתה\u0004 (מצחה) כשאר תכשיטים.","\u0003לא יצא האיש\u0004 בשבת \u0003בסנדל המסומר\u0004 (שיש לו מסמרים בסוליותיו) כאשר יבואר טעמו של דבר בגמרא. \u0003ולא\u0004 יצא בסנדל \u0003יחיד, בזמן שאין ברגלו מכה\u0004 (פצע). \u0003ולא\u0004 יצא \u0003בתפילין, ולא בקמיע בזמן שאינו מן המומחה,\u0004 שהקמיע נכתב בידי מי שאין ידוע עדיין אם מומחה הוא לכתוב קמיעות המועילים לנושא אותן. \u0003ו\u0004כן לא יצא \u0003לא בשריון ולא בקסדא ולא במגפיים. ואם יצא\u0004 בכל אלה — \u0003אינו חייב חטאת.\u0004","ושואלים: \u0003סנדל המסומר מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסרו לצאת בו בשבת?","\u0003אמר שמואל:\u0004 אנשים \u0003שלפי\u0004 \u0005[נשלפים,\u0006 נשמטים\u0005]\u0006 מן ה\u0003גזירה\u0004 (גזירת השמד) \u0003היו\u0004 לאחר אחת המלחמות באותם ימים, \u0003והיו\u0004 אנשים אלו \u0003נחבאין במערה, ואמרו\u0004 הנחבאים: \u0003הנכנס\u0004 למערה — \u0003יכנס, והיוצא\u0004 ממנה — \u0003אל יצא.\u0004 שאין היוצא יודע אם אורבים מבחוץ ויכול בכך להסגיר את כל יושבי המערה.","ואירע ש\u0003נהפך סנדלו של אחד מהם\u0004 כשצדו הקדמי מאחור, ונראו עקבותיו כפסיעות יוצאות מן המערה, ו\u0003כסבורין הם\u0004 ש\u0003אחד מהן יצא וראוהו\u0004 ה\u0003אויבים ועכשיו באין עליהן. דחקו זה בזה והרגו זה את זה יותר ממה שהרגו בהם אויבים.\u0004 ולזכר אותו אסון שאירע בגלל סנדל מסומר אסרו לצאת בו.","\u0003ר' אילעאי בן אלעזר אומר\u0004 שסיבת הגזירה היתה אחרת, ולדעתו מקור הגזירה היה בכך שפעם אחת \u0003במערה היו יושבין\u0004 אותם \u0003אנשים ושמעו קול\u0004 סנדל המסומר \u0003מעל גבי המערה, כסבורין היו שבאו עליהם אויבים, דחקו זה בזה והרגו זה את זה יותר ממה שהרגו בהן אויבים.\u0004","\u0003רמי בר יחזקאל אמר,\u0004 טעם הגזירה היה שונה, והוא: \u0003בבית הכנסת היו יושבים\u0004 אנשים אלו \u0003ושמעו קול\u0004 סנדל מסומר \u0003מאחורי בית הכנסת, כסבורין היו שבאו עליהם אויבים. דחקו זה בזה והרגו זה את זה יותר ממה שהרגו בהן אויבים.\u0004","ולזכר אותו אסון שאירע בגלל סנדל מסומר \u0003באותה שעה אמרו: אל יצא אדם בסנדל המסומר.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ב\u0004ימות ה\u0003חול נמי ליתסר\u0004 \u0005[גם כן ייאסר]\u0006 לנעול סנדל מסומר! ומשיבים: \u0003מעשה\u0004 זה \u0003כי הוה\u0004 \u0005[כאשר היה]\u0006 — \u0003בשבת הוה\u0004 \u0005[\u0006הוא ש\u0005היה]\u0006 ולכך גזרו איסור רק מעין המאורע, בשבת. ומקשים: אם כן \u0003ביום טוב לישתרי\u0004 \u0005[יותר]\u0006 לנעול סנדל מסומר! \u0003אלמה תנן\u0004 \u0005[מדוע שנינו ב\u0006אותה \u0005משנה]:\u0006"],["\u0003משלחין\u0004 כמתנה \u0003כלים ביום טוב בין תפורין\u0004 ו\u0003בין שאינן תפורין,\u0004 שדבר הראוי לשימוש כלשהו בחג — מותר לשלחו במתנה, \u0003אבל לא סנדל המסומר ולא מנעל שאינו תפור (ביום טוב) בשבת,\u0004 שאסור להשתמש בהם. ומכאן נלמד שסנדל המסומר אסור בלבישה ביום טוב!","ומסבירים: \u0003בשבת מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסרו — משום \u0003דאיכא כינופיא\u0004 \u0005[שיש התכנסות\u0006 קהל\u0005],\u0006 \u0003ביום טוב נמי איכא כינופיא\u0004 \u0005[גם כן יש התכנסות].\u0006 ומקשים: ב\u0003תענית ציבור\u0004 הרי גם כן \u0003איכא כינופיא\u0004 \u0005[יש התכנסו]\u0006 ואם כן גם בה \u0003ליתסר\u0004 \u0005[ייאסר]\u0006 הסנדל המסומר בנעילה. ומשיבים: ה\u0003מעשה\u0004 שבגללו אסרו \u0003כי הוה בכינופיא דאיסורא\u0004 \u0005[כאשר היה,\u0006 היה זה \u0005בהתכנסות של איסור],\u0006 ביום שנאסר בעשיית מלאכה, \u0003הכא כינופיא דהתירא\u0004 \u0005[כאן\u0006 בתענית \u0005התקהלות של היתר]\u0006 היא, שיום שמותר בעשיית מלאכה הוא, ואינו דומה כלל. והרחבה מסויימת (כמו משבת ליום טוב) של גזירות שנעשו לזכרון מקובלת היא.","\u0003ואפילו ל\u0004שיטת \u0003ר' חנינא בן עקיבא\u0004 שגזירה שגזרו מחמת מאורע מסויים שאירע לא גזרו אלא בנסיבות הדומות לאותו מאורע, שהוא \u0003אמר\u0004 בענין אחר ש\u0003לא אסרו אלא בירדן ובספינה וכמעשה שהיה.\u0004 שפעם העבירו אפר פרה אדומה אל מעבר לירדן בספינה, והתברר שהיתה טומאה בקרקעית הספינה, ורצו חכמים לגזור שלא להעביר כלל אפר פרה אדומה מעל מקור מים, ים או נהר, מעל גשר או באמצעות ספינה. ור' חנינא בן עקיבא אמר שגזירות שנוצרו לזכר מאורע אין גוזרים אלא בדיוק כשם שהיה המעשה בשעתו ולכן לא גזרו אלא בירדן ובספינה. אולם גם לשיטה מצמצמת זו \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003ירדן\u0004 לעומת נהרות אחרים מכיון \u0003דשאני\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 \u0003משאר נהרות\u0004 בכמה \u0005דברים, רוחב או עומק,\u0006 \u0003אבל יום טוב ושבת כי הדדי נינהו\u0004 \u0005[זה כמו זה הם],\u0006 \u0003דתנן\u0004 \u0005[\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין בין יום טוב לשבת\u0004 הבדל בהלכה \u0003אלא\u0004 היתר הכנת \u0003אוכל נפש בלבד\u0004 ביום טוב.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: לא שנו\u0004 שסנדל המסומר יהא אסור \u0003אלא\u0004 כאשר קבעו בו את המסמרים כדי \u0003לחזק\u0004 את מבנהו, \u0003אבל\u0004 אם קבעום \u0003לנוי\u0004 — \u0003מותר.\u0004 ושואלים: \u0003וכמה\u0004 מסמרים נחשבים \u0003לנוי? ר' יוחנן אמר: חמש ב\u0004סנדל \u0003זה וחמש בזה. ור' חנינא אמר: שבע בזה ושבע בזה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לרב שמן בר אבא: אסברא\u0004 \u0005[אסביר]\u0006 \u0003לך: לדידי\u0004 \u0005[לשיטתי]\u0006 נועצים בסנדל זה לנוי \u0003שתים מכאן\u0004 מצידו החיצוני, אחד סמוך לאצבעותיו ואחד סמוך לעקבו, \u0003ושתים מכאן,\u0004 מצידו הפנימי אחד סמוך לאצבעותיו ואחד סמוך לעקבו, \u0003ואחת בתרסיותיו\u0004 (רצועותיו), ו\u0003לר' חנינא שלוש מכאן ושלוש מכאן ואחת בתרסיותיו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003סנדל הנוטה\u0004 (שאין סולייתו ישרה) \u0003עושה לו שבע\u0004 מסמרים בתחתיתו לישרו, ומותר בשבת, אלו \u0003דברי ר' נתן. ורבי מתיר\u0004 אף \u0003בשלוש עשרה.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' חנינא הוא\u0004 ש\u0003אמר\u0004 דבריו \u0003כר' נתן. אלא\u0004 ל\u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 דבריו, \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אמרם? והרי שני התנאים אינם מסכימים לשיטתו! ומשיבים: \u0003הוא\u0004 ש\u0003אומר\u0004 דבריו \u0003כ\u0004שיטת \u0003ר' נהוראי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' נהוראי אמר:\u0004 אם \u0003חמש\u0004 מסמרים קבועים בסנדל \u0003מותר\u0004 לצאת בו בשבת, \u0003ו\u0004אולם אם קבועים בו \u0003שבע\u0004 מסמרים — \u0003אסור\u0004 לצאת בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 החכם \u0003איפה לרבה בר בר חנה: אתון\u0004 \u0005[אתם]\u0006 \u0003תלמידי ר' יוחנן עבידו\u0004 \u0005[עשו]\u0006 \u0003כ\u0004שיטת \u0003ר' יוחנן, אנן נעביד\u0004 \u0005[אנחנו נעשה]\u0006 \u0003כ\u0004שיטת \u0003ר' חנינא.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב הונא מרב אשי: חמש\u0004 מסמרים הקבועים בסנדל \u0003מהו\u0004 לצאת בו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו שבע מותר.\u0004 שאלו עוד: \u0003תשע\u0004 מהו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו שמונה אסור.\u0004","\u0003בעא מיניה ההוא רצענא\u0004 \u0005[שאל רצען אחד]\u0006 \u0003מר' אמי:\u0004 אם \u0003תפרו\u0004 לאותו סנדל \u0003מבפנים\u0004 בעור — \u0003מהו\u0004 לקבוע בו מסמרים ויוכלו לצאת בו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: \u0003מותר, ולא ידענא מאי טעמא\u0004 \u0005[ו\u0006אולם \u0005איני יודע מה טעם]\u0006 הדבר.","\u0003אמר רב אשי: ולא ידע מר מאי טעמא\u0004 \u0005[ו\u0006כי \u0005אין אדוני יודע מה טעם]?\u0006 והלא פשוט הוא! \u0003כיון\u0004 ש\u0003תפרו מבפנים הוי ליה\u0004 \u0005[הרי הוא\u0006 נעשה\u0005]\u0006 בכך \u0003מנעל\u0004 ויוצא מכלל סנדל, ו\u0003בסנדל גזרו ביה רבנן\u0004 \u0005[גזרו בו חכמים]\u0006 איסור, ואילו \u0003במנעל לא גזרו ביה רבנן\u0004 \u0005[גזרו בו חכמים].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' אבא בר זבדא מר' אבא בר אבינא:\u0004 אם \u0003עשאו\u0004 לאותו סנדל \u0003כמין כלבוס\u0004 שתקע בו מסמרים עקומים, המחודדים משני קצותיהם, ואמצע המסמר בולט כלפי חוץ, \u0003מהו\u0004 הדין בכגון זה, האם מותר לצאת בו בשבת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מותר.\u0004 ו\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר ר' יוסי בר' חנינא: עשאו כמין כלבוס\u0004 — \u0003מותר.\u0004","\u0003אמר רב ששת:\u0004 סנדל ש\u0003חיפהו\u0004 \u0005[כיסהו]\u0006 \u0003כולו במסמרות כדי שלא תהא קרקע אוכלתו\u0004 (משפשפת אותו) — \u0003מותר\u0004 לצאת בו בשבת, שנעשה ככלי אחר, ואינו סנדל המסומר שגזרו בו.","ואכן \u0003תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב ששת: לא יצא האיש בסנדל המסומר ולא יטייל\u0004 בו אפילו \u0003מבית לבית\u0004 בחצרו, ו\u0003אפילו\u0004 לא \u0003ממטה למטה\u0004 בביתו. \u0003אבל\u0004 כיון שהאיסור הוא משם זכרון למעשה שהיה בלבד, אינו אלא כפי שהיה באותו מעשה ואינו אלא על נעילת הסנדל, ולכן \u0003מטלטלין אותו לכסות בו את הכלי ולסמוך בו\u0004 את \u0003כרעי המטה. ור' אלעזר בר' שמעון אוסר\u0004 אף בשימוש אחר. \u0003נשרו\u0004 ה\u0003רוב\u0004 מ\u0003מסמרותיו ונשתייר בו\u0004 רק \u0003ארבע\u0004 או \u0003חמש\u0004 — \u0003מותר\u0004 לצאת בו. \u0003ורבי מתיר\u0004 לצאת בו אם נשארו בו \u0003עד שבעה\u0004 מסמרים. ואם \u0003חיפהו בעור מלמטה\u0004 תחת העץ \u0003וקבע לו מסמרות מלמעלה\u0004 — \u0003מותר. עשאו\u0004 את המסמר \u0003כמין כלבוס, או\u0004 שעשאו \u0003כמין טס\u0004 שטוח מאד בקצהו \u0003או\u0004 חד \u0003כמין יתד, או שחיפהו כולו במסמרות כדי שלא תהא קרקע אוכלתו\u0004 — \u0003מותר\u0004 לצאת בו.","וכיון שהובאה ברייתא זו דנים בה לגופה; \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה]\u0006 שכן מצד אחד \u0003אמרת\u0004 שאם \u0003נשרו רוב מסמרותיו\u0004 — מותר, ומכאן שהוא הדין \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003נשתיירו ביה טובא\u0004 \u0005[בו הרבה],\u0006 \u0003והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 \u0003ארבע או חמש,\u0004 ומשמע כי רק ארבע או חמש — \u0003אין\u0004 \u0005[כן],\u0006 מותר לצאת בו, ואולם \u0003טפי\u0004 \u0005[יותר]\u0006 — \u0003לא,\u0004 בלא לדקדק מה היה מספר המסמרים קודם לכן!","\u0003אמר רב ששת: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 ויש ליישב באופן זה: \u0003כאן\u0004 שהתירו בנפילת רובן הרי זה באופן \u0003שנגממו,\u0004 שרק ראשי המסמרים נקטעו ועדיין רוב המסמר נעוץ, ורואים שרובם נפלו. \u0003כאן\u0004 שהתירו רק בארבעה ובחמשה \u0003הרי זה באופן שנעקרו\u0004","ואין רואין אלא את המסמרים המצויים בנעל. ועוד מדקדקים בלשון התוספתא: שנינו בה שאם נשרו רוב מסמרי הסנדל ונותרו בו \u0003ארבע או חמש\u0004 מסמרים — \u0003מותר\u0004 לצאת בו. ומקשים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 אם אמרת שכאשר נותרו \u0003חמש\u0004 מסמרים \u0003שרי\u0004 \u0005[מותר]\u0006 לצאת בו, \u0003ארבע מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]?!\u0006 ומשיבים: \u0003אמר רב חסדא, ארבע\u0004 שאמרו הריהן \u0003מסנדל קטן, וחמש מסנדל גדול,\u0004 ולכל אחד מהם דין המיוחד לו.","שנינו באותה תוספתא ש\u0003רבי מתיר עד שבע.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 שבסנדל הנוטה \u0003רבי מתיר\u0004 אם יש בו \u0003עד שלש עשרה\u0004 מסמרים! ומשיבים: \u0003נוטה שאני\u0004 \u0005[שונה],\u0006 שמכיון שאין המסמרים אלא ליישור הסנדל, אינו נידון כסנדל המסומר.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן]\u0006 וחדשת הסבר שסנדל נוטה דינו שונה, \u0003לר' יוחנן\u0004 שקבע בניגוד לדעת שיטות התנאים שמספר המסמרים הוא חמש בסנדל זה וחמש בסנדל זה, כפי ששנינו מקודם, \u0003נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 כי \u0003נוטה שאני\u0004 \u0005[שונה]\u0006 אבל בשאינו נוטה אף לדעתו לא הותר כל כך.","\u0003אמר רב מתנה ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב אחדבוי בר מתנה\u0004 שכך \u0003אמר רב מתנה: אין הלכה כר' אלעזר בר' שמעון\u0004 האוסר את הסנדל המסומר בכל טלטול. ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 והלא כלל הוא שבכל מחלוקת שנחלקו בה \u0003יחיד ורבים הלכה כרבים,\u0004 ודעתו בתוספתא היא דעת יחיד בלבד! ומשיבים: \u0003מהו דתימא מסתברא טעמא\u0004 \u0005[מהו שתאמר\u0006 כי \u0005מסתבר הטעם]\u0006 של \u0003ר' אלעזר בר' שמעון בהא\u0004 \u0005[בזה]\u0006 ויפסקו כמותו אף שהוא יחיד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הלכה כן.","\u0003אמר ר' חייא: אי לאו דקרו\u0004 \u0005[אם לא ש\u0006היו \u0005קוראים]\u0006 \u0003לי \"בבלאי שרי איסורי\"\u0004 \u0005[בבלי מתיר]\u0006 \u0003שרינא ביה טובא\u0004 \u0005[הייתי מתיר בו,\u0006 באותו סנדל \u0005הרבה].\u0006 ושואלים: \u0003וכמה\u0004 היה מתיר? \u0003בפומבדיתא אמרין\u0004 \u0005[אמרו]:\u0006 \u0003עשרים וארבע\u0004 מסמרים. \u0003בסורא אמרין\u0004 \u0005[אמרו]:\u0006 \u0003עשרין ותרתין\u0004 \u0005[עשרים ושנים].\u0006 \u0003אמר רב נחמן בר יצחק: וסימניך\u0004 \u0005[וסימן\u0006 יהיה \u0005לך]\u0006 כדי שתזכור מה אמרו בסורא ומה אמרו בפומבדיתא: \u0003עד דאתא\u0004 \u0005[שבא]\u0006 \u0003מפומבדיתא לסורא חסר תרתי\u0004 \u0005[שני\u0006 מסמרים\u0005]\u0006 ממנעלו. כי הדרך מפומבדיתא לארץ ישראל עוברת את סורא, והרי זה סימן לזכרון, שבטורח הדרך נפלו מ\"סנדלו של ר' חייא\" שני מסמרים.","שנינו במשנה ש\u0003לא\u0004 יוצאים בשבת \u0003ב\u0004סנדל \u0003יחיד בזמן שאין ברגלו מכה.\u0004"],["\u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש ברגלו מכה\u0004 — \u0003נפיק\u0004 \u0005[יוצא]\u0006 בסנדל אחד. ואם כן: \u0003בהי מינייהו נפיק\u0004 \u0005[באיזה מהם,\u0006 מן הסנדלים, \u0005יוצא]?\u0006 \u0003אמר רב הונא: ב\u0004סנדל הנעול על \u0003אותה\u0004 רגל \u0003שיש בה מכה. אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]\u0006 כי \u0003סנדל לשום\u0004 (לשם) \u0003צער עביד\u0004 \u0005[\u0006הוא \u0005עשוי],\u0006 שכרגיל הולך אדם בסנדל רק כדי למנוע מעצמו את כאב ההליכה על אבנים וכדומה, וכשרואים שהוא נעול סנדל אחד מבינים שאינו חש לכאב זה, ורק משום פצע שברגלו נעל סנדל זה, ורגלו האחרת יחפה כדרכו, ואין חושדים אותו שהוא נועל.","\u0003וחייא בר רב אמר: באותה שאין בה מכה\u0004 נועל את אותו סנדל יחיד. \u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]\u0006 כי סנדל \u0003לשום תענוג עביד\u0004 \u0005[\u0006הוא \u0005עשוי],\u0006 ואותו הוא נועל ברגל הבריאה, \u0003ו\u0004רגל \u0003זו שיש בה מכה, מכתה מוכחת עליה\u0004 שאינו יכול לנעול סנדל על גבי אותה רגל, והשאיר אותו סנדל בביתו, ואין הדבר נראה משונה.","ומעירים: \u0003ואף ר' יוחנן סבר להא\u0004 \u0005[סבור כ\u0006הלכה \u0005זו]\u0006 של \u0003רב הונא\u0004 שאין נועלים סנדל אלא משום צער. ודבר זה נלמד ממעשה \u0003שאמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לרב שמן בר אבא\u0004 שמשו: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 את \u0003מסנאי\u0004 \u0005[נעלי].\u0006 \u0003יהב ליה\u0004 \u0005[נתן לו]\u0006 את הנעל של רגל \u0003ימין. אמר ליה\u0004 \u0005[לו]\u0006 \u0003עשיתו\u0004 לרגל זו כאילו יש בה \u0003מכה.\u0004 שלדעת ר' יוחנן יש לנעול נעל שמאל תחילה, והנועל נעל ימין בראשונה שוב אינו נועל של שמאל אחריה, ואם כן יצטרך ללכת בנעל אחת, ויחשבו שהוא פצוע באותה רגל, וכדברי רב הונא שעל הרגל בה המכה הוא נועל את הסנדל.","ודוחים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003כ\u0004שיטת \u0003חייא בר רב סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שנועלים על הרגל הבריאה, \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003עשית\u0004 רגל \u0003של שמאל\u0004 שאינו נועל בה כאילו היתה בה \u0003מכה.\u0004 ואם כן אין להוכיח מדברי ר' יוחנן בזה.","\u0003ו\u0004לגוף דברי ר' יוחנן, \u0003אזדא\u0004 \u0005[הולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003אמר ר' יוחנן: כ\u0004דרך הנחת \u0003תפילין כך\u0004 דרך נעילת \u0003מנעלין. מה תפילין\u0004 מניח \u0003ב\u0004יד \u0003שמאל, אף מנעלין\u0004 מתחיל \u0003ב\u0004רגל \u0003שמאל.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003כשהוא נועל\u0004 מנעליו — \u0003נועל של ימין\u0004 תחילה \u0003ואחר כך נועל של שמאל!\u0004","\u0003אמר רב יוסף: השתא דתניא הכי\u0004 \u0005[עכשיון ששנויה\u0006 ברייתא \u0005כך],\u0006 \u0003ואמר ר' יוחנן הכי\u0004 \u0005[כך],\u0006 \u0003דעבד הכי\u0004 \u0005[\u0006מי \u0005שעשה\u0006 כך] — \u0003עבד\u0004 \u0005[עשה],\u0006 \u0003ודעבד הכי\u0004 \u0005[ו\u0006מי \u0005שעשה כך]\u0006 — \u0003עבד\u0004 \u0005[עשה],\u0006 שלכל מנהג יש סימוכין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 מדוע נקבל בוודאות את ההנחה שר' יוחנן חלוק על הברייתא, ואחר שכן אין להכריע בדבר? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003ר' יוחנן הא מתניתא לא הוה שמיע ליה, ואי הוה שמיע ליה הוה הדר ביה\u0004 \u0005[ברייתא זו לא שמע,\u0006 ידע \u0005ממנה, ואילו היה שומע ממנה היה חוזר בו].\u0006 \u0003ואי נמי שמיע ליה\u0004 \u0005[ואם גם כן\u0006 יכול אתה לומר \u0005ששמע ממנה]\u0006 \u0003וקסבר\u0004 \u0005[\u0006אולם \u0005הוא סבור]\u0006 ש\u0003אין הלכה כאותה משנה,\u0004 ובכל אופן ראוי להכריע בין השיטות.","\u0003אמר רב נחמן בר יצחק:\u0004 ו\u0003ירא שמים יוצא ידי שתיהן\u0004 (שתי השיטות) (יעב\"ץ). \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 ירא שמים זה? — \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא. היכי עביד\u0004 \u0005[איך\u0006 הוא \u0005עושה]?\u0006 — \u0003סיים דימיניה ולא קטר\u0004 \u0005[נועל\u0006 את \u0005של\u0006 רגל \u0005ימינו ואינו קושר]\u0006 את השרוכים, \u0003וסיים דשמאליה וקטר\u0004 \u0005[ונעל\u0006 את \u0005של שמאלו, וקושר],\u0006 \u0003והדר קטר דימיניה\u0004 \u0005[וחוזר\u0006 אחר כך ו\u0005קושר\u0006 את \u0005של ימינו].\u0006 \u0003אמר רב אשי: חזינא\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רב כהנא\u0004 ש\u0003לא קפיד\u0004 \u0005[\u0006היה \u0005מקפיד]\u0006 בסדר נעילת נעליים.","כיון שהובא קטע זה מהלכות דרך ארץ מביאים את הענין כולו: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשהוא נועל\u0004 את נעליו הריהו \u0003נועל\u0004 את \u0003של ימין\u0004 תחילה \u0003ואחר כך נועל\u0004 את \u0003של שמאל,\u0004 שהימין חשובה לכל דבר. ו\u0003כשהוא חולץ\u0004 — \u0003חולץ\u0004 את \u0003של שמאל ואחר כך חולץ\u0004 את \u0003של ימין,\u0004 כדי שתשאר הרגל הימנית נעולה.","וכן \u0003כשהוא רוחץ\u0004 את רגליו הריהו \u0003רוחץ\u0004 את \u0003של ימין\u0004 תחילה \u0003ואחר כך רוחץ\u0004 את \u0003של שמאל. כשהוא סך\u0004 — \u0003סך של ימין ואחר כך של שמאל. והרוצה לסוך\u0004 את \u0003כל גופו\u0004 — \u0003סך\u0004 את \u0003ראשו תחילה מפני שהוא מלך\u0004 (חשוב) \u0003על כל איבריו\u0004 האחרים של האדם.","שנינו במשנה ש\u0003לא\u0004 יצא האיש בשבת \u0003בתפילין. אמר רב ספרא : לא תימא\u0004 \u0005[אל תאמר]\u0006 שדבר זה הוא רק \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטת מי שאומר]\u0006 ש\u0003שבת לאו\u0004 \u0005[לא]\u0006 \u0003זמן תפילין הוא,\u0004 שאסור להניח בה תפילין, ולכך גם אסור לצאת בהם. \u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 ש\u0003שבת זמן תפילין הוא\u0004 — \u0003לא יצא\u0004 בהם, וזאת משום החשש \u0003דילמא אתי לאיתויי\u0004 \u0005[שמא יבוא להביא]\u0006 אותם בידו \u0003ברשות הרבים,\u0004 ובכך הוא נושא משא בשבת ועובר על דברי תורה.","\u0003ואיכא למתני לה אסיפא\u0004 \u0005[ויש\u0006 מי \u0005ששונה אותה,\u0006 את הערת רב ספרא, \u0005על סופה\u0006 של הפיסקה\u0005],\u0006 כך: \u0003ואם יצא\u0004 בתפילין \u0003אינו חייב חטאת.\u0004 ועל כך \u0003אמר רב ספרא: לא תימא\u0004 \u0005[אל תאמר]\u0006 שדבר זה הוא רק \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטת מי שאומר]\u0006 ש\u0003שבת זמן תפילין הוא,\u0004 ולכך אם הוציאם אינו עובר בכך על איסור תורה ואינו מתחייב בכך חטאת, \u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 ש\u0003שבת לאו\u0004 \u0005[לא]\u0006 \u0003זמן תפילין הוא\u0004 — \u0003אינו חייב חטאת,\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 פטור? — כי \u0003דרך מלבוש עבידא\u0004 \u0005[עשוייה]\u0006 הנחת התפילין, והלובש בגד או תכשיט בשבת, אף שאסור להשתמש בו בשבת, מכל מקום איסור טילטול מן התורה אין בכך.","שנינו במשנה ש\u0003לא\u0004 יצא אדם \u0003בקמיע בזמן שאינו מן המומחה. אמר רב פפא: לא תימא\u0004 \u0005[אל תאמר]\u0006 שהכוונה היא שאינו יוצא בקמיע אלא \u0003עד\u0004 ש\u0003מומחה גברא\u0004 \u0005[האיש]\u0006 שכותב אותו, \u0003ו\u0004גם \u0003מומחה\u0004 ה\u0003קמיע,\u0004 שנבדק ונמצא שהוא מועיל, \u0003אלא כיון\u0004 ש\u0003מומחה גברא\u0004 \u0005[האיש]\u0006 הכותב אותו\u0003, אף על גב\u0004 \u0005[אף על\u0006 פי] ש\u0003לא מומחה\u0004 ה\u0003קמיע\u0004 יכול הוא לצאת אתו.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר מלשון המשנה, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 במשנתנו: \u0003\"ולא בקמיע בזמן שאינו מן המומחה\", ולא קתני\u0004 \u0005[שנינו]\u0006 \u0003\"בזמן\u0004 שהקמיע עצמו \u0003אינו מומחה\",\u0004 ומכאן שדי שיתמחה כותב הקמיעות ואין צורך בהוכחת תועלתו של הקמיע עצמו. ומעירים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003איזהו קמיע מומחה\u0004 — \u0003כל שריפא\u0004 אדם אחד פעם אחת, \u0003ושנה, ושלש. אחד קמיע של כתב, ואחד קמיע של עיקרין\u0004 (שורשי צמחים לסגולה). \u0003אחד\u0004 הוא אם נבדק \u0003בענין ריפוי חולה שיש בו סכנה, ואחד\u0004 ב\u0003חולה שאין בו סכנה,\u0004 שבכל זה מותר לאדם לצאת בשבת בו.","ו\u0003לא\u0004 הותר דווקא בקמיע \u0003ש\u0004כבר \u0003נכפה\u0004 (חלה במחלת הנפילה) והוא נוטל את הקמע אתו כדי להצילו מנפילה נוספת, \u0003אלא\u0004 אפילו אם מעולם לא נפל ורק דואג \u0003שלא יכפה\u0004 (יחלה במחלה זו), מותר לו לצאת עמו.","ואף \u0003קושר ומתיר\u0004 אותו \u0003ואפילו ברשות הרבים. ובלבד שלא יקשרנו\u0004"],["\u0003בשיר ובטבעת ויצא בו ברשות הרבים.\u0004 וטעם האיסור: \u0003משום מראית העין,\u0004 שנראה כתכשיט בלבד האסור בטלטול.","על מה ששנינו בהגדרת קמיע מומחה שהוא זה שריפא אדם אחד שלוש פעמים, מקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו קמיע מומחה\u0004 — \u0003כל שריפא שלושה בני אדם כאחד!\u0004","ומשיבים: \u0003לא קשיא\u0004, אין בכך סתירה, אלא, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו בברייתא שצריך לדעת שריפא כבר שלושה אנשים — הרי זה כדי \u0003למחויי גברא\u0004 \u0005[להוכיח מומחיות של האדם\u0006 כותב \u0005הקמיע\u0006\u0005],\u0006 שאחר שקמיעותיו הוכיחו את עצמם בריפוי בשלושה אנשים שונים שאף ודאי כל אחד לוקה בחולי אחר, ודאי שכותבם מומחה בכתיבת קמיעות. ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו בתוספתא שצריך לדעת שריפא אדם אחד שלוש פעמים — הרי זה כאשר רוצים \u0003למחויי\u0004 \u0005[ל\u0006הוכיח \u0005שמומחה]\u0006 \u0003קמיע\u0004 זה ומועיל למה שייעדוהו.","\u0003אמר רב פפא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי\u0004 במקרה שנכתבו \u0003תלת קמיע לתלת גברי תלתא תלתא זמני\u0004 \u0005[שלושה קמיעות לשלושה אנשים שלוש שלוש פעמים\u0006 לכל אחד\u0005]\u0006 והועילו — \u0003שאיתמחי גברא ואתמחי\u0004 \u0005[התמחה האדם והתמחה]\u0006 ה\u0003קמיע.\u0004 וכן פשוט לי שהכותב \u0003תלתא קמיע לתלתא גברי חד חד זימנא\u0004 \u0005[שלושה קמיעות לשלושה אנשים פעם אחת]\u0006 והועילו — \u0003גברא איתמחי\u0004 \u0005[האדם התמחה],\u0006 ואילו \u0003קמיעא\u0004 \u0005[\u0006ה\u0005קמיע]\u0006 \u0003לא איתמחי\u0004 \u0005[התמחה].\u0006 וכן כאשר כתב \u0003חד קמיע לתלתא גברי\u0004 \u0005[קמיע אחת לשלושה אנשים]\u0006 והועיל — \u0003הקמיע איתמחי\u0004 \u0005[התמחה]\u0006 ואילו \u0003גברא\u0004 \u0005[האדם]\u0006 הכותב \u0003לא איתמחי\u0004 \u0005[התמחה].\u0006","ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 כאשר כתב \u0003תלתא קמיע לחד גברא מאי\u0004 \u0005[שלושה קמיעות לאדם אחד מה]\u0006 יש לומר בכגון זה; ה\u0003קמיע ודאי לא איתמחי\u0004 \u0005[התמחה],\u0006 ואולם \u0003גברא איתמחי\u0004 \u0005[האדם\u0006 הכותב \u0005התמחה]\u0006 \u0003או לא איתמחי\u0004 \u0005[התמחה]?\u0006 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 שהאדם התמחה בכך שכן \u0003הא אסי ליה\u0004 \u0005[הרי\u0006 הקמיע שהוא כתב \u0005ריפא אותו]\u0006 את אותו חולה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר כי \u0003מזלא דהאי גברא\u0004 \u0005[המזל של אותו אדם\u0006 חולה\u0005]\u0006 \u0003הוא דקא\u0004 \u0005[שהוא]\u0006 \u0003מקבל\u0004 ומושפע מ\u0003כתבא\u0004 \u0005[\u0006מן \u0005הכתב],\u0006 אבל אדם אחר לא יתרפא. לשאלה זו לא נמצא פתרון ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לתלמידי הישיבה\u0005]\u0006 שאלה זו: \u0003קמיעין\u0004 האם \u0003יש בהן משום קדושה, או דילמא\u0004 \u0005[שמא]\u0006 \u0003אין בהן משום קדושה?\u0004 ושואלים: \u0003למאי הילכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 יש חשיבות בהכרעה זו? \u0003אילימא לאצולינהו\u0004 \u0005[אם תאמר ל\u0006ענין \u0005הצלתם]\u0006 \u0003מפני הדליקה,\u0004 אין הדבר יתכן, שכן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לכך ממה ששנינו: \u0003הברכות והקמיעין, אף על פי שיש בהן אותיות\u0004 של שמות קדושים \u0003ומענינות\u0004 (נושאים) \u0003הרבה שבתורה\u0004 — \u0003אין מצילין אותן מפני הדליקה, ונשרפים במקומן!\u0004","\u0003אלא\u0004 תאמר שנשאלה השאלה \u0003לענין גניזה,\u0004 אם יש צורך לגנוז את הקמיע שבלה, או שמותר להשליכו לאחר שימוש. ואולם אף לענין זה \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003היה\u0004 שם ה' \u0003כתוב,\u0004 אף \u0003על ידות הכלים ו\u0004אף \u0003על כרעי\u0004 (רגלי) \u0003המטה\u0004 — \u0003יגוד\u0004 (יקצוץ) את השם \u0003ויגנזנו,\u0004 הרי שמקפידים בגניזת שם בכל מקום שהוא כתוב בו!","\u0003אלא\u0004 יש לומר שנשאלה השאלה לענין \u0003ליכנס\u0004 (להכנס) \u0003בהן בבית הכסא, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם נאמר ש\u0003יש בהן קדושה, ואסיר\u0004 \u0005[ואסור],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אין בהן קדושה, ושרי\u0004 \u0005[מותר]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו ש\u0003לא\u0004 יצא אדם בשבת \u0003בקמיע בזמן שאינו מן המומחה,\u0004 ומדייקים מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם הוא \u0003מן המומחה\u0004 — \u0003נפיק\u0004 \u0005[יוצא]\u0006 בו,","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003קמיעין יש בהן משום קדושה, זמנין דמיצטריך\u0004 \u0005[לפעמים שמצטרך]\u0006 \u0003לבית הכסא\u0004 ויצטרך להסיר את הקמיע, \u0003ואתי לאיתויינהו\u0004 \u0005[ויבוא להביאם,\u0006 לטלטלם\u0005]\u0006 מתוך שכחה \u0003ארבע אמות ברשות הרבים.\u0004 ומאחר שאיננו חוששים לכך, נלמד שקמיעין אין בהם משום קדושה לענין זה ומותר להכנס בהם לבית הכסא! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בקמיע של עיקרין\u0004 (שרשים, עשבים) ובקמיע זו אין קדושה.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד קמיע של כתב ואחד קמיע של עיקרין\u0004 שווים לענין הלכה! \u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בחולה שיש בו סכנה,\u0004 ומשום הסכנה התירו לו להיכנס בקמיעו לבית הכסא, על אף ביזיון השם שבדבר. \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד חולה שיש בו סכנה ואחד חולה שאין בו סכנה\u0004 דינם שווה לענין זה.","\u0003אלא\u0004 יש לומר כי \u0003כיון דמסי\u0004 \u0005[שמרפא]\u0006 הקמיע, \u0003אף על גב דנקיט ליה בידיה\u0004 — \u0003נמי שפיר דמי\u0004 \u0005[אף על פי שמחזיקו בידו\u0006 — \u0005גם כן יפה הדבר,\u0006 מותר\u0005],\u0006 שכיון שלצורך הרפואה בו אין הבדל אם הקמיע תלוי בצוארו או נמצא בידו, על כן כשם שהתירו לענדו על צוארו בשבת, כך התירו לשאתו בידו."]]};
